KB.add({"board":"07","title":"文化遗产、民俗与传统常识","note":"交大考过：世界文化遗产、四大发明、天干地支、三书六礼、三姑六婆、礼仪、文曲星、屏风、发妻；选择题考过四大石窟、二十四节气、八大菜系、端午申遗、八里桥遗址、乌龙茶、句芒、屠苏、第一批世界遗产、第一个国家森林公园。这一板块题量稳定但很分散，表格速记效率最高。","clusters":[{"cid":"07a","name":"遗产保护体系：世界遗产与非遗","line":"联合国教科文组织两条公约分管两类遗产：1972年《保护世界文化和自然遗产公约》管有形遗产（中国1985年加入，1987年首批6项，2026年景德镇手工瓷业遗存为第61项），2003年《保护非物质文化遗产公约》管活态传承（端午2009年、春节2024年入选）；国内配套有非遗法、国家公园和“两创”方针。"},{"cid":"07b","name":"考古与文物：从良渚、二里头到殷墟、敦煌","line":"考古实证文明链条：良渚实证五千多年文明，二里头与八里桥指向夏，殷墟出甲骨文和后母戊鼎确证商，再到佛教东传后的四大石窟与敦煌藏经洞。"},{"cid":"07c","name":"名山名楼名园与古建","line":"名胜按“数字+名词”记：五岳定方位；四大名楼各配一篇名作（黄鹤楼崔颢、岳阳楼范仲淹、滕王阁王勃、鹳雀楼王之涣）；四大名园两座在苏州、两座是皇家园林；古桥、古塔、古都另成一组。"},{"cid":"07d","name":"天文历法：干支、节气、时辰与星神","line":"古人观日定节气（黄经每15度一个节气），观月定月份（农历是阴阳合历），用天干地支纪年月日时，地支又配生肖和十二时辰；星宿与时令神（文曲星、春神句芒）把天象和季节人格化。"},{"cid":"07e","name":"传统节日与民族风俗","line":"节日沿农历一年排开：春节饮屠苏、元宵赏灯、上巳修禊、清明扫墓、端午龙舟、七夕乞巧、中秋赏月、重阳登高；端午2009年成为首个入选人类非遗的中国节日，春节2024年入选；少数民族节庆与民歌另成一组。"},{"cid":"07f","name":"礼制与称谓：成年、婚丧、年龄与谦敬","line":"周公制礼，“三礼”奠定礼仪之邦；礼制落到人生各阶段：冠笄成年、三书六礼成婚、五服定丧服亲疏；称谓体系（年龄称谓、名字号、谦敬辞、三姑六婆）反映宗法伦理与社会分工。"},{"cid":"07g","name":"古代科技与中医","line":"四大发明（造纸、印刷、火药、指南针）是主干；科技典籍按朝代串：东汉《九章算术》、北魏《齐民要术》、北宋《梦溪笔谈》、明代《本草纲目》《天工开物》；中医由《黄帝内经》奠基，张仲景立辨证论治，直到屠呦呦青蒿素获诺奖。"},{"cid":"07h","name":"衣食器用与游艺：茶、菜、瓷、绣与棋","line":"物质文化按“吃、用、玩”记：六大茶类按发酵程度分，八大菜系按地域分；瓷器从唐代南青北白到宋代五大名窑再到瓷都景德镇；四大名绣、四大名砚；文人四艺琴棋书画中的围棋。"}],"entries":[{"id":"c-050","t":"甲骨四堂","cid":"07b","p":2,"kind":"合称","alias":["甲骨学四堂","罗王董郭"],"one":"罗振玉（雪堂）、王国维（观堂）、董作宾（彦堂）、郭沫若（鼎堂）。","ans":"甲骨四堂指**近代甲骨学研究的四位代表学者**：**罗振玉（号雪堂）、王国维（号观堂）、董作宾（字彦堂）、郭沫若（号鼎堂）**，因名号都带“堂”字而得名。罗振玉最早搜集、考释甲骨，著有《殷虚书契》；王国维用甲骨文与文献互证（二重证据法），考订殷商先公先王；董作宾提出甲骨文**分期断代**的方法，分为五期；郭沫若编纂《甲骨文合集》并以甲骨文研究商代社会。四人奠定了甲骨学的基础，使甲骨文成为研究商代历史的核心材料。","pts":["罗雪堂、王观堂、董彦堂、郭鼎堂","罗搜集考释，王二重证据，董分期，郭研究社会","奠定甲骨学基础"],"members":[["罗振玉","号雪堂，最早搜集考释甲骨"],["王国维","号观堂，二重证据法"],["董作宾","字彦堂，甲骨分期断代"],["郭沫若","号鼎堂，编《甲骨文合集》"]],"mem":"口诀“罗王董郭，雪观彦鼎”：罗雪、王观、董彦、郭鼎，两个口诀对齐背。一人一功：罗搜集，王互证，董分期，郭总编。","mix":"甲骨四堂不含王懿荣（甲骨文最早发现者）和刘鹗（《铁云藏龟》）；王国维也是清华国学研究院四大导师之一，“四大导师”与“甲骨四堂”是两个不同的组合；《甲骨文合集》由郭沫若主编、胡厚宣总编辑。","mcq":[{"q":"“甲骨四堂”中，号“观堂”的是","o":["罗振玉","董作宾","郭沫若","王国维"],"a":3,"w":"王国维号观堂；罗雪堂、董彦堂、郭鼎堂。"},{"q":"下列学者中，不属于“甲骨四堂”的是","o":["郭沫若","王国维","陈寅恪","董作宾"],"a":2,"w":"陈寅恪是清华国学研究院四大导师之一，不在四堂之列。"}],"rel":[{"t":"甲骨文","n":"研究对象"},{"t":"殷墟","n":"甲骨出土地"},{"t":"王国维","n":"观堂"},{"t":"郭沫若","n":"鼎堂"},{"t":"清华国学研究院四大导师","n":"王国维兼属"}],"more":"1899年王懿荣发现甲骨文；1928年殷墟开始科学发掘。\n罗振玉《殷虚书契》，王国维《殷卜辞中所见先公先王考》，董作宾《殷历谱》，郭沫若《卜辞通纂》《殷契粹编》。","exam":[]},{"id":"b06-048","t":"发妻","cid":"07f","p":3,"kind":"常识","exam":["2014名解"],"alias":["结发妻","结发夫妻","原配","正妻"],"one":"古代男子初婚行结发之礼所迎娶的第一任正配妻子，又称结发妻子。","ans":"发妻即**“结发妻子”，指男子初婚时明媒正娶的第一任正配夫人**。源于古代婚礼合髻之俗：**夫妇洞房各截一缕头发绾在一起**，象征恩爱不疑相守白头。在宗法礼制中，发妻**享有正统嫡妻地位**，远在妾室之上，受“三不去”律法严格保护。","pts":["男子初婚迎娶的第一任正配妻子（原配）","源于新婚合髻各截一发相绾的结发之礼","享有正统嫡妻地位，受宗法与三不去保护"],"mem":"诗句联想：“**结发为夫妻，恩爱两不疑**”，初婚断发相绾，相守白头。","mix":"发妻专指元配（原配），原配亡故后续娶之妻称为“继室”或“填房”，不可称为发妻；发妻享有嫡妻宗法特权，受“三不去”保护不可随意休弃。","mcq":[{"q":"在传统汉语与宗法伦理中，‘发妻’（结发妻子）专门用来指代","o":["男子纳娶的宠爱侍妾","男子初婚时迎娶的第一任正配妻子","原配亡故后明媒续娶的继室","订立婚约但尚未完婚的未婚妻"],"a":1,"w":"发妻指男子初婚时依照传统礼制迎娶的第一任正配妻子，源于新婚合髻结发之礼。"}],"rel":[{"t":"七出与三不去","n":"发妻受三不去律法保护"},{"t":"三书六礼","n":"明媒正娶结发成婚之礼"},{"t":"亲属雅称","n":"同属传统婚姻亲属称谓"}]},{"id":"b07-001","t":"世界文化遗产","cid":"07a","p":1,"kind":"概念","exam":["2016名解","2024选择"],"alias":["世界遗产","《世界遗产名录》","世界遗产名录"],"one":"联合国教科文组织依1972年公约列入名录、具突出普遍价值的文物、建筑群和遗址。","ans":"世界文化遗产是**联合国教科文组织依据1972年《保护世界文化和自然遗产公约》列入《世界遗产名录》、具有突出普遍价值的文物、建筑群和遗址**。世界遗产分**文化遗产、自然遗产、文化与自然混合遗产**三类，文化景观归入文化遗产，由世界遗产委员会审议列入，缔约国负有首要保护责任。**中国1985年加入公约，1987年长城、故宫、莫高窟、秦始皇陵及兵马俑坑、周口店北京人遗址、泰山首批入选**，2026年景德镇手工瓷业遗存入选后总数达61项。","pts":["教科文组织依1972年公约列入名录","文化、自然、混合三类，突出普遍价值","中国1985年加入，1987年首批六项"],"mem":"画面：1972年一张“遗产证书”，上面盖三个章：文化、自然、混合。数字挂钩：1972年公约（有形遗产），2003年公约（非遗），两个年份前后相差31年，别串。中国线：1985加入，1987首批，两年之隔，六项入选。","mix":"非物质文化遗产依据的是2003年《保护非物质文化遗产公约》，不是1972年公约；世界记忆名录管文献，也是另一套体系。","mcq":[{"q":"下列项目中，不属于1987年中国首批世界遗产的是","o":["秦始皇陵及兵马俑坑","周口店北京人遗址","泰山","布达拉宫"],"a":3,"w":"布达拉宫1994年列入；首批六项是长城、故宫、莫高窟、秦始皇陵及兵马俑坑、周口店北京人遗址、泰山。"},{"q":"中国加入《保护世界文化和自然遗产公约》的年份是","o":["1978年","1985年","1987年","1992年"],"a":1,"w":"中国1985年加入公约，1987年首批项目入选。"}],"rel":[{"t":"《保护世界文化和自然遗产公约》","n":"依据的1972年公约"},{"t":"中国首批世界遗产（1987年6项）","n":"中国首批六项"},{"t":"世界遗产类型","n":"文化、自然、混合"},{"t":"非物质文化遗产","n":"另一公约管活态遗产"},{"t":"中国近年新增世界遗产","n":"后续入选项目"}],"more":"2026年景德镇手工瓷业遗存入选，中国世界遗产总数达61项。"},{"id":"b07-002","t":"景德镇手工瓷业遗存","cid":"07a","p":1,"kind":"时事","alias":["景德镇世界遗产","景德镇申遗","景德镇御窑厂遗址"],"one":"2026年列入世界遗产，中国第61项，首个以产业遗产类型申报成功的项目。","ans":"景德镇手工瓷业遗存于**2026年7月25日在韩国釜山举行的联合国教科文组织第48届世界遗产大会**上列入《世界遗产名录》，使**中国世界遗产总数达到61项**。遗产位于江西东北部，由**镇区瓷业生产中心（含御窑厂窑址）、湖田古瓷窑址、高岭瓷土矿遗址、长岭瓷石矿遗址和蛟潭窑柴燃料产区**五部分组成，代表**10至19世纪景德镇手工制瓷的完整产业体系**。它是**中国第一个以产业遗产类型申报成功的项目**，填补了名录中“瓷”主题遗产的空白。","pts":["2026年7月釜山第48届大会列入，第61项","五部分：镇区、湖田窑、高岭、长岭、蛟潭","10至19世纪完整产业体系，首个产业遗产"],"mem":"按制瓷流程记五部分：挖瓷土（高岭）、取瓷石（长岭）、砍柴烧窑（蛟潭）、烧制（湖田古窑）、成品与官窑（镇区含御窑厂），一条生产线串起来。数字：61项，7月25日，釜山，第48届。","mix":"高岭土（kaolin）得名于景德镇高岭村；景德镇是“瓷都”，但“南青北白”的青瓷指越窑，白瓷指邢窑，与景德镇的青花、白瓷是不同概念。","mcq":[{"q":"2026年景德镇手工瓷业遗存列入世界遗产后，中国世界遗产总数达到","o":["59项","60项","61项","62项"],"a":2,"w":"该遗产是中国第61项世界遗产。"},{"q":"下列不属于景德镇手工瓷业遗存组成部分的是","o":["湖田古瓷窑址","高岭瓷土矿遗址","蛟潭窑柴燃料产区","耀州窑遗址"],"a":3,"w":"耀州窑在陕西铜川；景德镇遗存由镇区、湖田窑、高岭、长岭、蛟潭五部分组成。"}],"rel":[{"t":"青花瓷","n":"景德镇代表瓷种"},{"t":"南青北白","n":"唐代瓷业格局"},{"t":"中国近年新增世界遗产","n":"近年新增项目"},{"t":"世界文化遗产","n":"所属体系"},{"t":"《天工开物》","n":"记载制陶瓷工艺"}],"more":"遗产代表10至19世纪景德镇手工制瓷的完整产业体系。\n高岭土（kaolin）得名于当地高岭村。","exam":[]},{"id":"b07-003","t":"中国近年新增世界遗产","cid":"07a","p":2,"kind":"时事","alias":["新增世界遗产"],"one":"2024至2026年中国新增四项世界遗产，总数增至61项，最新一项是景德镇手工瓷业遗存。","ans":"中国近年新增世界遗产指**2024年至2026年列入《世界遗产名录》的四个项目**。2024年有**巴丹吉林沙漠—沙山湖泊群和北京中轴线**，后者为中国第**59**项；2025年**西夏陵**为第**60**项；2026年**景德镇手工瓷业遗存**为第**61**项。北京中轴线体现都城规划，西夏陵是党项王朝陵寝，景德镇遗存体现千年制瓷传统。中国世界遗产总数由1987年首批6项增至**61项**。","pts":["2024：巴丹吉林、北京中轴线（第59项）","2025：西夏陵（第60项）","2026：景德镇手工瓷业遗存（第61项）"],"mem":"数字随年份逐年加一：59中轴线，60西夏陵，61景德镇。三个“最新”各记一个关键词：中轴（2024）、西夏（2025）、瓷（2026）。","mix":"北京中轴线（2024）与1987年入选的故宫、长城是不同项目；西夏陵不要与宁夏的其他景点混淆，景德镇是“瓷业遗存”而非窑址单体。","mcq":[{"q":"2025年列入《世界遗产名录》的中国项目是","o":["北京中轴线","景德镇手工瓷业遗存","殷墟","西夏陵"],"a":3,"w":"西夏陵2025年列入，为中国第60项。"}],"rel":[{"t":"北京中轴线","n":"2024年入选，第59项"},{"t":"西夏陵","n":"2025年入选，第60项"},{"t":"景德镇手工瓷业遗存","n":"2026年入选，第61项"},{"t":"中国首批世界遗产（1987年6项）","n":"起点对照"},{"t":"世界文化遗产","n":"所属类别"}],"more":"2024年：巴丹吉林沙漠—沙山湖泊群；北京中轴线（第59项）\n2025年：西夏陵（第60项）\n2026年：景德镇手工瓷业遗存（第61项）","exam":[]},{"id":"b07-004","t":"非物质文化遗产","cid":"07a","p":1,"kind":"概念","alias":["非遗","人类非物质文化遗产","《保护非物质文化遗产公约》","非物质文化遗产公约"],"one":"世代相传、活态传承的社会实践与技能，依据2003年公约保护。","ans":"非物质文化遗产指**被各社区、群体或个人视为其文化遗产组成部分的各种社会实践、表现形式、知识、技能及相关的工具、实物和文化场所**，特点是**世代相传、活态传承**。联合国教科文组织于**2003年通过《保护非物质文化遗产公约》**，设人类非遗代表作名录、急需保护名录和优秀实践名册。中国2011年颁布**《非物质文化遗产法》**，昆曲、古琴、端午节、京剧、二十四节气、春节等已列入人类非遗代表作名录。它保护活态的文化实践，补足了1972年公约以有形遗产为主的体系。","pts":["世代相传、活态传承的实践与技能","2003年公约，三类名录","2011年非遗法；端午、春节等入选"],"mem":"“活”字抓牢：世界遗产是“物”（建筑、遗址），非遗是“人”（技艺、习俗、表演），人在传，遗产才活。年份口诀：物是1972，人是2003，国内法是2011。","mix":"1972年公约管文化与自然遗产，2003年公约管非遗；世界记忆名录管文献，三者不要混用。","mcq":[{"q":"《保护非物质文化遗产公约》通过的年份是","o":["1972年","2003年","2009年","2011年"],"a":1,"w":"公约2003年通过；1972年是《保护世界文化和自然遗产公约》；2011年是中国非遗法。"},{"q":"中国第一个列入人类非遗代表作名录的传统节日是","o":["春节","中秋节","清明节","端午节"],"a":3,"w":"端午节2009年入选；春节2024年入选。"}],"rel":[{"t":"人类非遗代表作中国项目","n":"中国入选项目汇总"},{"t":"国家级非物质文化遗产代表性项目名录","n":"国内名录体系"},{"t":"世界文化遗产","n":"有形遗产对照"},{"t":"端午节","n":"首个入选的节日"},{"t":"春节列入人类非遗代表作名录","n":"2024年入选"}],"more":"代表作名录中的中国项目示例：昆曲（2001年宣布）、古琴（2003）、端午节（2009）、京剧（2010）、二十四节气（2016）、春节（2024）。","exam":[]},{"id":"b07-005","t":"二十四节气","cid":"07d","p":1,"kind":"常识","exam":["2021选择"],"alias":["节气","24节气"],"one":"古人依太阳黄经每15度划分的24个节气，2016年列入人类非遗。","ans":"二十四节气是**中国古人通过观察太阳周年运动而形成的时间知识体系**，用来指导农事。它**按太阳在黄道上的位置划分，黄经每隔15度为一个节气，一年共24个**，从立春开始，到大寒结束。完整的二十四节气名称**最早见于西汉《淮南子·天文训》**。**2016年“二十四节气”列入联合国教科文组织人类非物质文化遗产代表作名录**，被誉为“中国的第五大发明”，至今仍影响农事与日常生活。","pts":["观测太阳周年运动的时间体系，指导农事","黄经每15度一个，立春起大寒止","《淮南子》完整记载，2016年入选人类非遗"],"mem":"通行节气歌：“春雨惊春清谷天，夏满芒夏暑相连，秋处露秋寒霜降，冬雪雪冬小大寒。”每季六个，每句四字对应四季首字。四立（立春立夏立秋立冬）是四季起点，二分二至是昼夜长短的转折。","mix":"节气按太阳（阳历）定，月份按月亮（农历）定，所以春节日期每年变而立春基本固定在2月4日前后；寒食不是节气。","mcq":[{"q":"二十四节气完整名称最早见于","o":["《吕氏春秋》","《礼记》","《周髀算经》","《淮南子》"],"a":3,"w":"西汉《淮南子·天文训》最早完整记载二十四节气。"},{"q":"下列不属于二十四节气的是","o":["惊蛰","小满","寒食","霜降"],"a":2,"w":"寒食是节日，不是节气；惊蛰、小满、霜降都是节气。"}],"rel":[{"t":"二十四节气中的“四立二分二至”","n":"节气中的关键八个"},{"t":"《淮南子》","n":"完整记载出处"},{"t":"七十二候","n":"节气的物候细分"},{"t":"天干地支","n":"同属历法系统"},{"t":"非物质文化遗产","n":"2016年入选"}],"more":"二十四节气2016年11月列入人类非遗代表作名录。\n春季：立春、雨水、惊蛰、春分、清明、谷雨。\n夏季：立夏、小满、芒种、夏至、小暑、大暑。\n秋季：立秋、处暑、白露、秋分、寒露、霜降。\n冬季：立冬、小雪、大雪、冬至、小寒、大寒。"},{"id":"b07-006","t":"天干地支","cid":"07d","p":1,"kind":"常识","exam":["2019名解"],"alias":["干支","六十甲子","干支纪年","甲子"],"one":"十天干配十二地支，组成六十甲子，用于纪年月日时。","ans":"天干地支简称“干支”，是**中国古代用于纪年、纪月、纪日、纪时的符号系统**。**天干十个：甲、乙、丙、丁、戊、己、庚、辛、壬、癸；地支十二个：子、丑、寅、卯、辰、巳、午、未、申、酉、戌、亥**。二者依次相配，**组成从甲子到癸亥的六十组，称“六十甲子”，循环使用**。商代甲骨文中已用干支纪日，地支还对应十二生肖和十二时辰，“甲午战争”“辛亥革命”即用干支纪年。","pts":["古代纪年月日时的符号系统","十天干、十二地支","配成六十甲子，对应生肖时辰"],"mem":"天干口诀“甲乙丙丁戊己庚辛壬癸”，地支口诀“子丑寅卯辰巳午未申酉戌亥”，生肖依次“鼠牛虎兔龙蛇马羊猴鸡狗猪”。算法：天干10、地支12，最小公倍数60，所以60年一轮回，这就是“花甲”和“还历”的来历。","mix":"子时是23点至1点，不是0点到2点；干支纪年只管年份循环，不能直接定出公元年，需记几个锚点：甲午1894、戊戌1898、辛亥1911。","mcq":[{"q":"下列属于十天干的一组是","o":["子、丑、寅、卯","甲、乙、丙、丁","辰、巳、午、未","申、酉、戌、亥"],"a":1,"w":"甲乙丙丁是天干，其余三组均是地支。"},{"q":"十二时辰中，子时指","o":["21点至23点","1点至3点","23点至次日1点","11点至13点"],"a":2,"w":"子时为23点至次日1点，午时为11点至13点。"}],"rel":[{"t":"十二生肖","n":"与地支相配"},{"t":"十二时辰","n":"地支纪时"},{"t":"干支纪年与历史事件","n":"甲午、辛亥等"},{"t":"农历","n":"同属传统历法"},{"t":"《易经》（《周易》）","n":"2019同组名解"}],"more":"2019同组名解：易经、卜筮。"},{"id":"b07-007","t":"三书六礼","cid":"07f","p":1,"kind":"制度","exam":["2021名解"],"alias":["六礼","三书","纳采问名纳吉纳征请期亲迎"],"one":"古代婚姻礼仪程序：三书（聘书、礼书、迎书）与六礼。","ans":"三书六礼是**中国古代传统婚姻的礼仪程序**。**“三书”指聘书（订亲文书）、礼书（过大礼时的礼品清单）、迎书（迎娶新娘的文书）**。**“六礼”指纳采（提亲）、问名（问女方姓名和生辰）、纳吉（占卜吉兆后订婚）、纳征（送聘礼）、请期（择定婚期）、亲迎（迎娶）**，最早系统记载于《仪礼·士昏礼》《礼记·昏义》。它体现了古代婚姻“父母之命，媒妁之言”的礼制特征，部分习俗沿用至今。","pts":["古代婚姻礼仪程序","三书：聘书、礼书、迎书","六礼：纳采到亲迎，见《仪礼》"],"members":[["纳采","提亲，男方送礼求婚"],["问名","问女方姓名、生辰"],["纳吉","占卜得吉后订婚"],["纳征","送聘礼，俗称过大礼"],["请期","择定婚期"],["亲迎","新郎迎娶新娘"]],"mem":"六礼按婚事推进的顺序背，首字“采名吉征期迎”，可编成“采名吉，征期迎”：先提亲、问名字、卜吉凶，再送聘礼、定日子、迎新娘。三书对应“订亲、送礼、迎娶”三个节点：聘书、礼书、迎书。","mix":"“纳征”才是下聘礼（过大礼），“纳采”是提亲；合卺（交杯酒）是婚礼环节，不属于六礼。","mcq":[{"q":"“六礼”中，俗称“过大礼”的是","o":["纳采","纳吉","纳征","亲迎"],"a":2,"w":"纳征即送聘礼，俗称过大礼。"},{"q":"下列不属于“六礼”的是","o":["问名","请期","合卺","亲迎"],"a":2,"w":"合卺指婚礼上的交杯酒，不在六礼之内。"}],"rel":[{"t":"三礼","n":"六礼见于《仪礼》"},{"t":"礼仪","n":"上位概念"},{"t":"冠礼与笄礼","n":"人生礼仪"},{"t":"五服","n":"婚丧礼制并称"}],"more":"六礼最早系统记载于《仪礼·士昏礼》《礼记·昏义》。"},{"id":"b07-008","t":"三姑六婆","cid":"07f","p":1,"kind":"合称","exam":["2022名解"],"alias":["三姑","六婆"],"one":"元代《南村辍耕录》所记九类职业女性，后泛指搬弄是非的妇女。","ans":"三姑六婆是**中国古代对民间从事特定职业的女性的统称**，出自**元代陶宗仪《南村辍耕录》**。**“三姑”指尼姑、道姑、卦姑（占卜者）；“六婆”指牙婆（人口买卖中介）、媒婆、师婆（巫婆）、虔婆（鸨母）、药婆、稳婆（接生婆）**。她们常出入人家，旧时被视为不安分的人，故此词**后来带有贬义，泛指搬弄是非、不务正业的妇女**。它反映了古代社会的职业分工与性别观念。","pts":["元代陶宗仪《南村辍耕录》","三姑：尼、道、卦；六婆：牙媒师虔药稳","后来泛指搬弄是非的妇女，含贬义"],"members":[["尼姑","三姑，佛教女性出家人"],["道姑","三姑，道教女性出家人"],["卦姑","三姑，占卜者"],["牙婆","六婆，人口买卖中介"],["媒婆","六婆，说媒"],["师婆","六婆，巫婆"],["虔婆","六婆，鸨母"],["药婆","六婆，卖药行医"],["稳婆","六婆，接生婆"]],"mem":"三姑记“尼道卦”（两教加一卦），六婆首字“牙媒师虔药稳”，可谐音“牙媒师，前药稳”。分类线索：宗教三种姑，买卖、说媒、巫、鸨、医、接生六种婆。","mix":"2022同组名解还有《孽海花》或《镜花缘》（女性题材）；“三姑六婆”今天多作贬义，原义是中性的职业列举。","mcq":[{"q":"下列不属于“六婆”的是","o":["媒婆","稳婆","卦姑","药婆"],"a":2,"w":"卦姑属“三姑”，六婆是牙婆、媒婆、师婆、虔婆、药婆、稳婆。"},{"q":"“三姑六婆”一词出自","o":["《梦溪笔谈》","《南村辍耕录》","《容斋随笔》","《酉阳杂俎》"],"a":1,"w":"元代陶宗仪《南村辍耕录》。"}],"rel":[{"t":"《镜花缘》","n":"2022同组名解，女性题材"},{"t":"《孽海花》","n":"2022同组名解"},{"t":"三教九流","n":"同类职业分类词"},{"t":"《红楼梦》人物与情节","n":"书中常见此类人物"}],"more":"元代陶宗仪《南村辍耕录》：三姑者，尼姑、道姑、卦姑也；六婆者，牙婆、媒婆、师婆、虔婆、药婆、稳婆也。"},{"id":"b07-009","t":"四大发明","cid":"07g","p":1,"kind":"合称","exam":["2015名解"],"alias":["造纸术、印刷术、火药、指南针"],"one":"造纸术、印刷术、火药、指南针，中国古代对世界的重大贡献。","ans":"四大发明指**中国古代的造纸术、印刷术、火药和指南针**。**东汉蔡伦改进造纸术；唐代出现雕版印刷，北宋毕昇发明活字印刷，事见沈括《梦溪笔谈》；火药源于唐代炼丹家的实验，宋代用于军事；战国时已有“司南”，北宋指南针用于航海**。四大发明经阿拉伯传入欧洲，**对文艺复兴、宗教改革、航海大发现和资本主义的兴起产生了深远影响**，是中国对世界文明的重要贡献。","pts":["造纸术、印刷术、火药、指南针","蔡伦、毕昇活字、炼丹、司南","西传欧洲，推动近代社会变革"],"members":[["造纸术","东汉蔡伦改进"],["印刷术","唐代雕版，北宋毕昇活字，见《梦溪笔谈》"],["火药","唐代炼丹家，宋代用于军事"],["指南针","战国司南，北宋用于航海"]],"mem":"一句话：纸写字、印印书、药炸城、针指路，四个发明对应“记录、传播、战争、航海”。人名配对：蔡伦—纸，毕昇—活字，炼丹家—火药，司南—指南针，其中只有活字有明确发明者毕昇，见沈括《梦溪笔谈》。","mix":"现存最早有明确纪年的雕版印刷品是唐代《金刚经》（868年，敦煌出土）；“新四大发明”（高铁、扫码支付、共享单车、网购）是现代说法，不要混用；毕昇发明的是活字，不是印刷术本身。","mcq":[{"q":"下列不属于四大发明的是","o":["造纸术","火药","瓷器","指南针"],"a":2,"w":"四大发明是造纸术、印刷术、火药、指南针；瓷器不在其列。"},{"q":"北宋发明活字印刷术的是","o":["蔡伦","沈括","宋应星","毕昇"],"a":3,"w":"毕昇发明活字印刷，记载在沈括《梦溪笔谈》中。"}],"rel":[{"t":"造纸术","n":"四大发明之一"},{"t":"印刷术","n":"四大发明之一"},{"t":"火药","n":"四大发明之一"},{"t":"指南针","n":"四大发明之一"},{"t":"古登堡印刷术","n":"欧洲印刷术对照"}],"more":"唐代《金刚经》（868年）是现存最早有明确纪年的雕版印刷品，敦煌出土。\n马克思评价：火药、指南针、印刷术是预告资产阶级社会到来的三大发明。"},{"id":"b07-010","t":"中国四大石窟","cid":"07b","p":1,"kind":"合称","exam":["2010选择"],"alias":["四大石窟","莫高窟","云冈石窟","龙门石窟","麦积山石窟"],"one":"敦煌莫高窟、大同云冈、洛阳龙门、天水麦积山四处佛教石窟。","ans":"中国四大石窟指**甘肃敦煌莫高窟、山西大同云冈石窟、河南洛阳龙门石窟和甘肃天水麦积山石窟**，是佛教传入后形成的石窟艺术代表。**莫高窟始凿于前秦，以壁画和彩塑著称，藏经洞出土大量文书；云冈石窟开凿于北魏，以早期大型造像闻名；龙门石窟始于北魏孝文帝迁都洛阳后，盛于唐，卢舍那大佛最著名；麦积山石窟以泥塑见长**。莫高窟、龙门、云冈分别于1987、2000、2001年列入世界遗产，麦积山作为丝绸之路一部分列入。它们体现了佛教艺术的中国化和中外交流。","pts":["莫高窟、云冈、龙门、麦积山","壁画彩塑、早期大像、卢舍那、泥塑","世界遗产，佛教艺术中国化与中外交流"],"members":[["莫高窟","甘肃敦煌，前秦始凿，壁画彩塑，藏经洞，1987年入选"],["云冈石窟","山西大同，北魏，昙曜五窟，犍陀罗风格，2001年入选"],["龙门石窟","河南洛阳，北魏孝文帝迁洛后开凿，卢舍那大佛，2000年入选"],["麦积山石窟","甘肃天水，后秦始凿，泥塑，东方雕塑陈列馆"]],"mem":"地点口诀“敦（莫高）、同（云冈）、洛（龙门）、水（麦积山）”，甘肃占两个（敦煌、天水），山西一个，河南一个。特色配对：莫高画、云冈大、龙门佛（卢舍那）、麦积泥。","mix":"莫高窟和麦积山都在甘肃，云冈在山西，龙门在河南；大足石刻、炳灵寺不属于四大石窟，常作干扰项。卢舍那大佛在龙门，不在云冈。","mcq":[{"q":"“昙曜五窟”是下列哪处石窟的早期代表","o":["莫高窟","龙门石窟","云冈石窟","麦积山石窟"],"a":2,"w":"昙曜五窟开凿于北魏，在山西大同云冈石窟。"},{"q":"卢舍那大佛所在的石窟是","o":["龙门石窟","云冈石窟","麦积山石窟","莫高窟"],"a":0,"w":"卢舍那大佛是河南洛阳龙门石窟的代表，唐代武则天时期完成。"}],"rel":[{"t":"敦煌藏经洞","n":"莫高窟出土文书"},{"t":"敦煌壁画","n":"莫高窟艺术核心"},{"t":"大足石刻","n":"常作干扰项"},{"t":"世界文化遗产","n":"三窟入选名录"},{"t":"丝绸之路","n":"麦积山属其组成部分"}],"more":"莫高窟始凿于前秦建元二年（366年）。\n龙门石窟奉先寺卢舍那大佛造于唐高宗时期，武则天曾助脂粉钱。"},{"id":"b07-011","t":"端午节","cid":"07e","p":1,"kind":"常识","exam":["2025选择"],"alias":["端五","重五","端阳节","龙舟节","中国端午节"],"one":"农历五月初五，纪念屈原，2009年成为首个入选人类非遗的中国节日。","ans":"端午节在**农历五月初五**，“端”是开头，“午”与“五”相通，又称端五、重五。其起源与夏季驱疫避毒的习俗有关，**后世主要纪念战国诗人屈原**，另有纪念伍子胥、曹娥等说法。习俗有**赛龙舟、吃粽子、挂艾草菖蒲、饮雄黄酒、佩香囊**。**2009年“中国端午节”列入人类非物质文化遗产代表作名录，是中国第一个入选的传统节日**；2008年起成为国家法定节假日。","pts":["农历五月初五，纪念屈原","赛龙舟、吃粽子、挂艾草、饮雄黄酒","2009年入选人类非遗，首个中国节日"],"mem":"“端午”三步记：五月五，“午”与“五”通，赛龙舟的目的是“救屈原”，粽子是“投江喂鱼”的祭品。年份：2008年放假，2009年申遗，春节要等到2024年。","mix":"屈原纪念不限于端午；寒食纪念介子推，七夕与牛郎织女相关，中元是七月十五，重阳登高；干扰项里常把“放河灯”（中元）混入端午。","mcq":[{"q":"中国第一个列入人类非遗代表作名录的传统节日是","o":["春节","中秋节","端午节","清明节"],"a":2,"w":"端午节2009年入选，春节2024年入选。"},{"q":"下列习俗属于端午节的是","o":["插茱萸","放河灯","踏青扫墓","赛龙舟"],"a":3,"w":"赛龙舟是端午习俗；插茱萸是重阳，踏青扫墓是清明，放河灯多在中元。"}],"rel":[{"t":"屈原","n":"主要纪念对象"},{"t":"春节列入人类非遗代表作名录","n":"后来入选的节日"},{"t":"非物质文化遗产","n":"所属遗产类型"},{"t":"节令酒与节令食","n":"粽子、雄黄酒"},{"t":"中国传统四大节日","n":"传统节日并称"}],"more":"2008年起成为国家法定节假日。"},{"id":"b07-012","t":"八里桥遗址","cid":"07b","p":2,"kind":"地理","exam":["2025选择"],"alias":["八里桥"],"one":"河南方城县的夏代文化遗址。","ans":"八里桥遗址位于**河南省方城县**，是一处**夏代文化遗址**，属于探索夏文化的考古遗存。夏是中国史上第一个王朝，**夏商周断代工程（1996至2000年）**把夏代年代定为约前2070至前1600年。夏文化的核心线索是**河南偃师二里头遗址**，多数学者视为夏代中晚期都城，八里桥遗址同为河南境内的夏代遗存。这类遗址为“夏”提供实物证据，补充文献记载。","pts":["河南方城县的夏代遗址","夏约前2070至前1600年","与二里头遗址同指向夏文化"],"mem":"带“里”的两处都指向夏：八里桥、二里头；带“殷”的指向商：殷墟。","mix":"干扰项常设为商（殷墟）、仰韶或西周；二里头在偃师，八里桥在方城，不要互换地名。","mcq":[{"q":"河南方城八里桥遗址属于哪一时期的文化遗址","o":["仰韶文化","夏代","商代","西周"],"a":1,"w":"八里桥遗址属夏代文化遗址。"}],"rel":[{"t":"夏文化","n":"所属文化"},{"t":"二里头遗址","n":"夏文化核心遗址"},{"t":"夏朝","n":"对应王朝"},{"t":"殷墟","n":"商代遗址对照"}]},{"id":"b07-013","t":"屠苏","cid":"07e","p":1,"kind":"常识","exam":["2026选择"],"alias":["屠苏酒"],"one":"古代农历正月初一饮用的药酒，王安石《元日》“春风送暖入屠苏”。","ans":"屠苏是**古代农历正月初一饮用的药酒**，又称屠苏酒，用多种药材浸泡而成，旧俗认为饮后可**驱邪辟疫、祝愿新岁安康**。饮用时按**年龄由小到大**依次，与平常敬酒先老后少的顺序相反，苏辙《除日》有“年年最后饮屠苏”之句，写自己年老。北宋王安石《元日》“爆竹声中一岁除，**春风送暖入屠苏**”即写此俗，是春节诗词中流传最广的名句之一。它与椒柏酒同属春节的节令饮品，与食物、房屋无关。","pts":["正月初一饮的药酒，辟邪祈安","按年龄由小到大饮用","王安石《元日》“春风送暖入屠苏”"],"mem":"画面：除夕守岁，爆竹响过，一家人围桌，最小的孩子先端起屠苏酒。名句记全：“爆竹声中一岁除，春风送暖入屠苏。千门万户曈曈日，总把新桃换旧符。”前两句有爆竹和酒，后两句有春联（桃符）。","mix":"2026选择的干扰项里有食物和房屋，屠苏是酒；“屠苏”在个别古籍中另指草庵，但考点指屠苏酒。","mcq":[{"q":"“春风送暖入屠苏”中的“屠苏”是指","o":["一种点心","一种药酒","一种房屋","一种乐器"],"a":1,"w":"屠苏是春节饮用的药酒。"},{"q":"“爆竹声中一岁除，春风送暖入屠苏”出自","o":["王安石《元日》","杜牧《清明》","王维《九月九日忆山东兄弟》","苏轼《水调歌头》"],"a":0,"w":"《元日》为王安石写春节的名篇。"}],"rel":[{"t":"节令酒与节令食","n":"同类节令饮品"},{"t":"春节列入人类非遗代表作名录","n":"春节习俗"},{"t":"王安石","n":"《元日》作者"},{"t":"七夕节","n":"其他节令诗词"}],"more":"元日｜王安石\n爆竹声中一岁除，春风送暖入屠苏。千门万户曈曈日，总把新桃换旧符。"},{"id":"b07-014","t":"句芒","cid":"07d","p":2,"kind":"常识","exam":["2024选择"],"alias":["春神句芒","木神句芒"],"one":"古代神话中的木神、春神，主管树木生长，居东方。","ans":"句芒是**中国古代神话中的木神和春神**，主管树木发芽生长，**居东方**，与五行中的木、四季中的春相配。《山海经》描写他“**鸟身人面，乘两龙**”，《礼记·月令》载春季“其帝太皞，其神句芒”。在**五方神**体系中，**春神句芒、夏神祝融、秋神蓐收、冬神玄冥**分管四时，中央为后土。句芒体现古人把季节人格化、按方位配五行的观念。","pts":["木神、春神，居东方","鸟身人面，乘两龙","春句芒、夏祝融、秋蓐收、冬玄冥"],"mem":"口诀“春句夏祝秋蓐冬玄”。联想：句芒是春天里发芽的“芒”，木、春、东、青四个字对在一起。","mix":"祝融是夏神、火神，蓐收是秋神，玄冥是冬神，后土居中；句芒不是太阳神，也不是土神。","mcq":[{"q":"中国古代神话中的春神是","o":["祝融","句芒","蓐收","玄冥"],"a":1,"w":"句芒为春神、木神；祝融夏神，蓐收秋神，玄冥冬神。"}],"rel":[{"t":"五方神（四时之神）","n":"同组神祇"},{"t":"中国古代神话","n":"所属神话体系"},{"t":"五行","n":"木对应春与东方"},{"t":"二十四节气","n":"立春迎春的民俗背景"}]},{"id":"b07-015","t":"八大菜系","cid":"07h","p":1,"kind":"合称","exam":["2021选择"],"alias":["中国八大菜系","鲁川粤苏闽浙湘徽"],"one":"鲁、川、粤、苏、闽、浙、湘、徽八大地方菜系。","ans":"八大菜系是**中国地方风味菜的八个代表流派**，即**鲁菜、川菜、粤菜、苏菜、闽菜、浙菜、湘菜、徽菜**，其中鲁、川、粤、苏又称四大菜系。它们在漫长的饮食文化中逐渐形成，按**地域物产、气候和口味**区分：鲁菜擅长爆炒、重咸鲜，川菜以麻辣见长，粤菜重鲜嫩，苏菜讲究刀工和原汁，闽菜善做汤，浙菜清鲜，湘菜香辣，徽菜重烧炖。八大菜系体现了中国饮食文化的地域多样性。","pts":["鲁川粤苏闽浙湘徽","四大菜系为鲁川粤苏","按地域物产与口味分，风味各异"],"members":[["鲁菜","山东，咸鲜，九转大肠"],["川菜","四川，麻辣，麻婆豆腐"],["粤菜","广东，鲜嫩，白切鸡"],["苏菜","江苏，重刀工，松鼠鳜鱼"],["闽菜","福建，善做汤，佛跳墙"],["浙菜","浙江，清鲜，西湖醋鱼"],["湘菜","湖南，香辣，剁椒鱼头"],["徽菜","安徽，重烧炖，臭鳜鱼"]],"mem":"通行顺序“鲁川粤苏闽浙湘徽”，前四个就是四大菜系。省份对应：山东（鲁）、四川（川）、广东（粤）、江苏（苏）、福建（闽）、浙江（浙）、湖南（湘）、安徽（徽），都是各省简称，背省简称就背会了。","mix":"京菜、沪菜（本帮菜）、淮扬菜不在“八大”之列，淮扬菜属苏菜；“四大菜系”与“八大菜系”是不同层级。","mcq":[{"q":"下列不属于“八大菜系”的是","o":["鲁菜","徽菜","京菜","湘菜"],"a":2,"w":"八大菜系是鲁、川、粤、苏、闽、浙、湘、徽，京菜不在其中。"},{"q":"以“佛跳墙”闻名的菜系是","o":["粤菜","浙菜","徽菜","闽菜"],"a":3,"w":"佛跳墙是闽菜名菜。"}],"rel":[{"t":"四大菜系","n":"八大中的前四"},{"t":"六大茶类","n":"饮食文化并列知识"},{"t":"中国十大名茶","n":"同属衣食器用"},{"t":"中国传统制茶技艺及其相关习俗","n":"饮食类非遗"}],"more":"四大菜系：鲁、川、粤、苏。"},{"id":"b07-016","t":"乌龙茶","cid":"07h","p":1,"kind":"常识","exam":["2025选择"],"alias":["青茶","铁观音","大红袍","冻顶乌龙"],"one":"又称青茶，半发酵茶，代表铁观音、大红袍。","ans":"乌龙茶又称**青茶**，是**介于绿茶与红茶之间的半发酵茶**，加工需经萎凋、摇青、杀青、揉捻、烘干，叶片边缘红、中心绿，有“**绿叶红镶边**”之称。主产**福建、广东、台湾**：福建有**安溪铁观音**和**武夷岩茶（大红袍）**，广东有凤凰单丛，台湾有冻顶乌龙。乌龙茶兼有绿茶的清香与红茶的醇厚，是六大茶类中工艺较复杂的一类。","pts":["青茶，半发酵，绿叶红镶边","铁观音、大红袍、冻顶乌龙","主产福建、广东、台湾"],"mem":"发酵程度坐标：绿茶不发酵、红茶全发酵，乌龙在正中间，所以叫“半发酵”。名字就是“青茶”，别想成“黑茶”。三个代表茶对三个地方：铁观音（福建安溪）、大红袍（福建武夷山）、冻顶乌龙（台湾）。","mix":"乌龙茶=青茶，不是黑茶；黑茶是后发酵（普洱熟茶、安化黑茶）；红茶是全发酵（祁门红茶、正山小种）；君山银针属黄茶。","mcq":[{"q":"乌龙茶在六大茶类中又称","o":["青茶","黄茶","白茶","黑茶"],"a":0,"w":"乌龙茶就是青茶，属半发酵茶。"},{"q":"下列茶叶中，属于乌龙茶的是","o":["祁门红茶","君山银针","西湖龙井","武夷大红袍"],"a":3,"w":"大红袍是武夷岩茶，属乌龙茶；祁门是红茶，君山银针是黄茶，龙井是绿茶。"}],"rel":[{"t":"六大茶类","n":"所属分类"},{"t":"中国十大名茶","n":"铁观音、大红袍"},{"t":"中国传统制茶技艺及其相关习俗","n":"茶类非遗"},{"t":"陆羽《茶经》","n":"茶文化典籍"}],"more":"工艺：萎凋、摇青（做青）、杀青、揉捻、烘干。"},{"id":"b07-017","t":"张家界国家森林公园","cid":"07a","p":2,"kind":"地理","exam":["2023选择"],"alias":["张家界","武陵源"],"one":"1982年设立的中国第一个国家森林公园，位于湖南张家界。","ans":"张家界国家森林公园位于**湖南省张家界市**，**1982年设立，是中国第一个国家森林公园**。景区以**石英砂岩峰林地貌**闻名，数以千计的石峰拔地而起，是武陵源风景名胜区的核心。1992年武陵源以张家界为主体列入**世界自然遗产**。它在国家森林公园序列中居首，是中国自然景观类世界遗产的代表。“第一个国家森林公园”与2021年设立的**国家公园**分属两个体系。","pts":["1982年设立，中国第一个国家森林公园","位于湖南，石英砂岩峰林","1992年武陵源列入世界自然遗产"],"mem":"年份对比：“八二”张家界（森林公园），“二一”国家公园（三江源等），两个“第一”相隔39年。地名画面：张家界的石峰像一排排竖起的柱子。","mix":"国家森林公园（1982，张家界）与国家公园（2021，三江源等五个）是不同制度；选择题常把“第一个国家森林公园”误设为黄山、庐山、神农架。","mcq":[{"q":"中国第一个国家森林公园是","o":["黄山国家森林公园","张家界国家森林公园","庐山国家森林公园","神农架国家森林公园"],"a":1,"w":"1982年设立，位于湖南。"}],"rel":[{"t":"中国第一个国家公园","n":"体系不同，常被对举"},{"t":"世界遗产类型","n":"武陵源属自然遗产"},{"t":"中国文化与自然双遗产","n":"对照：张家界并非双遗产"}],"more":"1982年：设立，中国第一个国家森林公园\n1992年：武陵源列入世界自然遗产"},{"id":"b07-018","t":"殷墟","cid":"07b","p":1,"kind":"地理","alias":["殷墟遗址","安阳殷墟","殷都"],"one":"河南安阳商代后期都城遗址，出甲骨文和后母戊鼎，2006年入遗。","ans":"殷墟是**商代后期的都城遗址**，位于**河南安阳**，自盘庚迁殷到商亡共约273年。1928年起由中央研究院历史语言研究所主持科学发掘，出土**甲骨文**和**后母戊鼎**，发掘出宫殿宗庙区、王陵区和**妇好墓**。殷墟出土的文字与青铜器**证实了商朝的存在**，使商代成为有文字可征的信史时期。**2006年列入世界遗产名录**，是中国考古学和商史研究的重要基地。","pts":["商代后期都城，河南安阳","出土甲骨文、后母戊鼎、妇好墓","2006年入遗，证实商朝信史"],"mem":"“殷”字线索：盘庚迁殷，所以叫殷商；殷墟就是“殷的废墟”。三件宝一句话：甲骨文记事，鼎铸国力，妇好墓见女将。年份：1899发现甲骨，1928开始发掘，2006入遗。","mix":"二里头遗址在河南偃师，指向夏文化；殷墟在安阳，对应商。甲骨文最早发现于1899年，殷墟发掘始于1928年，两者不同。","mcq":[{"q":"殷墟位于今天的","o":["河南洛阳","河南偃师","河南安阳","陕西西安"],"a":2,"w":"殷墟在河南安阳，二里头在偃师。"},{"q":"殷墟列入世界遗产名录的年份是","o":["1987年","2006年","2012年","2019年"],"a":1,"w":"殷墟2006年入选，良渚2019年入选。"}],"rel":[{"t":"甲骨文","n":"殷墟出土文字"},{"t":"后母戊鼎","n":"殷墟出土重器"},{"t":"商朝与盘庚迁殷","n":"都城来历"},{"t":"二里头遗址","n":"夏文化对照"},{"t":"良渚古城遗址","n":"早于殷墟的文明实证"}],"more":"殷墟1928年起科学发掘；1976年发掘妇好墓。","exam":[]},{"id":"b07-019","t":"甲骨文","cid":"07b","p":1,"kind":"概念","alias":["殷墟文字","卜辞","契文","殷墟甲骨文"],"one":"商代刻在龟甲、兽骨上的文字，现存最早的成熟汉字系统。","ans":"甲骨文是**商代后期刻写在龟甲和兽骨上的文字**，内容多为占卜记录，故又称卜辞、殷墟文字。**1899年金石学家王懿荣**在中药“龙骨”上发现刻痕，主要出土于**河南安阳殷墟**。甲骨文单字约4500个，已释读约1500字，是**现存最早的成熟汉字系统**，已具备象形、指事、会意、形声等造字方法。它为商代历史提供第一手文字证据，罗振玉、王国维、董作宾、郭沫若的研究形成甲骨学，有“甲骨四堂”之称。","pts":["商代刻于龟甲兽骨，多为占卜","1899年王懿荣发现，出自安阳殷墟","现存最早成熟汉字，甲骨学"],"mem":"故事记忆：王懿荣生病抓药，发现中药“龙骨”上有字，一味药引出一门学问。“甲骨四堂”用号记：雪堂罗振玉、观堂王国维、彦堂董作宾、鼎堂郭沫若。","mix":"甲骨文是商代文字，金文（钟鼎文）主要在商周青铜器上；小篆是秦统一后的文字；“最早的成熟汉字系统”指甲骨文，不是更早的刻划符号。","mcq":[{"q":"1899年最早发现甲骨文的是","o":["罗振玉","王国维","郭沫若","王懿荣"],"a":3,"w":"清末金石学家王懿荣在“龙骨”上发现刻痕。"},{"q":"下列学者中，不属于“甲骨四堂”的是","o":["罗振玉","王国维","胡适","郭沫若"],"a":2,"w":"甲骨四堂是罗振玉、王国维、董作宾、郭沫若；胡适不在其列。"}],"rel":[{"t":"殷墟","n":"主要出土地"},{"t":"甲骨四堂","n":"甲骨学四位大家"},{"t":"后母戊鼎","n":"殷墟另一重器"},{"t":"六书","n":"造字方法"},{"t":"商朝与盘庚迁殷","n":"所属时代"}],"more":"2017年《殷墟甲骨文》入选世界记忆名录。","exam":[]},{"id":"b07-020","t":"文曲星","cid":"07d","p":2,"kind":"常识","exam":["2013名解"],"alias":["文曲","文曲星下凡"],"one":"北斗第四星，传说主管文运，称才子或状元为“文曲星下凡”。","ans":"文曲星是**中国传统星宿名**，旧说为**北斗七星的第四星**，民间视为**主管文运的星神**。古人把才华出众或科举夺魁的人称作“**文曲星下凡**”，戏曲和小说中的包拯即被写成文曲星转世。与它并称的有**文昌星（文昌帝君）**和**魁星**，同属科举文化中的文运之神。文曲星把天象人格化，体现古人对读书与功名的崇拜，今天仍用来形容才子。","pts":["北斗第四星，主文运","才子、状元称“文曲星下凡”","与文昌、魁星同属科举神"],"mem":"北斗“文武”对：文曲第四、武曲第六。画面：魁星一脚踢斗，点中状元；文曲、文昌、魁星三位都管读书。","mix":"文昌帝君主文昌，魁星主科甲名次，武曲星主武运；“文曲”“文昌”常被互换。","mcq":[{"q":"民间称才华出众、考中状元的人为","o":["武曲星下凡","紫微星下凡","太白金星下凡","文曲星下凡"],"a":3,"w":"文曲星主文运，故称“文曲星下凡”。"}],"rel":[{"t":"北斗七星","n":"文曲所属星官"},{"t":"二十八宿","n":"星官体系对照"},{"t":"莫言","n":"2013名解同组"},{"t":"中国古代神话","n":"星神的神话背景"}]},{"id":"b07-021","t":"礼仪","cid":"07f","p":1,"kind":"概念","exam":["2016名解"],"alias":["礼仪之邦","周公制礼","制礼作乐"],"one":"古代规范人际与社会秩序的礼节仪式，周公制礼，“三礼”为典籍。","ans":"礼仪是**中国古代规范人际交往与社会秩序的礼节和仪式制度**，“礼”是原则规范，“仪”是外在仪节。中国素称**“礼仪之邦”**，相传**周公制礼作乐**，确立了周代礼制。礼仪涵盖**吉、凶、军、宾、嘉五礼**，记录礼制的**《周礼》《仪礼》《礼记》合称“三礼”**，《礼记·中庸》有“礼仪三百，威仪三千”之说。孔子强调“不学礼，无以立”，礼仪由此成为儒家**修身治国**的核心，并渗透到冠婚丧祭等人生各阶段。","pts":["古代规范交往与秩序的礼节仪式","周公制礼，礼仪之邦","三礼典籍，五礼，儒家修身治国"],"mem":"一条线：周公制礼作乐（源头）→三礼成书（《周礼》讲官制、《仪礼》讲仪节、《礼记》讲礼义）→孔子“不学礼，无以立”（儒家化）。“五礼”口诀“吉凶军宾嘉”，吉祭祀、凶丧葬、军征伐、宾待客、嘉冠婚。","mix":"三礼与“三礼”之外的“五礼”分属两个系统：三礼是书，五礼是分类；《周礼》原名《周官》，不要把《礼记》和《仪礼》的内容对调。","mcq":[{"q":"“三礼”指的是","o":["《周礼》《仪礼》《礼记》","《周礼》《礼记》《春秋》","《仪礼》《礼记》《论语》","《周易》《周礼》《仪礼》"],"a":0,"w":"三礼即《周礼》《仪礼》《礼记》。"},{"q":"相传制礼作乐、确立周代礼制的人是","o":["孔子","孟子","周公","荀子"],"a":2,"w":"周公制礼作乐，孔子称“吾从周”。"}],"rel":[{"t":"三礼","n":"礼仪典籍"},{"t":"五礼","n":"礼仪五类"},{"t":"周公","n":"制礼作乐者"},{"t":"仁与礼（克己复礼）","n":"孔子礼学"},{"t":"《论语》","n":"“不学礼，无以立”出处"}],"more":"礼记·中庸：大哉圣人之道！洋洋乎发育万物，峻极于天。优优大哉！礼仪三百，威仪三千。\n论语·季氏：不学礼，无以立。"},{"id":"b07-022","t":"世界遗产类型","cid":"07a","p":2,"kind":"概念","alias":["世界遗产分类","混合遗产"],"one":"世界遗产分文化遗产、自然遗产、文化与自然混合遗产（双遗产）三类，文化景观属文化遗产。","ans":"世界遗产是**联合国教科文组织依据1972年公约评定的人类共同遗产**，分为三类：**文化遗产**（古迹、建筑群、遗址）、**自然遗产**（地貌、生物和自然景观）和**文化与自然混合遗产（双遗产）**，后者同时符合两类标准。**1992年**起增设**文化景观**，归入文化遗产，指人与自然的共同作品，如庐山、杭州西湖文化景观。评定标准共十条，一至六条为文化标准，七至十条为自然标准。","pts":["三类：文化、自然、混合（双遗产）","文化景观归文化遗产","十条标准：1至6文化，7至10自然"],"mem":"三类口诀“文、自、双”，景观归文。十条标准按“六文四自”记：前六条文化，后四条自然。","mix":"非物质文化遗产由2003年另一公约管理，不在世界遗产三类之内；文化景观是文化遗产的子类，不是第四类。","mcq":[{"q":"下列不属于世界遗产类型的是","o":["文化遗产","自然遗产","文化与自然混合遗产","非物质文化遗产"],"a":3,"w":"非遗由2003年《保护非物质文化遗产公约》管理。"}],"rel":[{"t":"世界文化遗产","n":"三类之一"},{"t":"非物质文化遗产","n":"另一条公约，易混"},{"t":"中国文化与自然双遗产","n":"混合遗产在中国的四项"},{"t":"《保护世界文化和自然遗产公约》","n":"分类的出处"},{"t":"濒危世界遗产","n":"名录的警示类别"}],"exam":[]},{"id":"b07-023","t":"十二时辰","cid":"07d","p":2,"kind":"常识","alias":["时辰","子时","午时"],"one":"以十二地支命名的计时制度，一时辰两小时，子时23至1点，午时11至13点。","ans":"十二时辰是**中国古代的计时制度**，把一天分为**十二段，每段相当于现在两小时**，依次用**十二地支**命名：子、丑、寅、卯、辰、巳、午、未、申、酉、戌、亥。**子时为23点至1点**，**午时为11点至13点**，“子夜”“正午”“午时三刻”等说法由此而来。每个时辰又分初、正，各一小时。十二时辰与干支纪年、十二生肖共用十二地支，沿用至清代。","pts":["一天十二时辰，每个两小时","地支命名，子时23至1点","午时11至13点，正午由来"],"mem":"算法：除子时外，第n个时辰从（2n-3）点开始，如午（第7）从11点、酉（第10）从17点。子时跨日，23点起。","mix":"子时跨越两天；巳时9至11点，未时13至15点，申时15至17点，都容易错位；时辰是两小时，不是一小时。","mcq":[{"q":"午时对应现在的","o":["9点至11点","13点至15点","23点至1点","11点至13点"],"a":3,"w":"午时为11点至13点，子时为23点至1点。"}],"rel":[{"t":"十二生肖","n":"共用十二地支"},{"t":"干支纪年与历史事件","n":"干支系统"},{"t":"农历","n":"同属传统历法体系"}],"more":"子23至1；丑1至3；寅3至5；卯5至7；辰7至9；巳9至11；午11至13；未13至15；申15至17；酉17至19；戌19至21；亥21至23","exam":[]},{"id":"b07-024","t":"围棋“收官”","cid":"07h","p":2,"kind":"常识","exam":["2011选择"],"alias":["收官","官子"],"one":"围棋术语，指对局最后阶段，后借指事情的最后阶段。","ans":"“收官”是**围棋术语，指对局的最后阶段**。围棋一局大致分为**布局、中盘、收官**三个阶段：开局抢占要点为布局，中盘展开战斗，棋形大局已定后，双方在边界上争夺最后的目数，称为收官（又称官子）。围棋起源于中国，古称“弈”，是琴棋书画“四艺”之一。“收官”后来被借用到日常语言，比喻事情进入最后阶段，如“年度收官”“工程收官”，是围棋用语进入通用语汇的典型例子。","pts":["围棋术语，指对局最后阶段","围棋三阶段：布局、中盘、收官","后借指事情最后阶段"],"mem":"一局棋像一部戏：开场（布局）、高潮（中盘）、谢幕（收官）。收官就是收尾，“官”是官子，棋盘边界上最后几步的争夺。看到“年终收官”“收官之战”，想到的就是围棋用语出圈。","mix":"“收官”不是象棋术语，围棋才有布局、中盘、官子；围棋古称“弈”，与国际象棋、中国象棋要分清。","mcq":[{"q":"“收官”一词原为哪项活动的术语","o":["中国象棋","国际象棋","古琴","围棋"],"a":3,"w":"围棋对局最后阶段称收官。"},{"q":"围棋一局的三个阶段依次是","o":["布局、中盘、收官","开局、中局、残局","起手、中盘、官子","落子、战斗、收官"],"a":0,"w":"围棋常说布局、中盘、收官（官子）。"}],"rel":[{"t":"围棋与国际象棋","n":"同类词条"},{"t":"文人四艺（琴棋书画）","n":"围棋为“棋”"},{"t":"AlphaGo","n":"围棋与人工智能"},{"t":"“人工智能+”行动","n":"AI与围棋关联"}],"more":"围棋19×19路，361个交叉点，黑先白后。"},{"id":"b07-025","t":"创造性转化、创新性发展","cid":"07a","p":2,"kind":"概念","exam":["2024作文"],"alias":["两创","创造性转化","创新性发展","创造性转化创新性发展"],"one":"习近平提出的对待中华优秀传统文化的方针，简称“两创”，写入十九大报告和党章。","ans":"“创造性转化、创新性发展”简称“两创”，是**习近平提出的对待中华优秀传统文化的基本方针**，2013年前后提出，后写入**党的十九大报告和党章**。**创造性转化**指对仍有价值的内涵和陈旧的表现形式加以改造，赋予**新的时代内涵和现代表达形式**；**创新性发展**指对传统文化内涵加以补充、拓展、完善，增强其**影响力和感召力**。“两创”要求**不复古泥古，也不简单否定**，如殷墟成果数字化展示、非遗活态传承。2021年建党百年大会提出“两个结合”，2023年文化传承发展座谈会深刻阐释“第二个结合”。","pts":["习近平提出的传统文化方针，十九大写入","转化改形式，发展补内涵","不复古也不否定，如殷墟、非遗；2023年座谈会"],"mem":"口诀“转化改形式，发展补内涵”：创造性转化管表现形式（旧瓶装新酒），创新性发展管内容（加厚加宽）。实例挂殷墟：甲骨文数字化展示就是转化，博物馆新馆是发展。","mix":"“两创”针对中华优秀传统文化；“两个结合”是马克思主义基本原理同中国具体实际、同中华优秀传统文化相结合，是另一个提法。","mcq":[{"q":"“创造性转化、创新性发展”针对的对象是","o":["外来文化","革命文化","当代科技","中华优秀传统文化"],"a":3,"w":"“两创”是对待中华优秀传统文化的基本方针。"}],"rel":[{"t":"“两个结合”","n":"同一时期的理论提法"},{"t":"中华文明五个突出特性","n":"2023年座谈会成果"},{"t":"殷墟","n":"2024作文材料"},{"t":"非物质文化遗产","n":"活态传承的实践"}],"more":"2024作文材料：殷墟文化。殷墟1899年因甲骨文发现而闻名，2006年列入世界遗产，2024年殷墟博物馆新馆开放。\n2021年建党百年大会：提出“两个结合”；2023年文化传承发展座谈会：深刻阐释“第二个结合”，提出中华文明五个突出特性。"},{"id":"b07-026","t":"中华文明五个突出特性","cid":"07a","p":2,"kind":"合称","alias":["五个突出特性","中华文明突出特性"],"one":"连续性、创新性、统一性、包容性、和平性，2023年座谈会提出的中华文明五个突出特性。","ans":"中华文明五个突出特性是**习近平2023年6月在文化传承发展座谈会上提出**的论断，即**连续性、创新性、统一性、包容性、和平性**。它是对中华文明历史特征的总概括，与对“**第二个结合**”的系统阐释一同提出，用来说明中国为什么必须走自己的路。连续性指五千多年文明从未中断，创新性指守正不守旧，统一性指国家统一是核心利益，包容性指对其他文明兼收并蓄，和平性指始终做世界和平的建设者。它是理解**文化自信**的基础概括。","pts":["2023年座谈会提出","连续、创新、统一、包容、和平","结合“第二个结合”的阐释提出"],"members":[["连续性","五千多年从未中断，决定必然走自己的路"],["创新性","守正不守旧，尊古不复古"],["统一性","国家统一是核心利益的核心"],["包容性","对世界文明兼收并蓄"],["和平性","始终是世界和平的建设者"]],"mem":"首字串“连创统包和”。逻辑线：先看时间（连续、创新），再看内部（统一、包容），最后看对外（和平）。","mix":"干扰项常换成“先进性”“开放性”“多元性”；“和平性”与“和平共处五项原则”是两个不同提法。","mcq":[{"q":"下列不属于中华文明五个突出特性的是","o":["连续性","创新性","先进性","统一性"],"a":2,"w":"五个特性是连续性、创新性、统一性、包容性、和平性。"}],"rel":[{"t":"“两个结合”","n":"同次座谈会提出"},{"t":"创造性转化、创新性发展","n":"文化方针对举"},{"t":"中华文明探源工程","n":"五千多年文明的实证"},{"t":"华夏","n":"文明认同的概念"}],"exam":[]},{"id":"b07-027","t":"“两个结合”","cid":"07a","p":3,"kind":"概念","alias":["两个结合","第二个结合"],"one":"把马克思主义基本原理同中国具体实际、同中华优秀传统文化相结合。","ans":"“两个结合”指**把马克思主义基本原理同中国具体实际相结合**、**同中华优秀传统文化相结合**。它是推进**马克思主义中国化时代化**的根本途径。“第二个结合”彰显了高度的文化主体性，为**建设中华民族现代文明**提供了理论遵循。","pts":["同中国具体实际相结合","同中华优秀传统文化相结合","推进马克思主义中国化时代化"],"mem":"记“两个结合”：一结具体实际走对路，二结传统文化扎深根。","mix":"“第二个结合”特指同中华优秀传统文化相结合，非西方文明或现代科技。","mcq":[{"q":"2021年提出的“两个结合”，除同中国具体实际相结合外，另一个结合是","o":["同中华优秀传统文化相结合","同世界先进文明成果相结合","同现代科学技术发展相结合","同社会主义市场经济相结合"],"a":0,"w":"“两个结合”指同中国具体实际相结合、同中华优秀传统文化相结合。"}],"rel":[{"t":"习近平新时代中国特色社会主义思想","n":"当代马克思主义思想"},{"t":"中华思想文化术语传播工程","n":"传承中华优秀传统文化"}],"exam":[]},{"id":"b07-028","t":"屏风","cid":"07h","p":3,"kind":"常识","exam":["2017名解"],"alias":["座屏","插屏","围屏"],"one":"中国传统居室中用于挡风、分隔空间、隐蔽与美化装饰的古典家具。","ans":"屏风是**中国传统居室中用于挡风、分隔空间与装饰的古典家具**。周代即见雏形，汉唐普及，形制有**座屏、插屏、围屏等**。板面常饰以**书画浮雕或丝绣**，兼具实用隔断与艺术审美。在古典文学中常寄托**尊卑秩序与闺阁幽情**，《红楼梦》贾府随处可见。","pts":["传统居室挡风、隔断与装饰的古典家具","形制多样，常融汇书画、雕刻与丝绣","蕴含空间礼制与文化意象，红楼梦常写"],"mem":"联想：“**屏风挡风隔雅间，红楼深院书画嵌**”，李商隐“云母屏风烛影深”。","mix":"屏风本义为挡风（屏其风也），后演进为空间陈设与审美礼仪象征；交大2017名解与《红楼梦》贾府家居文化相结合考查。","mcq":[{"q":"唐代诗人李商隐名句‘云母屏风烛影深，长河渐落晓星沉’中的‘屏风’在古代居室中最原始的基本功能是","o":["悬挂衣物","挡风与遮蔽视线","研墨镇纸","祭祀神位"],"a":1,"w":"屏风顾名思义为‘屏其风也’，最初用于挡风和遮蔽，后演变为室内隔断与装饰家具。"}],"rel":[{"t":"《红楼梦》人物与情节","n":"2017考题同组结合文学考查"},{"t":"文房四宝","n":"同属文人雅致书房器用"},{"t":"四大名绣","n":"常作为屏风心装饰工艺"}]},{"id":"b07-029","t":"人类非遗代表作中国项目","cid":"07a","p":2,"kind":"常识","alias":["人类非遗中国项目","中国人类非遗"],"one":"昆曲（2001）居首，端午节2009年、二十四节气2016年、春节2024年先后入选。","ans":"中国列入联合国教科文组织人类非物质文化遗产代表作名录的项目可按时间串记：**2001年昆曲**，**2003年古琴**，2005年新疆维吾尔木卡姆与蒙古族长调民歌，**2009年端午节**及书法篆刻、剪纸等，**2010年京剧**与中医针灸，2013年珠算，**2016年二十四节气**，**2020年太极拳**，2022年中国传统制茶技艺，**2024年春节**。端午节是首个入选的中国节日。名录使这些活态文化获得国际关注与保护。","pts":["昆曲2001、古琴2003居前","端午2009、京剧2010、节气2016","太极拳2020、制茶2022、春节2024"],"mem":"只记三个年份锚点：2001昆曲、2009端午、2024春节。其余按“古琴、木卡姆在2003至2005，京剧针灸在2010，珠算节气在2013至2016，太极制茶在2020至2022”往里填。","mix":"京剧（2010）与中医针灸同年；端午节（2009）早于春节（2024）；国家级非遗名录、世界遗产名录是不同名录，不可混用。","mcq":[{"q":"下列项目中，最先列入人类非遗代表作名录的是","o":["古琴","昆曲","京剧","端午节"],"a":1,"w":"昆曲2001年入选，古琴2003年。"}],"rel":[{"t":"非物质文化遗产","n":"所属制度"},{"t":"昆曲","n":"2001年首批"},{"t":"古琴","n":"2003年入选"},{"t":"端午节","n":"首个入选的节日"},{"t":"春节列入人类非遗代表作名录","n":"2024年最新"}],"more":"2001昆曲；2003古琴；2005新疆维吾尔木卡姆、蒙古族长调民歌；2009端午节、中国书法篆刻、剪纸等；2010京剧、中医针灸；2013珠算；2016二十四节气；2020太极拳；2022中国传统制茶技艺；2024春节","exam":[]},{"id":"b07-030","t":"世界记忆名录","cid":"07a","p":3,"kind":"制度","alias":["世界记忆项目","Memory of the World"],"one":"联合国教科文组织设立的文献遗产保护名录，保护濒危档案手稿。","ans":"世界记忆名录是**联合国教科文组织**于1992年设立的**世界记忆项目**组成部分，旨在抢救并保护全球濒危的**文献遗产**。中国已有**甲骨文**、《本草纲目》《黄帝内经》等多项文献入选，展现了中华典籍的文明价值。","pts":["联合国教科文组织文献遗产名录","抢救与保护濒危档案手稿文献","中国入选甲骨文与本草纲目等"],"mem":"记忆名录管“纸墨文字”（文献档案），世界遗产管“名山古建”（有形实体）。","mix":"易与《世界遗产名录》（有形文化与自然遗产）、非遗名录（活态技艺）混淆。","mcq":[{"q":"下列中国珍贵文献遗产中，入选联合国教科文组织《世界记忆名录》的是","o":["敦煌变文残卷","殷墟甲骨文","《永乐大典》辑本","《四库全书》底本"],"a":1,"w":"殷墟甲骨文于2017年入选《世界记忆名录》，中国入选的还有《本草纲目》《黄帝内经》等。"}],"rel":[{"t":"《保护世界文化和自然遗产公约》","n":"教科文组织遗产公约"},{"t":"《本草纲目》","n":"中国入选文献遗产"},{"t":"《黄帝内经》","n":"中国入选文献遗产"}],"exam":[]},{"id":"b07-031","t":"敦煌藏经洞","cid":"07b","p":2,"kind":"事件","alias":["藏经洞","莫高窟第17窟","敦煌遗书"],"one":"1900年王圆箓发现的莫高窟藏经洞，出土五万余件文书，催生敦煌学。","ans":"敦煌藏经洞即莫高窟第17窟，**1900年由道士王圆箓发现**，洞中封存**四至十一世纪的文书五万余件**，包括佛经、官私文书、儒家典籍和少量绢画。其后英国斯坦因、法国伯希和等人把大批文物运往海外，造成严重**流失**。藏经洞文献催生了**“敦煌学”**，成为研究中古中国与丝绸之路的重要资料，陈寅恪在《敦煌劫余录序》中引“**敦煌者，吾国学术之伤心史也**”感慨文物流失并勉励学人振作。","pts":["1900年王圆箓发现，莫高窟第17窟","四至十一世纪文书五万余件","大量流失海外，催生敦煌学"],"mem":"画面：1900年，王道士在第17窟打开一堵墙，露出五万件文书，随后斯坦因、伯希和相继赶到。1900年也是义和团和八国联军侵华之年，国运与文物同遭劫难。","mix":"斯坦因、伯希和是后来的掠取者，发现者是王圆箓；藏经洞编号第17窟，开在第16窟甬道的北壁。","mcq":[{"q":"敦煌藏经洞的发现者是","o":["王圆箓","斯坦因","伯希和","张大千"],"a":0,"w":"1900年道士王圆箓发现；斯坦因、伯希和随后掠走大批文书。"}],"rel":[{"t":"敦煌壁画","n":"同在莫高窟"},{"t":"中国四大石窟","n":"莫高窟属其一"},{"t":"丝绸之路","n":"文书反映的背景"},{"t":"罗塞塔石碑","n":"重要文献发现的中西对照"}],"more":"1900年：王圆箓发现藏经洞\n1907年：斯坦因取走大批文书\n1908年：伯希和取走精品","exam":[]},{"id":"b07-032","t":"后母戊鼎","cid":"07b","p":2,"kind":"常识","alias":["司母戊鼎","后母戊大方鼎"],"one":"商代最重的青铜器，原称司母戊鼎，殷墟出土，藏国家博物馆。","ans":"后母戊鼎原称司母戊鼎，是**商代晚期青铜礼器**，1939年出土于**河南安阳殷墟**武官村，重**832.84公斤**，是目前已知**最重的青铜器**，现藏**中国国家博物馆**。鼎腹内壁铸有“后母戊”三字，为祭祀母亲“戊”而作，国家博物馆据对铭文的新释读，2011年改称今名。鼎体厚重，纹饰繁复，用分铸法铸成，体现**商代青铜铸造的高超水平**，与殷墟甲骨文共同见证商文明。","pts":["商代晚期，殷墟出土","现存最重的青铜器，832.84公斤","原称司母戊鼎，藏国家博物馆"],"mem":"画面：把“司”字照镜子翻转，就是“后”，“司母戊”因此改读“后母戊”。数字：“八三二”像三个字母叠在一起，记成“八百三十多公斤”。","mix":"四羊方尊也是商代名器，但以造型精美著称，不以重量取胜；毛公鼎、大盂鼎属西周。","mcq":[{"q":"我国已知最重的古代青铜器是","o":["毛公鼎","大盂鼎","四羊方尊","后母戊鼎"],"a":3,"w":"后母戊鼎重832.84公斤，商代，殷墟出土。"}],"rel":[{"t":"殷墟","n":"出土地"},{"t":"甲骨文","n":"同出殷墟"},{"t":"商朝与盘庚迁殷","n":"所属王朝"},{"t":"三星堆遗址","n":"同期青铜文明对照"}],"exam":[]},{"id":"b07-033","t":"三星堆遗址","cid":"07b","p":2,"kind":"地理","alias":["三星堆","三星堆青铜面具"],"one":"四川广汉的古蜀文明遗址，青铜纵目面具、青铜神树闻名。","ans":"三星堆遗址位于**四川省广汉市**，是**古蜀文明**的代表性遗址，年代距今约4800至3000年。1929年当地农民发现玉器，**1986年发掘出两个祭祀坑**，2019至2021年又发现六个新坑。出土有**青铜纵目面具、青铜大立人像、青铜神树**以及金面具、金杖，造型与中原青铜器差异明显。三星堆表明长江上游存在高度发达的区域文明，是**中华文明多元一体**的实物例证。","pts":["四川广汉，古蜀文明遗址","1986年两个祭祀坑，2021年新坑","青铜纵目面具、神树；多元一体"],"mem":"画面：突出的眼睛（纵目）加通天的大树（神树）。对照记：殷墟在中原，以鼎和甲骨文为代表，重礼与文字；三星堆在蜀地，以人像和神树为代表，没有发现文字。","mix":"成都金沙遗址（太阳神鸟）是古蜀文明的后继遗址，与三星堆不是同一处；三星堆青铜器没有发现成体系的文字。","mcq":[{"q":"青铜纵目面具出土于","o":["殷墟","二里头遗址","良渚古城","三星堆遗址"],"a":3,"w":"青铜纵目面具、神树出土于四川广汉三星堆。"}],"rel":[{"t":"殷墟","n":"同期中原青铜文明"},{"t":"后母戊鼎","n":"青铜器对照"},{"t":"良渚古城遗址","n":"同属文明起源遗址"},{"t":"迈锡尼文明","n":"同有黄金面具，可对照"}],"exam":[]},{"id":"b07-034","t":"二里头遗址","cid":"07b","p":2,"kind":"地理","alias":["二里头","二里头文化"],"one":"河南偃师，多数学者认为是夏代中晚期都城遗址。","ans":"二里头遗址位于**河南省洛阳市偃师区**，1959年由徐旭生调查“夏墟”时发现，年代约前1750至前1520年。遗址有**大型宫殿基址、中国最早的宫城和井字形道路网**，并有青铜礼器作坊，出土**绿松石龙形器**与青铜爵。**多数学者认为它是夏代中晚期都城**，也有学者主张属早商。它显示早期国家已经出现，被称为“**最早的中国**”。","pts":["河南偃师，1959年发现","宫城、道路网、绿松石龙形器","多数学者视为夏代中晚期都城"],"mem":"“二里头=夏都，偃师”。偃师境内还有偃师商城，属早商，两处隔洛河相望，一夏一商。","mix":"学界另有早商之说；八里桥遗址（方城）也属夏代遗存，二者不要互换地名。","mcq":[{"q":"多数学者认为河南偃师二里头遗址是哪一朝代的都城遗址","o":["夏","商","西周","东周"],"a":0,"w":"二里头被多数学者视为夏代中晚期都城。"}],"rel":[{"t":"夏文化","n":"核心考古遗址"},{"t":"夏朝","n":"所对应的王朝"},{"t":"八里桥遗址","n":"同指向夏的遗址"},{"t":"殷墟","n":"商代都城对照"},{"t":"中华文明探源工程","n":"重点研究对象"}],"exam":[]},{"id":"b07-035","t":"良渚古城遗址","cid":"07b","p":1,"kind":"地理","alias":["良渚","良渚文化","良渚古城","良渚遗址"],"one":"浙江杭州，2019年入遗，实证中华五千多年文明史。","ans":"良渚古城遗址位于**浙江杭州余杭区**，是**新石器时代晚期良渚文化的都邑遗址**，距今约5300至4300年。遗址由**莫角山宫殿区、内外城和外围水利系统**组成，出土以**玉琮、玉璧**为代表的玉礼器，显示出明显的社会等级和统一的信仰。**2019年7月列入世界遗产名录**，被认为**实证了中华五千多年文明史**，是长江下游地区早期国家的代表。","pts":["浙江杭州，新石器晚期良渚文化","宫殿区、城墙、水利系统，玉琮玉璧","2019年入遗，实证五千多年文明"],"mem":"一句话：良渚是“五千年”的实物证明，对应“水、玉、城”三字：大型水利系统、玉琮玉璧、内外城。年份挂钩：2019入遗，晚于殷墟（2006）13年。","mix":"良渚证明五千多年，二里头指向夏（约四千年前），殷墟确证商；良渚在浙江，三星堆在四川，红山在辽宁，不要错配。","mcq":[{"q":"实证中华五千多年文明史的考古遗址是","o":["二里头遗址","殷墟","三星堆遗址","良渚古城遗址"],"a":3,"w":"良渚古城遗址2019年列入世界遗产，被称为中华五千年文明的实证。"},{"q":"良渚文化最具代表性的玉器是","o":["玉龙","玉琮","玉衣","玉圭"],"a":1,"w":"玉琮、玉璧是良渚文化玉礼器的代表。"}],"rel":[{"t":"二里头遗址","n":"夏文化对照"},{"t":"殷墟","n":"商代都城对照"},{"t":"中华文明探源工程","n":"相关工程"},{"t":"三星堆遗址","n":"同列古蜀文明遗址"},{"t":"世界文化遗产","n":"所属体系"}],"more":"1936年施昕更在良渚镇首次发现良渚文化遗存。","exam":[]},{"id":"b07-036","t":"十二生肖","cid":"07d","p":2,"kind":"合称","alias":["生肖","属相"],"one":"鼠牛虎兔龙蛇马羊猴鸡狗猪，与十二地支对应。","ans":"十二生肖是**以十二种动物配十二地支纪年**的民俗体系，依次为**鼠、牛、虎、兔、龙、蛇、马、羊、猴、鸡、狗、猪**，对应子、丑、寅、卯、辰、巳、午、未、申、酉、戌、亥。人出生之年的生肖即属相，**十二年一轮回**，与六十年的**干支纪年**配合使用。生肖在东汉王充《论衡》中已有完整记载，睡虎地秦简《日书》也有相关内容，是节庆、婚俗、命名中的民俗载体。","pts":["十二动物配十二地支","鼠牛虎兔龙蛇马羊猴鸡狗猪","十二年一轮，配干支纪年"],"members":[["子鼠","子时23至1点"],["丑牛","丑时1至3点"],["寅虎","寅时3至5点"],["卯兔","卯时5至7点"],["辰龙","辰时7至9点"],["巳蛇","巳时9至11点"],["午马","午时11至13点"],["未羊","未时13至15点"],["申猴","申时15至17点"],["酉鸡","酉时17至19点"],["戌狗","戌时19至21点"],["亥猪","亥时21至23点"]],"mem":"顺序口诀“鼠牛虎兔龙蛇马羊猴鸡狗猪”。算法：（公历年份-4）除以12，余数0鼠、1牛、2虎、3兔、4龙、5蛇、6马……如2026年得6，是马年（丙午）。","mix":"生肖里没有猫；生肖十二年一轮，干支六十年一轮，两者不是同一周期；属相按农历春节还是立春划分，民间习惯不同。","mcq":[{"q":"2026年（农历丙午年）的生肖是","o":["蛇","羊","龙","马"],"a":3,"w":"2026年为丙午年，生肖属马。"}],"rel":[{"t":"十二时辰","n":"共用十二地支"},{"t":"干支纪年与历史事件","n":"干支配合纪年"},{"t":"农历","n":"生肖所属历法"}],"exam":[]},{"id":"b07-037","t":"二十四节气中的“四立二分二至”","cid":"07d","p":2,"kind":"合称","alias":["四立二分二至","四立","二分二至"],"one":"立春、立夏、立秋、立冬，春分、秋分，夏至、冬至共八个节气。","ans":"“四立二分二至”指**二十四节气中标志四季起讫和昼夜长短变化的八个节气**：**立春、立夏、立秋、立冬**（四立，四季开始），**春分、秋分**（二分，昼夜等长），**夏至、冬至**（二至，白昼最长与最短）。二十四节气按太阳在黄道上的位置划分，黄经每15度一个节气，八个节气相隔45度，**2016年**列入人类非遗代表作名录。冬至夏至时太阳直射点分别在南北回归线，是古人最早测定的节气。","pts":["四立：四季开始","二分：昼夜等长；二至：昼夜极值","黄经每15度一气，2016年入非遗"],"members":[["立春","四立，春季开始"],["立夏","四立，夏季开始"],["立秋","四立，秋季开始"],["立冬","四立，冬季开始"],["春分","二分，昼夜等长"],["秋分","二分，昼夜等长"],["夏至","二至，白昼最长"],["冬至","二至，白昼最短"]],"mem":"“立”是开始，“分”是平分，“至”是极致。夏至白昼最长，冬至白昼最短，春分秋分日夜等长。","mix":"“二至”指夏至与冬至，不含春分秋分；清明、谷雨、小满等是其余十六个节气，不在八节之内。","mcq":[{"q":"下列节气中，属于“二分”的是","o":["立春","夏至","春分","冬至"],"a":2,"w":"二分指春分和秋分，昼夜等长。"}],"rel":[{"t":"二十四节气","n":"所属体系"},{"t":"冬至与夏至","n":"二至详解"},{"t":"农历","n":"节气与历法"},{"t":"太初历","n":"首次订入节气的历法"}],"exam":[]},{"id":"b07-038","t":"农历","cid":"07d","p":2,"kind":"常识","alias":["夏历","阴阳合历","旧历"],"one":"阴阳合历，以月相定月，以节气配季节，设闰月协调。","ans":"农历是**中国传统历法**，属**阴阳合历**：以**月相变化（朔望月，约29.53天）**定月，大月30天、小月29天；又以**二十四节气**反映太阳周年运动、配合农时；用**闰月**协调12个朔望月与回归年的差距，**十九年七闰**。岁首为正月初一（春节），纪年用干支。农历又称夏历，与公历并行，春节、端午、中秋等传统节日都按农历。","pts":["阴阳合历：月相定月，节气配季","闰月协调，十九年七闰","春节等传统节日按农历"],"mem":"阴（月相）加阳（节气）等于阴阳合历。闰月口诀：“三年一闰，五年再闰，十九年七闰”。","mix":"伊斯兰历是纯阴历，没有闰月，一年约354天；公历是阳历；农历不是纯阴历。","mcq":[{"q":"农历属于","o":["纯阴历","纯阳历","太阴历","阴阳合历"],"a":3,"w":"农历以月相定月、以节气和闰月配合太阳年，是阴阳合历。"}],"rel":[{"t":"闰月与十九年七闰","n":"闰月规则"},{"t":"二十四节气","n":"农历的阳历成分"},{"t":"公历闰年","n":"公历对照"},{"t":"开斋节与古尔邦节","n":"伊斯兰历对照"},{"t":"太初历","n":"历法发展"}],"exam":[]},{"id":"b07-039","t":"《梦溪笔谈》","cid":"07g","p":1,"kind":"作品","alias":["梦溪笔谈","沈括"],"one":"北宋沈括所著笔记，记载活字印刷，李约瑟称“中国科学史上的坐标”。","ans":"《梦溪笔谈》是**北宋科学家沈括所著的笔记体著作**，因他晚年居润州梦溪园而得名，共30卷（含《补笔谈》《续笔谈》）。内容涉及天文历法、数学、物理、地质、医药、工程和文学，**记载了毕昇发明的活字印刷术**，记述指南针的磁偏角现象，并首次提出“**石油**”这一名称。英国学者李约瑟称它为“**中国科学史上的坐标**”，是研究宋代科技与社会的重要文献。","pts":["北宋沈括笔记体著作","记载毕昇活字、磁偏角、命名石油","李约瑟称“中国科学史上的坐标”"],"mem":"一个人一座园一本书：沈括—梦溪园—《梦溪笔谈》。三件大事“活字、磁偏、石油”：印刷（毕昇）、指南针（磁偏角）、石油（沈括首次命名），正好覆盖四大发明里的两项。","mix":"《天工开物》是明代宋应星所作，《本草纲目》是明代李时珍所作；活字印刷术是毕昇发明，沈括只是记载者。","mcq":[{"q":"记载毕昇发明活字印刷术的著作是","o":["《梦溪笔谈》","《天工开物》","《齐民要术》","《本草纲目》"],"a":0,"w":"沈括《梦溪笔谈》记载了毕昇活字印刷。"},{"q":"首次提出“石油”这一名称的是","o":["宋应星","李时珍","徐光启","沈括"],"a":3,"w":"沈括在《梦溪笔谈》中提出“石油”之名。"}],"rel":[{"t":"四大发明","n":"记载活字与指南针"},{"t":"印刷术","n":"活字印刷"},{"t":"指南针","n":"磁偏角记载"},{"t":"《天工开物》","n":"明代科技名著"},{"t":"《本草纲目》","n":"明代医药名著"}],"more":"沈括（1031–1095），字存中，北宋科学家。\n李约瑟称《梦溪笔谈》为“中国科学史上的坐标”。","exam":[]},{"id":"b07-040","t":"《天工开物》","cid":"07g","p":2,"kind":"作品","alias":["天工开物","宋应星"],"one":"明代宋应星所著农业手工业百科全书，被称“中国17世纪的工艺百科全书”。","ans":"《天工开物》是**明代宋应星所著的农业与手工业技术著作**，成书并刊行于崇祯十年（1637年），共三卷十八篇。全书记载了谷物栽培、纺织染色、冶铸、陶瓷、造纸、制盐、榨油等生产技术，附有大量插图，被称为**“中国17世纪的工艺百科全书”**。书名中“天工”“开物”分别取自《尚书》与《周易》。该书流传到日本和欧洲，为研究中国古代科技提供了系统史料，与《本草纲目》同为明代科技名著。","pts":["明代宋应星，崇祯十年（1637）刊行","记载农业与手工业技术，附插图","中国17世纪的工艺百科全书"],"mem":"人物对应：宋应星—天工开物，李时珍—本草纲目。“天工”是天然的造化，“开物”是人去开发利用，书名意思是人力配合自然去成就器物。口诀“宋工李药”：宋应星讲工艺，李时珍讲药物。","mix":"《天工开物》记工艺，不是农书（农书是《齐民要术》《农政全书》）；《梦溪笔谈》是北宋沈括所著，同样含大量科技内容，作者与朝代不要对错。","mcq":[{"q":"被称为“中国17世纪的工艺百科全书”的是","o":["《天工开物》","《本草纲目》","《梦溪笔谈》","《齐民要术》"],"a":0,"w":"宋应星《天工开物》，成书于1637年。"},{"q":"《天工开物》的作者是","o":["李时珍","徐光启","贾思勰","宋应星"],"a":3,"w":"明代宋应星；徐光启著《农政全书》。"}],"rel":[{"t":"《本草纲目》","n":"同为明代科技巨著"},{"t":"《齐民要术》","n":"农书对举"},{"t":"《梦溪笔谈》","n":"宋代科技笔记"},{"t":"四大发明","n":"相关技术记载"}],"more":"全书内容：乃粒（谷物）、乃服（纺织）、陶埏（陶瓷）、冶铸、杀青（造纸）、膏液（榨油）、燔石（石灰煤炭）、佳兵（兵器）等。","exam":[]},{"id":"b07-041","t":"《本草纲目》","cid":"07g","p":2,"kind":"作品","alias":["本草纲目","李时珍"],"one":"明代李时珍所著药学巨著。","ans":"《本草纲目》是**明代李时珍所著的药学巨著**，李时珍历时近三十年编成，万历年间（1596年）在金陵刊行。全书共五十二卷，收载药物**1892种**，附方一万多首，按自然属性把药物分为**十六部六十类**，纠正了前代本草书中的不少错误。书中也记述了植物学、动物学、矿物学等知识。《本草纲目》传到日本、欧洲，被译成多种文字，2011年与《黄帝内经》一同列入联合国教科文组织《世界记忆名录》。","pts":["明代李时珍，药学巨著","收药1892种，十六部六十类","2011年入选《世界记忆名录》"],"mem":"数字记法：“一八九二”是药物种数，“五十二”是卷数，“十六部”是分类。时间线：李时珍1593年去世，书在1596年才刊行，是他身后问世的。画面：一个郎中背着药篓走遍名山，三十年后写成一本书。","mix":"《本草纲目》是药学书，不是医经（医经是《黄帝内经》）；《神农本草经》是更早的汉代药学著作，作者题神农，不是李时珍。","mcq":[{"q":"明代李时珍所著，全书收药1892种的著作是","o":["《千金要方》","《本草纲目》","《神农本草经》","《伤寒杂病论》"],"a":1,"w":"《本草纲目》收药1892种，分十六部六十类。"}],"rel":[{"t":"古代名医","n":"李时珍在列"},{"t":"《黄帝内经》","n":"同入世界记忆名录"},{"t":"中医四大经典","n":"另有经典可对照"},{"t":"《天工开物》","n":"同为明代科技名著"}],"more":"2011年，《黄帝内经》和《本草纲目》同时入选联合国教科文组织《世界记忆名录》。","exam":[]},{"id":"b07-042","t":"《齐民要术》","cid":"07g","p":2,"kind":"作品","alias":["齐民要术","贾思勰"],"one":"北魏贾思勰所著，现存最早最完整的农书。","ans":"《齐民要术》是**北魏贾思勰所著的综合性农书**，也是**现存最早、最完整的农书**，成书于6世纪三十年代前后。全书共十卷九十二篇，系统总结了黄河中下游地区的农耕、园艺、林木、畜牧、酿造和食品加工技术，并引用大量古代文献。书名“齐民”指平民，“要术”指谋生的重要方法。该书在中国农学史上影响深远，后世《农桑辑要》《农政全书》等都受其影响，与《氾胜之书》《王祯农书》《农政全书》并称古代四大农书。","pts":["北魏贾思勰，现存最早最完整的农书","十卷九十二篇，总结黄河流域农耕经验","古代四大农书之一"],"mem":"“贾思勰—齐民要术—北魏”三个一组背。名字理解：齐民就是平民，要术就是要紧的方法，合起来是“平民谋生的要紧方法”。朝代线：东汉《九章算术》，北魏《齐民要术》，北宋《梦溪笔谈》，明代《本草纲目》《天工开物》，前三本顺序记“汉魏宋”。","mix":"四大农书的通行说法是《氾胜之书》《齐民要术》《王祯农书》《农政全书》，也有把《陈旉农书》等列入的版本；《齐民要术》不是最早的农书（《氾胜之书》更早，但已不全），而是“现存最早最完整”。","mcq":[{"q":"我国现存最早最完整的农书是","o":["《农政全书》","《王祯农书》","《天工开物》","《齐民要术》"],"a":3,"w":"北魏贾思勰《齐民要术》。"}],"rel":[{"t":"中国古代四大农书","n":"属其中之一"},{"t":"《天工开物》","n":"明代工艺百科"},{"t":"《梦溪笔谈》","n":"科技典籍顺序"},{"t":"《九章算术》","n":"科技典籍顺序"}],"more":"《齐民要术》内容：谷物种植、蔬菜、果树、桑蚕、畜牧、酿造、烹饪等。","exam":[]},{"id":"b07-043","t":"考古学文化","cid":"07b","p":3,"kind":"概念","alias":["Archaeological Culture"],"one":"指分布于一定地域、存在于一定时期并具有共同特征的一群遗存的考古学术语。","ans":"考古学文化指分布于**一定地域**、存在于**一定时期**、具有**共同特征的一群古代遗存总和**。通常以**首次发现的典型遗址地名命名**，如仰韶文化、龙山文化等。它由地层学与类型学界定，不等同于特定王朝，是史前考古的时空基准。","pts":["特定时空范围内具有共同特征的遗存总和","通常以首次发现的典型遗址地名命名","界定时空框架，不等同于单一民族或王朝"],"mem":"考古学文化三要素：一定时间、一定地域、共同特征；命名找“首发地名”。","mix":"考古学文化纯由物质文化遗存定义，不可简单与文献记载中的特定民族或朝代直接划等号。","mcq":[{"q":"在考古学研究中，一种“考古学文化”的定名通行原则通常是","o":["以发掘出土最精美代表文物的名称命名","以该文化最早被发现的典型遗址所在地名命名","以古文献记载的传说时代部落名称命名","以遗址所在地的主要山川河流名称命名"],"a":1,"w":"考古学文化通常以首次发现该文化典型遗存的小地名命名，如仰韶村、龙山镇、良渚镇等。"}],"rel":[{"t":"仰韶文化","n":"黄河流域典型考古学文化"},{"t":"龙山文化","n":"新石器晚期考古学文化"},{"t":"良渚古城遗址","n":"长江下游玉器文明代表"},{"t":"二里头遗址","n":"中原早期青铜文明代表"}],"exam":[]},{"id":"b07-044","t":"夏文化","cid":"07b","p":2,"kind":"概念","alias":["夏代文化"],"one":"夏王朝的考古学文化，二里头遗址被多数学者视为夏代晚期都城。","ans":"夏文化指**夏王朝时期夏族创造的考古学文化**。《史记·夏本纪》记载夏是中国第一个王朝，**夏商周断代工程（1996至2000年）**把夏代年代定为**约前2070至前1600年**。考古上，**河南偃师二里头遗址**被多数学者视为夏代晚期都城，豫西、晋南是夏文化的主要分布区，河南方城八里桥遗址也属夏代遗存。夏文化研究把传说时代与信史时代连接起来，但夏的同时代文字材料至今缺乏，学界对二里头是否即夏仍有讨论。","pts":["夏约前2070至前1600年，断代工程定","二里头为夏代晚期都城","八里桥属夏代遗存；缺同时代文字"],"mem":"数字锚点：夏2070，商1600，周1046，三个起点可依次排成“夏—商—周”。带“里”的遗址（二里头、八里桥）指向夏。","mix":"夏商周断代工程是1996至2000年，中华文明探源工程是2002年起，二者不要混；夏的起点前2070与商的起点前1600不可错位。","mcq":[{"q":"夏商周断代工程把夏代的起始年代定为","o":["约前1046年","约前2070年","约前1600年","约前841年"],"a":1,"w":"断代工程定夏约前2070至前1600年；前1046为周，前841为共和元年。"}],"rel":[{"t":"夏朝","n":"朝代词条"},{"t":"二里头遗址","n":"核心遗址"},{"t":"八里桥遗址","n":"2025年选择题考点"},{"t":"商朝与盘庚迁殷","n":"夏之后的王朝"},{"t":"中华文明探源工程","n":"后续大型工程"}],"exam":[]},{"id":"b07-045","t":"宋代五大名窑","cid":"07h","p":2,"kind":"合称","alias":["五大名窑","汝官哥钧定"],"one":"汝窑、官窑、哥窑、钧窑、定窑。","ans":"宋代五大名窑指**汝窑、官窑、哥窑、钧窑、定窑**，是宋代瓷业的代表。**汝窑**在河南汝州，以天青釉著称；**官窑**为官府设窑，北宋在汴京、南宋在杭州；**哥窑**以开片纹（金丝铁线）闻名；**钧窑**在河南禹州，以窑变釉著称；**定窑**在河北曲阳，以白瓷见长。宋代民窑景德镇则以青白瓷（影青）闻名，元代烧制青花，明清设御窑，成为“瓷都”。2026年“景德镇手工瓷业遗存”列入世界遗产。","pts":["汝、官、哥、钧、定","汝窑天青釉，钧窑窑变，哥窑开片，定窑白瓷","景德镇宋代青白瓷，明清御窑，2026年入遗"],"members":[["汝窑","河南汝州，天青釉"],["官窑","官府设窑，北宋汴京、南宋杭州"],["哥窑","开片纹“金丝铁线”"],["钧窑","河南禹州，窑变釉"],["定窑","河北曲阳，白瓷"]],"mem":"通行口诀“汝官哥钧定”。一字一特点：汝—天青，官—官府，哥—开片，钧—窑变，定—白瓷。景德镇不在五大名窑内，它在宋代是民窑，真正成名是元明清。","mix":"另有柴窑等其他说法，通行以汝官哥钧定为准；景德镇不是宋代五大名窑之一；“南青北白”是唐代格局，不是宋代。","mcq":[{"q":"下列瓷窑中，不属于宋代五大名窑的是","o":["汝窑","钧窑","越窑","定窑"],"a":2,"w":"越窑是唐代南方青瓷代表，宋代五大名窑为汝官哥钧定。"},{"q":"以窑变釉著称的名窑是","o":["定窑","钧窑","汝窑","官窑"],"a":1,"w":"钧窑窑变釉；汝窑天青，定窑白瓷。"}],"rel":[{"t":"南青北白","n":"唐代瓷业格局"},{"t":"景德镇手工瓷业遗存","n":"2026年入遗"},{"t":"青花瓷","n":"元代景德镇成熟"},{"t":"中国近年新增世界遗产","n":"遗产保护体系"}],"more":"景德镇：1004年（景德元年）以年号命名；宋代青白瓷（影青），元代青花，明清御窑厂。2026年“景德镇手工瓷业遗存”列入世界遗产（中国第61项世界遗产）。","exam":[]},{"id":"b07-046","t":"陆羽《茶经》","cid":"07h","p":2,"kind":"作品","alias":["茶经","陆羽","茶圣"],"one":"唐代陆羽所著，世界上第一部茶学专著，陆羽被尊为茶圣。","ans":"《茶经》是**唐代陆羽所著的茶学专著**，也是**世界上第一部茶学专著**，陆羽因此被尊为**“茶圣”**。陆羽是复州竟陵（今湖北天门）人，一生嗜茶。《茶经》共三卷十章，涵盖茶的起源、采制工具、煮茶器具、煮饮方法、产地等内容，是对唐代及以前茶业经验的系统总结。书中还提出品茶与饮用的方式，影响了后世茶文化，并传播到日本、朝鲜等地，为中国茶文化奠定了理论基础。","pts":["唐代陆羽，世界第一部茶学专著","陆羽被尊为茶圣","总结茶的源、具、造、器、煮、饮"],"mem":"“茶圣陆羽，茶经三卷十章”。十章可按流程记：源、具、造、器、煮、饮、事、出、略、图。口诀“陆羽茶圣，仲景医圣，羲之书圣”，三个“圣”一起背。","mix":"《茶经》是唐代，不是宋代；宋代论茶的有蔡襄《茶录》、宋徽宗《大观茶论》；陆羽被称茶圣，卢仝是“茶仙”（《七碗茶歌》），不要混。","mcq":[{"q":"世界上第一部茶学专著《茶经》的作者是","o":["蔡襄","卢仝","陆羽","宋徽宗"],"a":2,"w":"唐代陆羽，被尊为茶圣。"}],"rel":[{"t":"中国十大名茶","n":"茶文化相关"},{"t":"六大茶类","n":"茶类分类"},{"t":"中国传统制茶技艺及其相关习俗","n":"茶与非遗"},{"t":"南青北白","n":"《茶经》评越瓷邢瓷"}],"more":"《茶经》十章：一之源、二之具、三之造、四之器、五之煮、六之饮、七之事、八之出、九之略、十之图。\n《茶经》论瓷：邢瓷类银，越瓷类玉。","exam":[]},{"id":"b07-047","t":"中国四大名楼","cid":"07c","p":3,"kind":"合称","alias":["四大名楼"],"one":"中国历史文化名楼合称，指黄鹤楼、岳阳楼、滕王阁与鹳雀楼。","ans":"中国四大名楼是**古代四座著名历史名楼的合称**，即**湖北武汉黄鹤楼、湖南岳阳岳阳楼、江西南昌滕王阁与山西运城鹳雀楼**。四楼均因千古名篇扬名天下，前三座位于长江流域，并称**“江南三大名楼”**，集中展现了楼阁建筑与诗文艺术的交融。","pts":["黄鹤楼、岳阳楼、滕王阁、鹳雀楼","均因千古诗文名篇而闻名于世","前三楼并称为江南三大名楼"],"members":[["黄鹤楼","湖北武汉武昌蛇山，崔颢《黄鹤楼》、李白《黄鹤楼送孟浩然之广陵》"],["岳阳楼","湖南岳阳洞庭湖畔，范仲淹《岳阳楼记》“先天下之忧而忧”"],["滕王阁","江西南昌赣江之滨，王勃《滕王阁序》“落霞与孤鹜齐飞”"],["鹳雀楼","山西运城永济黄河东岸，王之涣《登鹳雀楼》“欲穷千里目”"]],"mem":"四楼配四篇名作：黄鹤崔颢，岳阳范记，滕王王勃，鹳雀王之涣。","mix":"四大名楼中的鹳雀楼位于北方山西黄河之滨；江南三大名楼则仅指黄鹤楼、岳阳楼、滕王阁，不含鹳雀楼。","mcq":[{"q":"中国古代“四大名楼”中，唯一位于北方黄河流域的楼阁是","o":["岳阳楼","滕王阁","黄鹤楼","鹳雀楼"],"a":3,"w":"鹳雀楼位于山西省运城永济市黄河岸畔，其余三楼均位于南方长江流域。"}],"rel":[{"t":"江南三大名楼","n":"江南三楼合称"},{"t":"范仲淹《岳阳楼记》与“易混作者”","n":"名楼文学作品"}],"exam":[]},{"id":"b07-048","t":"中国四大名园","cid":"07c","p":3,"kind":"合称","alias":["四大名园"],"one":"中国古代造园艺术的巅峰代表，指拙政园、留园、颐和园与承德避暑山庄。","ans":"中国四大名园是**中国古典园林杰作的合称**，包括**江苏苏州拙政园、留园**与**北京颐和园、河北承德避暑山庄**。四园于1961年被列为首批全国重点文物保护单位。拙政园与留园代表**江南私家园林**的秀雅，颐和园与避暑山庄展现了**北方皇家园林**的宏阔。","pts":["苏州拙政园、苏州留园、北京颐和园、承德避暑山庄","1961年入选首批全国重点文物保护单位","兼具江南私家园林与北方皇家园林精髓"],"members":[["拙政园","江苏苏州，江南私家园林代表，以水为中心，明代御史王献臣建"],["留园","江苏苏州，以建筑空间布局和奇石“冠云峰”著称，清代名园"],["颐和园","北京海淀，中国现存最大最完整的皇家园林，以万寿山、昆明湖为主体"],["承德避暑山庄","河北承德，清代皇帝避暑与处理政务的皇家夏宫，又称热河行宫"]],"mem":"口诀记“两南两北”：苏州拙政与留园（私家），北京颐和承德庄（皇家）。","mix":"四大名园由两座苏州私家园林与两座北方皇家园林构成；扬州个园、何园不在此列。","mcq":[{"q":"下列著名中国古典园林中，不属于“中国四大名园”的是","o":["苏州拙政园","扬州个园","苏州留园","承德避暑山庄"],"a":1,"w":"中国四大名园为拙政园、留园、颐和园、承德避暑山庄；个园是扬州著名私家园林，不在其列。"}],"rel":[{"t":"《园冶》","n":"古代造园学理论专著"},{"t":"世界文化遗产","n":"四名园均入选世界文化遗产"}],"exam":[]},{"id":"b07-049","t":"四大名绣","cid":"07h","p":2,"kind":"合称","alias":["四大名绣","苏湘蜀粤"],"one":"苏绣、湘绣、蜀绣、粤绣。","ans":"四大名绣指**苏绣、湘绣、蜀绣、粤绣**，是中国传统刺绣的代表。**苏绣**产于江苏苏州，以精细雅洁、双面绣见长；**湘绣**产于湖南长沙，以狮、虎等绣品和毛丝技法著称；**蜀绣**产于四川成都，以软缎、彩丝为材，针法严谨；**粤绣**产于广东，色彩浓艳，图案繁密，含广绣与潮绣。刺绣是中国传统手工艺，苏绣、湘绣、蜀绣、粤绣都曾入选国家级非遗项目。","pts":["苏绣、湘绣、蜀绣、粤绣","苏州精细，长沙狮虎，成都软缎，广东浓艳","传统手工艺，国家级非遗"],"members":[["苏绣","江苏苏州，精细雅洁，双面绣"],["湘绣","湖南长沙，狮虎题材"],["蜀绣","四川成都，针法严谨"],["粤绣","广东，色彩浓艳，含广绣潮绣"]],"mem":"口诀就是地名首字“苏湘蜀粤”，正好对应四个省：江苏、湖南、四川、广东。记特色：苏精、湘狮、蜀软、粤艳。","mix":"“四大名锦”是织锦，与“四大名绣”不同（锦是织、绣是刺）；云锦（南京）、蜀锦（成都）、宋锦（苏州）、壮锦（广西）不属于名绣。","mcq":[{"q":"下列属于“四大名绣”的是","o":["云锦","苏绣","宋锦","壮锦"],"a":1,"w":"四大名绣：苏湘蜀粤；云锦、宋锦、壮锦是织锦。"}],"rel":[{"t":"三大名锦（四大名锦）","n":"织锦对举"},{"t":"四大名砚","n":"同属文房手工艺"},{"t":"宋代五大名窑","n":"同类手工艺合称"},{"t":"八大菜系","n":"同样以地域分"}],"more":"苏绣、湘绣、蜀绣、粤绣。","exam":[]},{"id":"b07-050","t":"四大名砚","cid":"07h","p":3,"kind":"合称","alias":["中国四大名砚"],"one":"中国传统文房四宝中广东端砚、安徽歙砚、甘肃洮砚与山西澄泥砚的合称。","ans":"四大名砚是**中国传统文房四宝中砚台的四大杰出代表**。指**广东端砚、安徽歙砚、甘肃洮砚与山西澄泥砚**。端、歙、洮皆由**天然名石精雕**而成；澄泥砚则以**沉淀细泥烧制**而成。四大名砚集实用发墨与案头金石雕刻艺术于一体。","pts":["广东端砚、安徽歙砚、甘肃洮砚、山西澄泥砚","端歙洮为天然石砚，澄泥砚为陶泥烧制","集发墨实用与金石雕刻于一体的文房至宝"],"members":[["端砚","产于广东肇庆（古端州），居四大名砚之首，石质细腻润滑，发墨不损毫，石品丰富"],["歙砚","产于安徽黄山歙县（古徽州），石质坚润细密，纹理天然奇美（如罗纹、金星、眉子纹）"],["洮砚","产于甘肃甘南卓尼县洮河之滨，又称洮河砚，石质碧绿莹润如玉，发墨甚速"],["澄泥砚","产于山西绛州、河南洛阳等地，以特制沉淀过滤的细腻澄泥人工烧结制成，为唯一的陶泥砚"]],"mem":"地名口诀：“**粤端徽歙陇洮河，晋地澄泥烧作砚**”，前三为石砚，唯澄泥是陶砚。","mix":"澄泥砚是四大名砚中唯一的“泥陶烧制砚”（非天然采石）；端砚产于广东肇庆（端州），歙砚产于古徽州歙县。","mcq":[{"q":"在‘中国四大名砚’中，唯一不是利用天然石材雕刻、而是采用细泥人工烧结制成的是","o":["端砚","歙砚","澄泥砚","洮砚"],"a":2,"w":"澄泥砚产于山西绛州等地，以澄滤细泥焙烧而成，属于陶砚。"}],"rel":[{"t":"文房四宝","n":"四大名砚所属总类"},{"t":"宣纸","n":"文房四宝并列项"},{"t":"景泰蓝","n":"同属传统案头工艺珍品"}],"exam":[]},{"id":"b07-051","t":"五岳","cid":"07c","p":2,"kind":"合称","alias":["东岳泰山","西岳华山","南岳衡山","北岳恒山","中岳嵩山"],"one":"东岳泰山、西岳华山、南岳衡山、北岳恒山、中岳嵩山。","ans":"五岳是**中国五大名山**，按方位称**东岳泰山、西岳华山、南岳衡山、北岳恒山、中岳嵩山**，分别位于山东、陕西、湖南、山西、河南。古代帝王有**封禅**与祭祀五岳的制度，泰山居五岳之首，号称“**五岳独尊**”；华山以险著称；嵩山有少林寺和“天地之中”历史建筑群。五岳体现古人的方位观和山岳崇拜，是名山文化的核心。","pts":["东泰西华南衡北恒中嵩","泰山居首，封禅之地","分布在山东、陕西、湖南、山西、河南"],"members":[["东岳泰山","山东泰安，五岳之首"],["西岳华山","陕西华阴，险峻"],["南岳衡山","湖南衡阳"],["北岳恒山","山西浑源，悬空寺"],["中岳嵩山","河南登封，少林寺"]],"mem":"口诀“东泰西华南衡北恒中嵩”。衡恒易混，记地点：衡山在湖南衡阳（南），恒山在山西浑源（北，有悬空寺）。","mix":"衡山与恒山读音相近，常被互换；古代北岳曾指河北曲阳的大茂山，清代改定为山西恒山；“三山”（黄山、庐山、雁荡山）与五岳是两组。","mcq":[{"q":"五岳中的“中岳”是","o":["泰山","嵩山","华山","恒山"],"a":1,"w":"中岳嵩山，在河南登封。"}],"rel":[{"t":"三山五岳之“三山”","n":"与五岳对举"},{"t":"中国文化与自然双遗产","n":"泰山是双遗产"},{"t":"四大佛教名山","n":"名山对照"},{"t":"中国首批世界遗产（1987年6项）","n":"泰山首批入选"}],"exam":[]},{"id":"b07-052","t":"景泰蓝","cid":"07h","p":3,"kind":"常识","alias":["铜胎掐丝珐琅","掐丝珐琅"],"one":"起源于元代、盛行于明代景泰年间的中国传统特种金属手工艺。","ans":"景泰蓝正名为**“铜胎掐丝珐琅”**，是中国传统特种金属手工艺品。元代传入，在**明代景泰年间达到鼎盛**且多用蓝釉而得名。工艺须经**制胎、掐丝、点蓝、烧蓝、磨光、镀金**等繁复工序。融汇**金属造型与珐琅彩绘**，具有典雅华贵的宫廷艺术气派。","pts":["正名铜胎掐丝珐琅，明代景泰年间最盛","主要工序包括制胎、掐丝、点蓝、烧蓝、镀金","融金属铸造与珐琅彩绘于一体的宫廷工艺"],"mem":"六工序口诀：“**胎、丝、点、烧、磨、镀金**，明朝景泰蓝色尊”，以紫铜为胎。","mix":"景泰蓝是“金属工艺”（紫铜胎加珐琅彩），不是瓷器；元代传入中国，明代景泰年间盛行并成熟。","mcq":[{"q":"中国传统工艺特产‘景泰蓝’在工艺学上的正式规范名称是","o":["白铜雕錾青花","紫砂金银错","低温铅釉彩绘","铜胎掐丝珐琅"],"a":3,"w":"景泰蓝正名为铜胎掐丝珐琅，以紫铜作胎，掐细铜丝焊接花纹，填珐琅釉料烧制。"}],"rel":[{"t":"唐三彩","n":"传统工艺釉彩对照"},{"t":"紫砂壶","n":"传统器物工艺对照"},{"t":"景德镇手工瓷业遗存","n":"同属传统器皿手工艺巅峰"}],"exam":[]},{"id":"b07-053","t":"唐三彩","cid":"07h","p":3,"kind":"常识","alias":["唐代三彩釉陶"],"one":"唐代盛行的一种以黄、绿、白三色釉为主的低温彩色铅釉陶制品。","ans":"唐三彩是**唐代盛行的一种低温铅釉彩色陶制品**，盛唐最繁荣，多作**随葬明器**。以白色黏土作胎，以铁铜等金属氧化物呈色，烧出**黄、绿、白等斑斓釉色**。以**三彩马与骆驼俑**造型最为生动，深刻展现了盛唐**开放包容的丝路文化**气象。","pts":["唐代低温彩色铅釉陶器，盛唐最盛","以黄、绿、白为主色，多作随葬明器","三彩马与骆驼俑生动展现丝绸之路盛唐气象"],"mem":"口诀：“**陶胎低温铅釉覆，黄绿白三盛唐马**”，是陶非瓷，开元盛世随葬物。","mix":"唐三彩是“低温陶器”，绝非瓷器；“三”代表多彩，主色为黄、绿、白，偶见蓝、赭；多为随葬明器，非日常餐具。","mcq":[{"q":"关于唐代著名工艺品‘唐三彩’，下列说法正确的是","o":["属于低温铅釉陶器，以黄绿白为主要色彩","是一种高温烧制的彩色瓷器","最初主要用于宫廷文房陈设与日常饮茶","是清代景泰年间盛行的金属手工艺品"],"a":0,"w":"唐三彩是唐代盛行的低温铅釉陶器，主要用作随葬明器，以黄、绿、白三色为主。"}],"rel":[{"t":"景泰蓝","n":"古代工艺器皿对照"},{"t":"敦煌壁画","n":"同属盛唐丝路艺术遗存"},{"t":"丝绸之路","n":"反映丝路贸易交往文化"}],"exam":[]},{"id":"b07-055","t":"古代称谓","cid":"07f","p":1,"kind":"常识","alias":["年龄称谓","弱冠","而立","不惑","知天命","花甲","古稀","及笄"],"one":"弱冠（男20）、而立（30）、不惑（40）、知天命（50）、花甲（60）、古稀（70）；及笄（女15）。","ans":"古代称谓指**以年龄、身份等称呼人的习惯用语**，其中年龄称谓最常考。男子**二十岁称弱冠**，**三十而立，四十不惑，五十知天命，六十花甲（又称耳顺），七十古稀**；女子**十五岁称及笄**，是成年礼。“三十而立”等语出自《论语·为政》，“古稀”出自杜甫“人生七十古来稀”。这套称谓反映了古人对人生阶段的划分和对成年礼的重视。","pts":["男二十弱冠，三十而立，四十不惑","五十知天命，六十花甲，七十古稀","女子十五及笄；出自《论语·为政》"],"mem":"顺口溜：“弱冠二十、而立三十，不惑四十、天命五十，花甲六十、古稀七十”，每十年一档。女子“及笄”记“笄”是簪子，十五岁盘发插簪。","mix":"“耳顺”和“花甲”都指六十岁；“豆蔻”指十三四岁少女，“垂髫”指幼童，“期颐”指百岁，别与成年称谓混；“弱冠”只用于男子。","mcq":[{"q":"古人称“而立之年”是指","o":["二十岁","三十岁","四十岁","五十岁"],"a":1,"w":"《论语》“三十而立”。"},{"q":"古代女子十五岁称","o":["及笄","弱冠","豆蔻","垂髫"],"a":0,"w":"及笄指女子十五岁盘发加笄；弱冠指男子二十岁。"}],"rel":[{"t":"冠礼与笄礼","n":"成年礼"},{"t":"童年与高龄称谓","n":"年龄称谓补充"},{"t":"《论语》","n":"“三十而立”出处"},{"t":"谦辞与敬辞","n":"同属称谓礼仪"}],"more":"吾十有五而志于学，三十而立，四十而不惑，五十而知天命，六十而耳顺，七十而从心所欲，不逾矩。｜《论语·为政》\n人生七十古来稀。｜杜甫《曲江二首》","exam":[]},{"id":"b07-056","t":"古代计时","cid":"07d","p":3,"kind":"常识","alias":["五更","更次","更漏"],"one":"中国古代夜晚将一夜分为五更的计时制度，一更相当于一个时辰（约两小时）。","ans":"古代计时指我国古代通过日晷、漏刻等测定时间的制度。白天以**十二时辰**计时，夜晚则划分为**“五更”**打更报时。自黄昏入夜（戌时）起为**一更**，至黎明平旦（寅时）为**五更**，一更合两小时。该制度紧密关联古代宵禁与作息。","pts":["白日以十二时辰计时，夜晚分五更","一更约两小时，自戌时至寅时","以漏刻打更报时，关联古代作息与宵禁"],"mem":"五更对应时辰：一更戌（黄昏），二更亥（人定），三更子（半夜），四更丑（鸡鸣），五更寅（平旦）。","mix":"“半夜三更”对应子时（23点至次日1点）；更次仅用于夜晚夜禁时段，白天不称更；一更合两小时。","mcq":[{"q":"中国古代民间将夜晚划分为“五更”，常语“半夜三更”所对应的地支时辰是","o":["戌时（19点至21点）","亥时（21点至23点）","丑时（1点至3点）","子时（23点至次日1点）"],"a":3,"w":"古代一夜分五更，三更正值半夜子时（23:00至次日01:00）。"}],"rel":[{"t":"十二时辰","n":"古代地支时辰计时"},{"t":"冬至与夏至","n":"天文晷影测定节气"},{"t":"农历","n":"传统历法计时体系"}],"exam":[]},{"id":"b07-057","t":"冬至与夏至","cid":"07d","p":3,"kind":"常识","alias":["二至","冬至夏至"],"one":"二十四节气中的“二至”，分别代表北半球白昼最短与最长的天文节点。","ans":"冬至与夏至合称“二至”，是我国古代最早确立的**二十四节气核心节点**。**夏至**太阳直射北回归线，北半球**白昼最长、黑夜最短**；**冬至**太阳直射南回归线，北半球**白昼最短、黑夜最长**，标志着开始“数九”，民间有“冬至大如年”之说。","pts":["最早确立的节气节点，并称二至","夏至北半球昼最长，冬至昼最短","冬至起开始数九，民间有冬至大如年之说"],"mem":"昼夜长短口诀：“夏至昼最长（炎热至），冬至昼最短（进九寒）”。","mix":"冬至日太阳直射南回归线，夏至日太阳直射北回归线；春分秋分则昼夜等长；冬至是数九的起点，而非三伏起点。","mcq":[{"q":"太阳直射南回归线、北半球白昼最短而黑夜最长、民间素有“数九”习俗的节气是","o":["冬至","立冬","大雪","小寒"],"a":0,"w":"冬至日太阳直射南回归线，北半球昼最短夜最长，从冬至日起开始“数九”。"}],"rel":[{"t":"二十四节气中的“四立二分二至”","n":"核心八大节气"},{"t":"三伏与数九","n":"节令冷热推算"}],"exam":[]},{"id":"b07-058","t":"中国第一个国家公园","cid":"07a","p":2,"kind":"常识","alias":["首批国家公园","三江源国家公园"],"one":"2021年设立首批五个国家公园：三江源、大熊猫、东北虎豹、海南热带雨林、武夷山。","ans":"2021年10月，中国在《生物多样性公约》第十五次缔约方大会上宣布设立**首批国家公园**，共**五个**：**三江源、大熊猫、东北虎豹、海南热带雨林、武夷山**。国家公园以**保护自然生态系统的原真性和完整性**为首要目标，由国家主导管理，与1982年起设立的国家森林公园、风景名胜区属不同序列。三江源位于青海，是长江、黄河、澜沧江的发源地，被称为“**中华水塔**”。","pts":["2021年设立首批五个国家公园","三江源、大熊猫、东北虎豹、海南雨林、武夷山","保护生态系统原真性，区别于森林公园"],"mem":"自编口诀“三熊虎雨武”：三江源、大熊猫、东北虎豹、海南雨林、武夷山。动物线索：熊猫、虎豹、海南长臂猿，加一个水源地和一座名山。","mix":"张家界是1982年的国家森林公园，不在首批国家公园之列；三江源2016年起先行体制试点，2021年才正式设立。","mcq":[{"q":"2021年中国设立的首批国家公园不包括","o":["三江源国家公园","大熊猫国家公园","张家界国家公园","武夷山国家公园"],"a":2,"w":"张家界是1982年设立的国家森林公园，不属于首批国家公园。"}],"rel":[{"t":"张家界国家森林公园","n":"体系不同，常被对举"},{"t":"中国文化与自然双遗产","n":"武夷山是双遗产"},{"t":"世界遗产类型","n":"武夷山的遗产类型"}],"more":"首批国家公园（2021）：三江源、大熊猫、东北虎豹、海南热带雨林、武夷山","exam":[]},{"id":"b07-059","t":"风筝之都等","cid":"07h","p":3,"kind":"常识","alias":["特色工艺名城","风筝之都"],"one":"山东潍坊风筝、江西景德镇瓷器、浙江龙泉青瓷等特色手工艺名城的合称。","ans":"“风筝之都等”指**中国享有传统工艺盛名的一组历史文化名城**。包括被誉为“世界风筝都”的**山东潍坊**；“千年瓷都”**江西景德镇**；以及出产龙泉青瓷与宝剑的**浙江龙泉**（龙泉青瓷为人类非遗）。展现了**鲜明的地域民间手工艺传承**。","pts":["山东潍坊誉为“世界风筝都”，风筝列入非遗","江西景德镇誉为“瓷都”，瓷器享誉全球","浙江龙泉出青瓷与宝剑，龙泉青瓷为人类非遗"],"mem":"名城对联：“**潍坊鸢飞青云上，景德瓷润万户光，龙泉青瓷照古今**”。","mix":"潍坊为“风筝之都”（杨家埠为四大年画之一）；景德镇为“瓷都”（2026年手工瓷业遗存申遗）；龙泉青瓷是全球首个单独入选人类非遗的陶瓷类项目。","mcq":[{"q":"被誉为‘世界风筝都’、每年举办国际风筝会的手工艺名城是","o":["江苏苏州","山东潍坊","江西景德镇","浙江龙泉"],"a":1,"w":"山东潍坊被称为‘风筝之都’，其风筝扎制与杨家埠木版年画闻名中外。"}],"rel":[{"t":"景德镇手工瓷业遗存","n":"瓷都景德镇世界文化遗产"},{"t":"四大年画","n":"潍坊杨家埠为四大年画产地"},{"t":"中国剪纸","n":"同属民间传统造型艺术"}],"exam":[]},{"id":"b07-060","t":"代表性传承人","cid":"07a","p":3,"kind":"概念","alias":["非遗传承人","国家级代表性传承人"],"one":"经文化主管部门认定、承担非物质文化遗产传续责任的代表性个人。","ans":"代表性传承人是指经**文化行政部门**认定，熟练掌握非物质文化遗产并承担**传续责任**的个人。我国自2007年起开展**国家级代表性传承人**认定，享有传习补助，承担授徒传艺义务，是非物质文化遗产**活态传承**的核心载体。","pts":["主管部门认定的非遗传承者","国家级认定始于2007年","享有传习补助并承担授徒责任"],"mem":"记非遗传承“人亡技绝”的风险，故2007年起官方认定“代表性传承人”发传习补助。","mix":"代表性传承人认定给具体个人；国家级非遗名录认定的则是具体项目。","mcq":[{"q":"我国国家级非物质文化遗产代表性传承人认定工作正式启动于","o":["2001年","2004年","2007年","2011年"],"a":2,"w":"我国于2007年启动第一批国家级非物质文化遗产代表性传承人认定工作。"}],"rel":[{"t":"国家级非物质文化遗产代表性项目名录","n":"非遗保护项目名录"},{"t":"文化和自然遗产日","n":"非遗宣传保护节日"}],"exam":[]},{"id":"b07-061","t":"生产性保护","cid":"07a","p":3,"kind":"概念","alias":["非遗生产性保护"],"one":"将具备生产转化条件的非遗转化为产品，实现活态保护传承的机制。","ans":"生产性保护是指在保持非遗真实性与核心技艺的前提下，借助**生产、流通、销售**等手段将非遗转化为文化产品的保护方式。该模式主要适用于**传统技艺**、**传统美术**与**传统医药**等门类，推动非遗融入现代生活，实现**活态传承**与发展。","pts":["通过生产流通销售转化保护非遗","主要适用于传统技艺、美术和医药","保持核心技艺的前提下融入现代生活"],"mem":"生产性保护口诀：“技艺变产品，在用中活态传”，专针对吃穿用药等手艺。","mix":"适用于具备实用制作功能的传统技艺、美术、医药；不可套用于神话传说、民歌舞蹈等精神表现类非遗。","mcq":[{"q":"“生产性保护”作为我国非物质文化遗产保护的重要方式，最主要适用于下列哪一类项目","o":["民间神话与史诗传说","传统民间音乐与舞蹈","岁时节令与民间竞技","传统手工技艺与传统医药"],"a":3,"w":"生产性保护主要适用于传统技艺、传统美术和传统医药等具备生产转化条件的非遗门类。"}],"rel":[{"t":"国家级非物质文化遗产代表性项目名录","n":"非遗保护项目名录"},{"t":"文化和自然遗产日","n":"非遗宣传保护节日"}],"exam":[]},{"id":"b07-062","t":"濒危世界遗产","cid":"07a","p":3,"kind":"概念","alias":["濒危世界遗产名录"],"one":"联合国教科文组织设立的面临严重蜕变或毁灭威胁的世界遗产保护名录。","ans":"濒危世界遗产指列入联合国教科文组织**《濒危世界遗产名录》**的遗产地。当世界遗产面临战争冲突、自然灾害、过度开发等**严重威胁**时，世界遗产委员会将其列入该名录，旨在动员国际力量开展**紧急抢救与资金技术援助**，价值彻底丧失者将被除名。","pts":["教科文组织设立的抢救名录","面临战争灾害或破坏等严重威胁","动员国际援助，丧失价值将被除名"],"mem":"濒危遗产是国际“亮黄牌”，动员全球抢救；彻底损毁则出示“红牌除名”。","mix":"濒危世界遗产针对有形文化与自然遗产；针对非物质文化遗产的急需抢救名录为“急需保护的非物质文化遗产名录”。","mcq":[{"q":"联合国教科文组织对面临严重自然灾害或战争威胁、急需国际抢救的世界遗产采取的保护机制是","o":["交由国际古迹遗址理事会托管","暂停所在缔约国的履约资格","列入《濒危世界遗产名录》","列入《世界记忆名录》"],"a":2,"w":"面临严重且具体威胁的世界遗产，会被列入《濒危世界遗产名录》以启动紧急援助。"}],"rel":[{"t":"《保护世界文化和自然遗产公约》","n":"设立依据公约"},{"t":"世界遗产类型","n":"世界遗产体系划分"},{"t":"世界文化遗产","n":"世界遗产分类"}],"exam":[]},{"id":"b07-063","t":"倮倮","cid":"07e","p":3,"kind":"常识","exam":["2012选择"],"alias":["罗罗"],"one":"我国少数民族彝族的旧称，新中国成立后统一定名为彝族。","ans":"倮倮是**中国少数民族彝族的旧称**，多见于旧史籍，为带有贬义色彩的他称。主要分布在**云南、四川、贵州**等西南地区。新中国成立后遵循民族平等原则，正式定名为**“彝族”**（寓意丰衣足食）。彝族拥有独特的**十月太阳历**与火把节民俗。","pts":["彝族的旧称或他称，旧志多见","主要分布在川滇黔等西南地区","新中国成立后按民族平等原则定名彝族"],"mem":"联想：“**旧称倮倮含贬义，新朝改彝表平等**”，彝字寓意有米有丝丰衣足食。","mix":"倮倮是彝族的旧称（他称），并非独立民族，彝族自称多为诺苏等；2012年交大选择题考查其对应民族。","mcq":[{"q":"在我国民族学与历史文献中，“倮倮”曾是下列哪个少数民族的旧称","o":["纳西族","彝族","白族","傣族"],"a":1,"w":"新中国成立后废除“倮倮”旧称，统一定名为彝族。"}],"rel":[{"t":"《远方的客人请你留下来》","n":"取材彝族撒尼人曲调"},{"t":"《阿诗玛》","n":"彝族撒尼人民间叙事诗"},{"t":"端午节","n":"同属传统节庆民俗"}]},{"id":"b07-064","t":"《远方的客人请你留下来》","cid":"07e","p":3,"kind":"作品","exam":["2022选择"],"one":"1953年范禹词、麦丁曲，取材云南彝族撒尼人曲调的经典民歌。","ans":"《远方的客人请你留下来》是**1953年创作的著名经典民族歌曲**，由**范禹作词、麦丁作曲**。作品**取材于云南彝族撒尼人的传统民歌调**，旋律热情真挚，展现了各族人民好客与团结情谊，是**少数民族风格声乐作品的代表作**。","pts":["1953年范禹作词、麦丁作曲","取材云南彝族撒尼人民间曲调","表现好客与民族团结的经典歌曲"],"mem":"口诀：“**范禹作词麦丁曲，撒尼欢歌彝族情**”，交大2022届考查所属民族。","mix":"取材自云南彝族撒尼人传统曲调，常被误作为白族或傣族民歌；交大2022选择题考查此曲属于哪个民族（彝族）。","mcq":[{"q":"著名歌曲《远方的客人请你留下来》取材于下列哪个少数民族支系的民间曲调","o":["白族民家","傣族水傣","彝族撒尼人","壮族布依"],"a":2,"w":"1953年范禹词、麦丁曲，取材于云南石林彝族撒尼人民间曲调。"}],"rel":[{"t":"倮倮","n":"同属彝族文化考题"},{"t":"《阿诗玛》","n":"同源撒尼人文学艺术"},{"t":"音乐舞蹈史诗《东方红》","n":"收录该曲展现民族团结"}],"alias":[]},{"id":"b07-065","t":"围棋与国际象棋","cid":"07h","p":2,"kind":"常识","exam":["2013名解"],"alias":["围棋","国际象棋","弈"],"one":"围棋源于中国，围地多少定胜负；国际象棋源于印度，以将死国王取胜。","ans":"围棋与国际象棋是**东西方两种代表性的棋类**。**围棋起源于中国**，古称“弈”，是琴棋书画“四艺”之一，在19路棋盘上**以围地多少定胜负**。**国际象棋源于古印度的“恰图兰卡”**，经波斯、阿拉伯传入欧洲，**以将死对方国王取胜**。两者在人工智能史上有标志性事件：**1997年IBM“深蓝”战胜国际象棋世界冠军卡斯帕罗夫，2016年AlphaGo战胜围棋名将李世石**，后者因围棋变化远多而更受关注。","pts":["围棋：中国起源，古称弈，围地多少定胜负","国际象棋：源于印度，将死国王取胜","1997深蓝胜卡斯帕罗夫，2016AlphaGo胜李世石"],"mem":"一张对照表：围棋＝中国＝围地＝361点；国际象棋＝印度→波斯→阿拉伯→欧洲＝将死＝64格。AI两件事按顺序：先是国际象棋（1997深蓝），后是围棋（2016AlphaGo），围棋更难所以晚19年。","mix":"围棋比国际象棋的搜索空间大得多，所以AlphaGo胜李世石晚于深蓝；中国象棋是第三种棋，规则是将帅对垒，与两者都不同。","mcq":[{"q":"1997年战胜国际象棋世界冠军卡斯帕罗夫的计算机是","o":["AlphaGo","深蓝","沃森","ChatGPT"],"a":1,"w":"IBM“深蓝”；AlphaGo是2016年战胜李世石。"},{"q":"围棋胜负的判定依据是","o":["将死对方国王","吃掉对方全部棋子","围地多少","先到对方底线"],"a":2,"w":"围棋以围地多少定胜负。"}],"rel":[{"t":"AlphaGo","n":"2016年战胜李世石"},{"t":"文人四艺（琴棋书画）","n":"围棋为“棋”"},{"t":"围棋“收官”","n":"围棋术语"},{"t":"“人工智能+”行动","n":"AI发展背景"}],"more":"围棋：19×19路、361个交叉点，黑先白后。\n国际象棋：8×8共64格，源于印度恰图兰卡。\n2017年AlphaGo再胜柯洁。"},{"id":"b07-066","t":"岷山","cid":"07a","p":3,"kind":"地理","exam":["2016名解"],"alias":["岷山山脉"],"one":"川甘交界著名山脉，长江水系岷江发源地，长征翻越的标志性雪山。","ans":"岷山是横亘于**四川北部与甘肃南部交界**的著名山脉，呈西北至东南走向，主峰为**雪宝顶**。岷山是长江支流**岷江**的发源地，分布有九寨沟、黄龙等自然名胜。红军长征翻越此山，毛泽东在**《七律·长征》**中留有“**更喜岷山千里雪**”的名句。","pts":["川甘交界山脉，主峰雪宝顶","岷江发源地，九寨沟黄龙所在地","红军长征翻越，毛泽东七律长征名句"],"mem":"记三点：川甘交界、岷江源头、毛泽东诗“更喜岷山千里雪”。","mix":"岷江是长江支流，发源于岷山；嘉陵江支流白龙江亦发源于此；不可误记为黄河发源地。","mcq":[{"q":"毛泽东在《七律·长征》中写下“更喜岷山千里雪，三军过后尽开颜”。岷山位于哪两省交界","o":["四川省与甘肃省","四川省与青海省","陕西省与四川省","四川省与西藏自治区"],"a":0,"w":"岷山横亘于四川省北部与甘肃省南部交界处。"}],"rel":[{"t":"蜀郡","n":"同处古蜀地理范畴"},{"t":"毛泽东思想","n":"长征诗作创作背景"}]},{"id":"b07-067","t":"蜀郡","cid":"07a","p":3,"kind":"地理","exam":["2016名解"],"alias":["蜀郡太守"],"one":"秦汉时期在古蜀地设立的行政建制，治所成都，以李冰治水、文翁兴学闻名。","ans":"蜀郡是秦汉时期的**重要地方行政建制**。秦灭古蜀后设置，**治所设于成都**。战国秦昭王时**蜀郡守李冰**主持兴建**都江堰**，造就了成都平原“天府之国”；西汉**蜀郡守文翁**在成都兴办“石室学堂”，开创了中国地方政府兴办**官学**的先河。","pts":["秦灭古蜀后设置，治所成都","秦昭王时李冰建都江堰造就天府之国","西汉文翁兴学创建中国最早地方官学"],"mem":"蜀郡两名守：李冰治水造天府（都江堰），文翁兴学开石室（官学之祖）。","mix":"都江堰由战国秦昭王时蜀郡守李冰修建，而非秦始皇；文翁石室为地方官学之始，太学则是中央官学。","mcq":[{"q":"战国秦昭王时期，主持兴建都江堰水利工程、造就天府之国的蜀郡太守是","o":["西门豹","李冰","郑国","文翁"],"a":1,"w":"秦国蜀郡太守李冰父子主持修建了都江堰水利工程；文翁为西汉蜀郡太守，以兴学闻名。"}],"rel":[{"t":"青城山—都江堰","n":"蜀郡太守李冰主持修建"},{"t":"岷山","n":"岷江发源于此流入蜀郡"}]},{"id":"b07-068","t":"整体性保护","cid":"07a","p":3,"kind":"概念","alias":["文化生态保护","整体性保护原则"],"one":"将非遗及其依存的人文与自然生态环境进行系统协同保护的非遗工作原则。","ans":"整体性保护是我国非遗保护的核心原则。它强调将**非遗项目本身**与**传承人、文化空间及依存的人文生态环境**进行系统保护。代表性举措是设立**国家级文化生态保护区**，2007年设立首个“**闽南文化生态保护实验区**”。","pts":["非遗保护核心原则，强调系统协同保护","保护项目、传承人及依存的人文生态环境","设立文化生态保护区，2007年首设闽南实验区"],"mem":"整体性保护记“三位一体”：护技艺、护传人、护文化生态（2007闽南实验区）。","mix":"易与“生产性保护”混淆：生产性保护侧重手工艺的市场生产流通；整体性保护侧重整个文化空间与生态环境的连带维护。","mcq":[{"q":"2007年我国设立的第一个国家级文化生态保护实验区是","o":["徽州文化生态保护实验区","热贡文化生态保护实验区","闽南文化生态保护实验区","羌族文化生态保护实验区"],"a":2,"w":"2007年文化部批准设立闽南文化生态保护实验区，是我国首个国家级文化生态保护实验区。"}],"rel":[{"t":"国家级非物质文化遗产代表性项目名录","n":"非遗保护项目名录"},{"t":"文化和自然遗产日","n":"非遗宣传保护节日"}],"exam":[]},{"id":"c-043","t":"六大茶类","cid":"07h","p":1,"kind":"合称","exam":["2025选择"],"alias":["茶叶六大类","绿茶","白茶","黄茶","红茶","黑茶"],"one":"绿、白、黄、青（乌龙）、红、黑六类，按加工工艺和品质特征分。","ans":"六大茶类是**按加工工艺、产品特性等划分的六类茶**：**绿茶（不发酵）、白茶（微发酵）、黄茶（轻发酵）、青茶即乌龙茶（半发酵）、红茶（全发酵）、黑茶（后发酵）**。代表茶有绿茶西湖龙井、碧螺春，白茶白毫银针，黄茶君山银针，青茶安溪铁观音、武夷大红袍，红茶祁门红茶，黑茶安化黑茶、普洱熟茶。不同加工方式形成各类茶特有的茶汤与滋味，是中国茶文化的基本分类。","pts":["绿白黄青红黑，按加工工艺和品质特征分","代表茶：龙井、银针、铁观音、祁红","青茶即乌龙茶，半发酵"],"members":[["绿茶","不发酵：西湖龙井、碧螺春、黄山毛峰"],["白茶","微发酵：白毫银针、白牡丹"],["黄茶","轻发酵（闷黄）：君山银针"],["青茶（乌龙茶）","半发酵：安溪铁观音、武夷大红袍、冻顶乌龙"],["红茶","全发酵：祁门红茶、正山小种"],["黑茶","后发酵：安化黑茶、普洱熟茶"]],"mem":"顺序“绿白黄青红黑”，这些是工艺类别，黑茶的“后发酵”与红茶的“全发酵”按不同工艺区分。“白茶”是“微”，因为几乎不动它；红茶“全”，叶子都红了。","mix":"白毫银针（白茶）与君山银针（黄茶）名字相近，易混；乌龙=青茶；普洱茶分生茶、熟茶，熟茶属黑茶；“半发酵”只有青茶。","mcq":[{"q":"君山银针属于","o":["绿茶","黄茶","白茶","青茶"],"a":1,"w":"君山银针产于湖南岳阳君山，是黄茶代表；白毫银针属白茶。"},{"q":"六大茶类中，属于全发酵茶的是","o":["绿茶","青茶","黑茶","红茶"],"a":3,"w":"红茶为全发酵；绿茶不发酵，青茶半发酵，黑茶后发酵。"}],"rel":[{"t":"乌龙茶","n":"青茶"},{"t":"中国十大名茶","n":"代表茶"},{"t":"八大菜系","n":"同属饮食文化"},{"t":"陆羽《茶经》","n":"茶学典籍"},{"t":"中国传统制茶技艺及其相关习俗","n":"2022年入选人类非遗"}],"more":"2022年“中国传统制茶技艺及其相关习俗”列入人类非遗代表作名录。"},{"id":"a07-001","t":"《保护世界文化和自然遗产公约》","cid":"07a","p":2,"kind":"制度","alias":["世界遗产公约","1972年公约"],"one":"1972年教科文组织通过的世界遗产公约，中国1985年加入。","ans":"《保护世界文化和自然遗产公约》是**联合国教科文组织大会1972年通过**的国际公约，通称《世界遗产公约》，确立了**世界遗产名录**制度，并设立世界遗产委员会和世界遗产基金。公约把遗产分为文化遗产和自然遗产，各缔约国负责保护境内遗产，国际社会协助。**中国1985年加入**，1987年首批**6项**列入名录。它与2003年管无形遗产的《保护非物质文化遗产公约》**分管两类遗产**。","pts":["1972年联合国教科文组织大会通过","确立世界遗产名录，文化与自然两类","中国1985年加入，1987年首批6项"],"mem":"年份链：七二立约，八五入约，八七首批；2003年另立非遗公约管“活”的遗产。","mix":"2003年公约管非物质文化遗产，1972年公约管有形的文化与自然遗产，易被互换。","mcq":[{"q":"中国加入《保护世界文化和自然遗产公约》的年份是","o":["1972年","1985年","1987年","2003年"],"a":1,"w":"1972年公约通过，中国1985年加入，1987年首批项目入选。"}],"rel":[{"t":"联合国教科文组织","n":"公约的主管机构"},{"t":"世界文化遗产","n":"公约下的类别"},{"t":"非物质文化遗产","n":"另一公约，对照"},{"t":"中国首批世界遗产（1987年6项）","n":"加入后的首批成果"},{"t":"世界遗产类型","n":"公约确立的分类"}],"exam":[]},{"id":"a07-002","t":"中国首批世界遗产（1987年6项）","cid":"07a","p":1,"kind":"合称","alias":["中国首批世界遗产","首批六项世界遗产","1987年世界遗产"],"one":"1987年入选的六项：长城、故宫、莫高窟、秦陵、周口店、泰山。","ans":"中国首批世界遗产指**1987年列入《世界遗产名录》的六项**，是中国1985年加入《保护世界文化和自然遗产公约》后的第一批申报成果。六项为**长城、明清皇宫（北京故宫，2004年增沈阳故宫）、莫高窟、秦始皇陵及兵马俑坑、周口店北京人遗址、泰山**。其中**泰山是中国第一个文化与自然双遗产**，其余五项为文化遗产。这一批覆盖古建筑、石窟艺术、帝陵和古人类遗址，是此后中国遗产申报的起点。","pts":["1987年入选六项，1985年加入公约","长城、故宫、莫高窟、秦陵、周口店、泰山","泰山是中国第一个文化与自然双遗产"],"members":[["长城","文化遗产，北方多省"],["明清皇宫（北京故宫）","文化遗产，2004年增沈阳故宫"],["莫高窟","文化遗产，甘肃敦煌"],["秦始皇陵及兵马俑坑","文化遗产，陕西西安"],["周口店北京人遗址","文化遗产，北京"],["泰山","文化与自然双遗产，山东泰安"]],"mem":"按“一墙一宫一窟一陵一洞一山”记：墙（长城）、宫（故宫）、窟（莫高窟）、陵（秦陵）、洞（周口店北京人）、山（泰山）。只有最后的山是双遗产，也是六项里唯一的自然与文化兼具。","mix":"后来才入选的有苏州园林、黄山（1990，双遗产）、布达拉宫（1994）、殷墟（2006）等，常作干扰项；2024选择对首批措辞存疑，按整体六项掌握。","mcq":[{"q":"1987年中国首批世界遗产中，属于文化与自然双遗产的是","o":["长城","莫高窟","周口店北京人遗址","泰山"],"a":3,"w":"泰山是中国第一个双遗产，其余五项均为文化遗产。"},{"q":"下列属于中国首批（1987年）世界遗产的是","o":["殷墟","秦始皇陵及兵马俑坑","丽江古城","苏州古典园林"],"a":1,"w":"殷墟2006年、丽江古城1997年、苏州古典园林1997年才入选。"}],"rel":[{"t":"世界文化遗产","n":"总体概念"},{"t":"中国文化与自然双遗产","n":"泰山是第一个"},{"t":"殷墟","n":"后来入选的考古遗址"},{"t":"中国近年新增世界遗产","n":"后续新增"}],"more":"莫高窟、泰山、长城等首批项目于1987年12月列入。","exam":[]},{"id":"a07-003","t":"中国文化与自然双遗产","cid":"07a","p":2,"kind":"合称","alias":["双遗产","中国双遗产"],"one":"泰山、黄山、峨眉山—乐山大佛、武夷山，中国四项文化与自然双遗产。","ans":"中国文化与自然双遗产指**同时具备文化与自然价值**的世界遗产，共**四项**：**泰山（1987年）、黄山（1990年）、峨眉山—乐山大佛（1996年）、武夷山（1999年）**。其中**泰山是中国第一个双遗产**，也是1987年首批6项中唯一的双遗产。四处都是名山，既有地质和生态景观，又承载宗教、封禅或摩崖石刻等文化遗存。","pts":["四项：泰山、黄山、峨眉山—乐山大佛、武夷山","泰山1987年，中国第一个双遗产","兼具文化与自然价值"],"members":[["泰山","1987年，山东，中国第一个双遗产"],["黄山","1990年，安徽"],["峨眉山—乐山大佛","1996年，四川"],["武夷山","1999年，福建"]],"mem":"口诀“泰黄峨武”（太黄鹅舞），年份依次为87、90、96、99，逐步递增。","mix":"庐山是文化景观（1996），张家界是自然遗产（1992），华山、衡山、嵩山不是双遗产。","mcq":[{"q":"下列不属于中国世界文化与自然双遗产的是","o":["泰山","黄山","峨眉山—乐山大佛","庐山"],"a":3,"w":"庐山1996年作为文化景观列入，属文化遗产。"}],"rel":[{"t":"世界遗产类型","n":"混合遗产的分类依据"},{"t":"中国首批世界遗产（1987年6项）","n":"泰山首批入选"},{"t":"五岳","n":"泰山为五岳之首"},{"t":"张家界国家森林公园","n":"自然遗产对照"}],"exam":[]},{"id":"a07-004","t":"青城山—都江堰","cid":"07a","p":2,"kind":"地理","alias":["都江堰","青城山","都江堰水利工程"],"one":"战国李冰主持修建的无坝引水工程，2000年与青城山一起列入世界遗产。","ans":"都江堰位于四川成都平原西部的岷江出山口，由**战国时秦蜀郡守李冰主持修建**，是**无坝引水**的水利工程。渠首由**鱼嘴分水、飞沙堰泄洪排沙、宝瓶口引水**三部分配合，兼顾分洪、排沙和灌溉，使成都平原成为“**天府之国**”。**2000年**与道教名山青城山一起列入**世界文化遗产**。工程两千多年来仍在使用，是中国古代水利科技的代表。","pts":["战国秦蜀郡守李冰主持修建","无坝引水：鱼嘴、飞沙堰、宝瓶口","2000年与青城山列入世界文化遗产"],"mem":"三个部件顺口溜：鱼嘴分、飞沙泄、宝瓶引。画面：江水被“鱼嘴”劈成两股，洪水从“飞沙堰”溢走，清水从“宝瓶口”流进成都平原。","mix":"郑国渠在关中，灵渠在广西，二者与都江堰并称秦代三大水利工程；都江堰无坝，不是拦河筑坝。","mcq":[{"q":"都江堰的主持修建者是","o":["郑国","史禄","李冰","郭守敬"],"a":2,"w":"李冰为战国秦蜀郡守；郑国修郑国渠，史禄修灵渠。"}],"rel":[{"t":"秦代三大水利工程","n":"同组工程"},{"t":"世界文化遗产","n":"所属类别"},{"t":"道教四大名山","n":"青城山属其一"},{"t":"《保护世界文化和自然遗产公约》","n":"申遗依据"}],"exam":[]},{"id":"a07-005","t":"秦始皇陵及兵马俑坑","cid":"07a","p":3,"kind":"地理","alias":["秦始皇陵","秦陵兵马俑","秦兵马俑"],"one":"中国首批世界文化遗产，秦代帝陵与大型陶俑军阵陪葬坑，誉为“世界第八大奇迹”。","ans":"秦始皇陵及兵马俑坑位于陕西西安临潼。**1974年发现兵马俑**，出土数千件写实陶俑陶马。**1987年被列入中国首批《世界遗产名录》**。该遗存展现了秦代精湛的雕塑技艺与严整的军阵制度，被誉为**“世界第八大奇迹”**。","pts":["陕西临潼，1974年发现兵马俑","1987年列入中国首批世界文化遗产","写实陶俑军阵，誉为世界第八大奇迹"],"mem":"记两组核心年份：1974年被发现（打井刨出），1987年首批列入世遗。","mix":"兵马俑是秦始皇陵东侧的从葬坑，并非秦陵地宫内部；地宫至今尚未发掘。","mcq":[{"q":"兵马俑坑被当地农民打井偶然发现于哪一年，并于哪一年被列入中国首批世界遗产","o":["1965年、1985年","1972年、1986年","1978年、1990年","1974年、1987年"],"a":3,"w":"兵马俑于1974年被发现，1987年与长城、故宫等一同列入中国首批世界遗产。"}],"rel":[{"t":"中国首批世界遗产（1987年6项）","n":"1987年首批入选世界遗产"},{"t":"世界文化遗产","n":"世界遗产分类"}],"exam":[]},{"id":"a07-006","t":"大运河","cid":"07a","p":3,"kind":"地理","alias":["中国大运河","京杭大运河","隋唐大运河"],"one":"世界上开凿最早、里程最长的人工运河，2014年列入世界文化遗产。","ans":"大运河是世界上里程最长的人工运河。**隋代开凿以洛阳为中心的大运河**，沟通五大水系；**元代截弯取直形成京杭大运河**。**2014年中国大运河列入《世界遗产名录》**。它是维系古代国家统一与南北物资流通的命脉。","pts":["隋代开凿隋唐大运河，沟通五大水系","元代截弯取直形成京杭大运河","2014年列入世界文化遗产，南北经济命脉"],"mem":"运河演变：隋代以洛阳为中心人字形，元代截弯取直直通南北，2014年申遗。","mix":"隋唐大运河中心在洛阳，京杭大运河截弯取直直通北京；申遗项目涵盖隋唐大运河、京杭大运河与浙东运河。","mcq":[{"q":"中国古代为了缩短航程并直达大都（北京），对大运河进行“截弯取直”的朝代是","o":["唐代","宋代","明代","元代"],"a":3,"w":"元代定都大都后，截弯取直开挖会通河等，使大运河直通南北不再绕经洛阳。"}],"rel":[{"t":"京杭大运河","n":"大运河元代以来的核心段落"},{"t":"隋炀帝与大运河","n":"开凿隋唐大运河的历史人物"},{"t":"世界文化遗产","n":"2014年入选世界遗产"}],"exam":[]},{"id":"a07-007","t":"丝绸之路：长安-天山廊道路网","cid":"07a","p":3,"kind":"地理","alias":["丝绸之路世界遗产","长安-天山廊道路网"],"one":"2014年列入世界遗产，中国与哈萨克斯坦、吉尔吉斯斯坦首个跨国联合申遗项目。","ans":"丝绸之路：长安-天山廊道路网是古代丝路东段主干。**2014年由中国、哈萨克斯坦、吉尔吉斯斯坦联合申报列入《世界遗产名录》**，是我国**首个跨国联合申遗项目**。涵盖汉魏洛阳城遗址、高昌故城等**33处代表性遗迹**，见证了东西方文明交流。","pts":["中哈吉三国联合申报，2014年入选世界遗产","我国首个跨国联合申报世界遗产项目","全长约5000公里，涵盖33处代表性遗产点"],"mem":"跨国申遗记“中哈吉三剑客”：中国、哈萨克斯坦、吉尔吉斯斯坦，2014年与大运河同年申遗。","mix":"联合申报国为中国、哈萨克斯坦、吉尔吉斯斯坦三国，不含乌兹别克斯坦；东起汉魏洛阳城与汉长安城，非仅限于西安。","mcq":[{"q":"2014年与中国大运河一同成功列入《世界遗产名录》的中国首个跨国联合申报项目是","o":["丝绸之路：长安-天山廊道路网","海上丝绸之路古港遗址","万里茶道遗产廊道","茶马古道文化线路"],"a":0,"w":"2014年第38届世界遗产大会上，大运河与“丝绸之路：长安-天山廊道路网”双双列入世界遗产。"}],"rel":[{"t":"丝绸之路","n":"丝绸之路东段廊道路网"},{"t":"大运河","n":"2014年同年列入世界遗产"},{"t":"世界文化遗产","n":"世界遗产分类"}],"exam":[]},{"id":"a07-008","t":"北京中轴线","cid":"07a","p":3,"kind":"地理","alias":["北京中轴线建筑群","北京中轴线申遗项目"],"one":"北起钟鼓楼、南至永定门的古都建筑轴线，2024年列入中国第59项世界遗产。","ans":"北京中轴线全长7.8公里，始建于元代，成型于明清。**南起永定门，北至钟鼓楼**，贯穿紫禁城等重要遗存。**2024年列入《世界遗产名录》，成为中国第59项世界遗产**。其体现了“居中而治”与**“左祖右社”**的传统礼制秩序。","pts":["北起钟鼓楼南至永定门，全长7.8公里","2024年列入世界遗产，中国第59项","体现中国传统理想都城规划秩序"],"mem":"记端点与序数：南永定北钟鼓，纵贯老城7.8公里，2024年第59项世遗。","mix":"南起永定门、北至钟鼓楼，全长7.8公里；不包括西北郊的颐和园或圆明园。","mcq":[{"q":"2024年7月成功列入《世界遗产名录》、成为中国第59项世界遗产的是","o":["普洱景迈山古茶林文化景观","北京中轴线","西夏陵","景德镇手工瓷业遗存"],"a":1,"w":"北京中轴线建筑群于2024年列入世界遗产，为中国第59项世界遗产。"}],"rel":[{"t":"世界文化遗产","n":"世界遗产分类"},{"t":"中国近年新增世界遗产","n":"近年新增世遗项目"}],"exam":[]},{"id":"a07-009","t":"西夏陵","cid":"07a","p":3,"kind":"地理","alias":["西夏王陵","西夏皇陵"],"one":"宁夏银川贺兰山麓的西夏皇家陵寝，2025年列入中国第60项世界遗产。","ans":"西夏陵位于**宁夏银川贺兰山东麓**，是西夏王朝皇家陵寝群，包含9座帝陵与270余处陪葬墓。其融合唐宋制度、**党项族风俗**与佛教形制。**2025年被列入《世界遗产名录》，成为中国第60项世界遗产**，实证了中华文明多元一体进程。","pts":["位于宁夏银川贺兰山东麓，西夏帝王陵寝","融合唐宋陵制与党项风俗、佛教形制","2025年列入世界遗产，中国第60项"],"mem":"贺兰山下“东方金字塔”：西夏陵，2025年申遗成功，中国第60项世遗。","mix":"西夏陵位于宁夏银川，属于党项族西夏王朝；非黑水城遗址（在内蒙古额济纳旗）。","mcq":[{"q":"2025年7月在第47届世界遗产大会上列入《世界遗产名录》、成为中国第60项世界遗产的是","o":["北京中轴线","景德镇手工瓷业遗存","西夏陵","巴丹吉林沙漠"],"a":2,"w":"西夏陵于2025年申遗成功，成为中国第60项世界遗产，也是宁夏首项世界文化遗产。"}],"rel":[{"t":"中国近年新增世界遗产","n":"近年新增世界遗产"},{"t":"世界文化遗产","n":"世界遗产分类"}],"exam":[]},{"id":"a07-010","t":"春节列入人类非遗代表作名录","cid":"07a","p":1,"kind":"时事","alias":["春节申遗","春节入选人类非遗","春节：中国人庆祝传统新年的社会实践","春节确定为联合国假日"],"one":"2024年12月4日在巴拉圭亚松森列入，中国人类非遗项目共44项。","ans":"**2023年12月22日，第78届联合国大会协商一致通过决议，将春节（农历新年）正式确定为联合国假日**。一年后的**2024年12月4日**，联合国教科文组织在**巴拉圭亚松森**审议通过，**“春节：中国人庆祝传统新年的社会实践”**正式列入**人类非物质文化遗产代表作名录**，此后我国入选人类非遗代表作总数达**44项**，使春节文化走向全球共通遗产。","pts":["2023年12月22日：第78届联大将春节确定为联合国假日","2024年12月4日：巴拉圭亚松森列入联合国教科文组织人类非遗名录","列入后中国人类非遗代表作共44项，系继端午后又一入选节俗"],"mem":"时间地点三要素：2024年12月4日、亚松森（Asunción，巴拉圭首都）、44项。节日线：端午2009年第一个，春节2024年再添一个，相隔15年。","mix":"端午节2009年是第一个入选的中国传统节日；二十四节气2016年入选，属知识与实践而非节日；春节申遗名称强调“社会实践”。","mcq":[{"q":"春节列入联合国教科文组织人类非遗代表作名录的年份是","o":["2009年","2016年","2022年","2024年"],"a":3,"w":"2009年是端午节，2016年是二十四节气，2024年12月是春节。"},{"q":"春节申遗成功的会议举办地是","o":["巴拉圭亚松森","韩国釜山","印度新德里","摩洛哥拉巴特"],"a":0,"w":"2024年12月4日在巴拉圭亚松森举行的政府间委员会会议上通过。"}],"rel":[{"t":"端午节","n":"首个入选的中国节日"},{"t":"非物质文化遗产","n":"所属遗产类型"},{"t":"人类非遗代表作中国项目","n":"中国入选项目汇总"},{"t":"屠苏","n":"春节节令饮品"},{"t":"二十四节气","n":"2016年入选"}],"more":"列入名称：春节：中国人庆祝传统新年的社会实践。\n列入后中国人类非遗项目共44项。","exam":[]},{"id":"a07-011","t":"国家级非物质文化遗产代表性项目名录","cid":"07a","p":3,"kind":"制度","alias":["国家级非物质文化遗产名录","国家级非遗名录"],"one":"我国建立的最高级别非遗项目保护名录，2006年由国务院首次公布。","ans":"该名录是我国**最高级别的非遗项目保护名录**。**2006年由国务院批准公布第一批（共518项）**，至2026年逢**公布20周年**。名录涵盖民间文学、传统技艺等**十大门类**，是构建国家、省、市、县四级非遗保护体系的基石。","pts":["我国最高级别非遗项目名录","2006年公布首批518项，2026年20周年","涵盖十大门类，奠定四级非遗保护体系"],"mem":"记年份与数字：2006年首批公布518项，2026年恰逢公布20周年。","mix":"认定对象是具体“文化表现形式和项目”，而非“个人”；个人由代表性传承人名录认定。","mcq":[{"q":"国务院批准公布第一批国家级非物质文化遗产名录（共518项）的年份是","o":["2001年","2004年","2011年","2006年"],"a":3,"w":"2006年国务院公布第一批国家级非遗名录，2026年逢首批公布20周年。"}],"rel":[{"t":"代表性传承人","n":"非遗项目核心传承主体"},{"t":"文化和自然遗产日","n":"非遗宣传保护节日"},{"t":"人类非遗代表作中国项目","n":"国际级非遗项目"}],"exam":[]},{"id":"a07-012","t":"文化和自然遗产日","cid":"07a","p":3,"kind":"常识","alias":["文化遗产日"],"one":"每年6月第二个星期六，旨在提高全民文化与自然遗产保护意识的国家主题日。","ans":"文化和自然遗产日是我国设立的**文化与自然遗产保护宣传日**，定于**每年6月第二个星期六**。国务院于2006年设立“文化遗产日”，**2017年起调整为“文化和自然遗产日”**。该节日通过文博开放与非遗展演，广泛提升全民**遗产保护意识**。","pts":["时间为每年6月第二个星期六","2006年设立文化遗产日，2017年调整为现名","宣传普及文物与非遗保护理念"],"mem":"顺口溜：“六月第二个星期六，文化自然共牵手”（2006首设，2017增自然）。","mix":"设立初期（2006年）名为“文化遗产日”，2017年起正式调整为“文化和自然遗产日”。","mcq":[{"q":"我国“文化和自然遗产日”定于","o":["每年5月第三个星期日","每年6月第二个星期六","每年6月第三个星期日","每年9月第三个星期六"],"a":1,"w":"我国自2006年设立该节日，2017年调整为“文化和自然遗产日”，时间为每年6月第二个星期六。"}],"rel":[{"t":"《保护世界文化和自然遗产公约》","n":"世界遗产保护纲领文件"},{"t":"国家级非物质文化遗产代表性项目名录","n":"国内非遗保护名录"}],"exam":[]},{"id":"a07-013","t":"仰韶文化","cid":"07b","p":2,"kind":"概念","alias":["仰韶","仰韶村遗址"],"one":"黄河中游彩陶文化，1921年安特生在河南渑池仰韶村发掘，是中国现代考古学开端。","ans":"仰韶文化是**黄河中游地区的新石器时代文化**，距今约7000至5000年，因**1921年在河南渑池仰韶村发现**而得名，发掘者是**瑞典人安特生**，被视为**中国现代考古学的开端**。其典型特征是**彩陶**，有人面鱼纹等纹饰；陕西西安的半坡、临潼的姜寨是典型聚落，居民以种植粟为主，已过定居生活。它与稍晚的**龙山文化**（黑陶）先后构成黄河流域史前序列。","pts":["1921年渑池仰韶村，安特生发掘","彩陶，黄河中游","中国现代考古学的开端"],"mem":"先彩后黑：仰韶（1921）彩陶，龙山（1928）黑陶。画面：仰头望韶乐，满眼彩绘的陶罐。","mix":"红山文化以玉龙著称（辽西），良渚以玉琮著称（长江下游），龙山以黑陶著称；河姆渡在浙江，以稻作著称。","mcq":[{"q":"仰韶文化最具代表性的遗物是","o":["黑陶","青铜礼器","玉琮","彩陶"],"a":3,"w":"仰韶文化以彩陶著称，龙山文化以黑陶著称。"}],"rel":[{"t":"龙山文化","n":"成对的黄河史前文化"},{"t":"考古学文化","n":"概念"},{"t":"河姆渡遗址","n":"长江流域对照"},{"t":"哈拉帕文化","n":"1921年同年发现"}],"exam":[]},{"id":"a07-014","t":"龙山文化","cid":"07b","p":2,"kind":"概念","alias":["龙山","城子崖遗址"],"one":"黄河中下游黑陶文化，1928年发现于山东章丘城子崖。","ans":"龙山文化是**新石器时代晚期黄河中下游的文化**，距今约4600至4000年，因**1928年发现于山东章丘龙山镇城子崖**而得名，首先由吴金鼎发现，后由李济、梁思永主持发掘。其典型特征是**黑陶**，尤以薄如蛋壳的**蛋壳黑陶杯**著称，制陶使用快轮。龙山时期已出现城址和铜器，社会分化明显，被看作文明起源的前夜，与仰韶文化的**彩陶**形成对照。","pts":["1928年山东章丘城子崖","黑陶，蛋壳陶杯","继仰韶之后，文明起源前夜"],"mem":"“彩仰头，黑龙山”：仰韶彩陶，龙山黑陶。年份用“1921、1928”前后相差七年。","mix":"同在山东的大汶口文化年代更早（早于龙山），以红陶、彩陶为主；良渚在长江下游，以玉器著称。","mcq":[{"q":"山东章丘城子崖遗址所代表的史前文化是","o":["仰韶文化","大汶口文化","良渚文化","龙山文化"],"a":3,"w":"城子崖是龙山文化的发现地，1928年发现。"}],"rel":[{"t":"仰韶文化","n":"成对的史前文化"},{"t":"考古学文化","n":"概念"},{"t":"良渚古城遗址","n":"同期长江下游对照"},{"t":"夏文化","n":"龙山之后的夏代"}],"exam":[]},{"id":"a07-015","t":"河姆渡遗址","cid":"07b","p":2,"kind":"地理","alias":["河姆渡","河姆渡文化"],"one":"浙江余姚，距今约7000年，人工栽培水稻与干栏式建筑。","ans":"河姆渡遗址位于**浙江省余姚市**，1973年发现，距今约7000至5000年，是**长江下游新石器时代**的代表。遗址出土大量**稻谷、稻壳和骨耜**，证明当地已**人工栽培水稻**；居民住**干栏式建筑**，木构件已使用榫卯，还有黑陶和刻有双鸟朝阳纹的象牙器。河姆渡与黄河流域的仰韶文化南北对照，说明**中华文明起源是多元的**。","pts":["浙江余姚，距今约7000年","人工栽培水稻，骨耜","干栏式建筑，榫卯"],"mem":"南北对照：北有仰韶（粟、彩陶），南有河姆渡（稻、干栏）。画面：高脚木屋里堆着稻谷。","mix":"良渚在杭州余杭，距今约5300至4300年，以玉器和水利系统闻名，比河姆渡晚；仰韶种粟，河姆渡种稻。","mcq":[{"q":"浙江余姚河姆渡遗址最重要的发现之一是","o":["甲骨文","人工栽培水稻","青铜礼器","兵马俑"],"a":1,"w":"河姆渡出土大量稻谷遗存，证明长江下游已栽培水稻。"}],"rel":[{"t":"仰韶文化","n":"北方对照"},{"t":"良渚古城遗址","n":"同在浙江的稍晚文明"},{"t":"考古学文化","n":"概念"},{"t":"中华文明探源工程","n":"多元起源的研究"}],"exam":[]},{"id":"a07-016","t":"红山文化","cid":"07b","p":3,"kind":"概念","alias":["红山文化遗址"],"one":"中国东北地区新石器时代晚期考古学文化，以玉猪龙、牛河梁坛庙冢闻名。","ans":"红山文化是分布在**辽宁西部、内蒙古东部**的新石器时代晚期文化，距今约6500至5000年。核心遗存为**牛河梁遗址**，出土**玉猪龙**、**牛河梁女神庙**、大型祭坛与积石冢，呈现出早期礼制雏形，是实证中华文明起源的重要源头。","pts":["辽西与内蒙古东部，距今6500–5000年","以牛河梁女神庙、积石冢祭坛为核心","出土玉猪龙，实证中华文明多元一体"],"mem":"红山文化抓三件宝：赤峰红山、牛河梁女神庙、玉猪龙（北方辽西）。","mix":"红山文化位于北方西辽河流域，代表玉器为玉猪龙；良渚文化位于长江下游环太湖流域，代表玉器为玉琮、玉璧。","mcq":[{"q":"发现女神庙、祭坛、积石冢并出土著名玉器“玉猪龙”的北方新石器时代考古学文化是","o":["红山文化","仰韶文化","大汶口文化","马家窑文化"],"a":0,"w":"红山文化分布于辽宁、内蒙古一带，以牛河梁遗址的女神庙、祭坛、积石冢和玉猪龙最为著名。"}],"rel":[{"t":"良渚古城遗址","n":"南北史前玉器文明对照"},{"t":"仰韶文化","n":"黄河流域同期新石器文化"}],"exam":[]},{"id":"a07-017","t":"半坡遗址","cid":"07b","p":3,"kind":"地理","alias":["半坡聚落","西安半坡遗址"],"one":"陕西西安典型的仰韶文化母系氏族村落遗址，建有中国第一座史前遗址博物馆。","ans":"半坡遗址位于**陕西省西安市浐河东岸**，是距今约6000年的新石器时代仰韶文化聚落遗存，为**母系氏族村落**的典型代表。遗址包含居住区、制陶作坊与墓葬区，出土半地穴式房屋与**人面鱼纹彩陶盆**。**1958年在此建成中国第一座史前遗址博物馆**。","pts":["陕西西安，距今约6000年仰韶文化聚落","母系氏族村落，出土人面鱼纹彩陶盆","1958年建成中国第一座史前遗址博物馆"],"mem":"半坡四要点：西安浐河、母系村落、人面鱼纹盆、1958年首座史前馆。","mix":"半坡是黄河流域仰韶文化代表（彩陶、粟作物、半地穴式房屋）；河姆渡是长江流域代表（黑陶、水稻、干栏式建筑）。","mcq":[{"q":"出土著名的人面鱼纹彩陶盆、并在1958年建成中国第一座史前遗址博物馆的是","o":["浙江河姆渡遗址","河南二里头遗址","陕西西安半坡遗址","山东龙山城子崖遗址"],"a":2,"w":"半坡遗址位于陕西西安，出土人面鱼纹彩陶盆，1958年建成西安半坡博物馆。"}],"rel":[{"t":"仰韶文化","n":"所属新石器时代考古学文化"},{"t":"河姆渡遗址","n":"黄河与长江流域史前聚落对照"}],"exam":[]},{"id":"a07-018","t":"元谋人、北京人、山顶洞人","cid":"07b","p":3,"kind":"合称","alias":["中国远古人类代表"],"one":"中国旧石器时代早中晚期演进的代表性古人类，实证东亚人类起源链条。","ans":"元谋人、北京人、山顶洞人是我国**旧石器时代演进序列**的三大代表。**元谋人**距今约170万年，是我国已知最早直立人之一；**北京人**距今约70万至20万年，会使用天然火；**山顶洞人**距今约3万年，已掌握**人工取火与磨制骨针**。","pts":["旧石器时代早中晚期演进的代表古人类","元谋人约170万年前，已知最早直立人之一","北京人会用天然火，山顶洞人会人工取火与缝纫"],"members":[["元谋人","云南元谋，距今约170万年，中国境内已知最早直立人之一，有早期用火痕迹"],["北京人","北京周口店龙骨山，距今约70万至20万年，直立人，会使用和保存天然火"],["山顶洞人","北京周口店龙骨山顶部，距今约3万年，晚期智人，掌握人工取火和骨针缝纫"]],"mem":"演化三步走：元谋人最早（170万年）→北京人用天然火→山顶洞人缝衣（人工取火、骨针）。","mix":"元谋人、北京人属于直立人；山顶洞人已演化为晚期智人（现代人类型）。","mcq":[{"q":"在中国远古人类遗址中，已经掌握人工取火并使用骨针缝制衣服的是","o":["元谋人","蓝田人","北京人","山顶洞人"],"a":3,"w":"山顶洞人距今约3万年，属晚期智人，已掌握人工取火技术并能磨制骨针缝纫。"}],"rel":[{"t":"中国首批世界遗产（1987年6项）","n":"周口店北京人遗址首批入选世遗"},{"t":"考古学文化","n":"旧石器时代考古人类遗存"}],"exam":[]},{"id":"a07-019","t":"马王堆汉墓","cid":"07b","p":2,"kind":"地理","alias":["马王堆","轪侯墓"],"one":"湖南长沙西汉轪侯利苍家族墓，出土素纱襌衣、帛书、T形帛画。","ans":"马王堆汉墓位于**湖南省长沙市**，是**西汉长沙国丞相、轪侯利苍及其家属的墓葬**，1972至1974年发掘。一号墓出土**辛追（利苍之妻）**的保存完好的遗体，同墓有重量不到50克的**素纱襌衣**和**T形帛画**；三号墓出土大量**帛书**，包括《老子》甲乙本、《周易》和医书《五十二病方》。它为研究西汉的丧葬、纺织、医学和思想提供了珍贵实物。","pts":["长沙，西汉轪侯利苍家族墓","素纱襌衣、T形帛画、辛追","帛书：老子、周易、医书"],"mem":"画面：一件不到50克的纱衣、一幅T形画、一具不腐的女尸（辛追）。位置记“长沙马王堆，河北满城金缕玉衣”。","mix":"金缕玉衣出自河北满城汉墓（刘胜）；马王堆在湖南，墓主是利苍家族，不是诸侯王。","mcq":[{"q":"马王堆汉墓位于今天的","o":["湖北荆州","湖南长沙","河北满城","陕西咸阳"],"a":1,"w":"马王堆汉墓在湖南长沙，西汉轪侯利苍家族墓。"}],"rel":[{"t":"金缕玉衣","n":"汉代葬具对照"},{"t":"《黄帝内经》","n":"同属医学文献背景"},{"t":"秦始皇陵及兵马俑坑","n":"帝王陵墓对照"},{"t":"考古学文化","n":"概念"}],"exam":[]},{"id":"a07-021","t":"何尊","cid":"07b","p":2,"kind":"常识","alias":["何尊铭文","宅兹中国"],"one":"西周早期青铜器，铭文“宅兹中国”是“中国”一词最早的文字记录。","ans":"何尊是**西周早期的青铜酒器**，**1963年出土于陕西宝鸡贾村**，内底铸有**122字铭文**。铭文记载**周成王营建成周（洛邑）**，并追述武王克商后“余其宅兹中国”的遗愿，其中“**宅兹中国**”即居于天下之中，是**“中国”一词最早的文字记录**。何尊现藏宝鸡青铜器博物院，为研究西周史、洛邑营建和“中国”观念形成的重要材料。","pts":["西周早期，1963年宝鸡出土","铭文122字，成王营建成周","“宅兹中国”：最早的“中国”"],"mem":"画面：一只酒器的底部有122个字，其中四个字是“宅兹中国”。联想：“何处是中国？何尊答：宅兹中国。”","mix":"铭文中的“中国”指天下之中的洛邑一带，与今天的国名含义不同；“中国”一词的文字记录与后母戊鼎（商）、毛公鼎（西周晚期）无关。","mcq":[{"q":"“中国”一词最早见于下列哪件文物的铭文","o":["毛公鼎","大盂鼎","后母戊鼎","何尊"],"a":3,"w":"何尊铭文“宅兹中国”是“中国”最早的文字记录。"}],"rel":[{"t":"中华文明探源工程","n":"文明与国家观念"},{"t":"后母戊鼎","n":"商代青铜器对照"},{"t":"周公","n":"营建洛邑的背景"},{"t":"殷墟","n":"商周更替的背景"}],"exam":[]},{"id":"a07-022","t":"毛公鼎","cid":"07b","p":3,"kind":"常识","alias":["毛公鼎铭文"],"one":"西周晚期青铜重器，现存铭文最长的青铜器，现藏台北故宫博物院。","ans":"毛公鼎是**西周宣王时期的青铜礼器**，清代出土于陕西岐山，现藏于**台北故宫博物院**。内壁铸有铭文32行、**497字**，是**迄今所见铭文最长**的商周青铜器。铭文记录周宣王告诫毛公及册命赏赐，金文书法精严，具有极高史料与书法价值。","pts":["西周晚期宣王时期，陕西岐山出土","现存铭文最长（497字）的青铜重器","现藏台北故宫博物院，金文书法典范"],"mem":"毛公鼎记“两最一藏”：字数最多（近500字长篇策命）、藏台北故宫。","mix":"毛公鼎是铭文最长（字数最多）的青铜器；后母戊鼎是现存最重最大的青铜鼎；四羊方尊是现存最大商代方尊。","mcq":[{"q":"现藏于台北故宫博物院、内壁铸有497字长篇铭文且为迄今出土铭文最长的西周青铜器是","o":["毛公鼎","大盂鼎","散氏盘","虢季子白盘"],"a":0,"w":"毛公鼎内壁铸有497字长篇铭文，是现存铭文最长的青铜器。"}],"rel":[{"t":"金文（钟鼎文）","n":"毛公鼎铭文为金文书法典范"},{"t":"后母戊鼎","n":"商周青铜重器对照"},{"t":"四羊方尊","n":"商周青铜重器对照"}],"exam":[]},{"id":"a07-023","t":"四羊方尊","cid":"07b","p":3,"kind":"常识","alias":["商四羊方尊"],"one":"商代晚期大型青铜礼器，现存最大的商代青铜方尊，现藏中国国家博物馆。","ans":"四羊方尊是**商代晚期青铜礼器**，1938年出土于**湖南宁乡**，现藏于**中国国家博物馆**。高58.3厘米，是**现存最大的商代青铜方尊**。器身四角各铸一卷角绵羊，将圆雕与浮雕融为一体，展现了商代南方青铜铸造的高超技艺。","pts":["商代晚期青铜礼器，湖南宁乡出土","现存最大的商代青铜方尊","四羊共体造型，藏于中国国家博物馆"],"mem":"四羊方尊记五字：湖南宁乡出，国博藏方尊（现存最大商代方尊）。","mix":"出土于湖南宁乡，属于南方青铜文化代表，并非河南安阳殷墟出土；现藏北京中国国家博物馆。","mcq":[{"q":"1938年出土于湖南宁乡、被誉为现存最大商代青铜方尊的国宝级文物是","o":["后母戊鼎","四羊方尊","利簋","毛公鼎"],"a":1,"w":"四羊方尊出土于湖南宁乡，是现存最大的商代青铜方尊，现藏中国国家博物馆。"}],"rel":[{"t":"后母戊鼎","n":"商代青铜重器代表"},{"t":"毛公鼎","n":"商周青铜重器对照"},{"t":"何尊","n":"西周青铜器代表"}],"exam":[]},{"id":"a07-024","t":"越王勾践剑","cid":"07b","p":3,"kind":"常识","alias":["越王勾践自作用剑"],"one":"春秋晚期越王勾践佩剑，1965年出土于湖北江陵，誉为“天下第一剑”。","ans":"越王勾践剑是**春秋晚期越国青铜兵器**，1965年出土于**湖北江陵望山楚墓**，现藏于**湖北省博物馆**。剑身铸有“越王鸠浅自作用剑”鸟篆铭文。采用复合金属技术与防锈工艺，历经两千四百余年出土时**锋利无锈**，被誉为**“天下第一剑”**。","pts":["春秋晚期越国兵器，1965年湖北江陵出土","鸟篆铭文“越王勾践自作用剑”","出土锋利无锈，藏湖北省博物馆"],"mem":"勾践剑记考点：虽是越王佩剑，却在湖北江陵楚墓出土，千年不锈天下第一。","mix":"虽是越国国君勾践之剑，但出土地点是湖北荆州（江陵）楚墓，而非浙江；现藏湖北省博物馆。","mcq":[{"q":"1965年在湖北江陵望山楚墓出土、历经两千多年出土仍锋利无锈的春秋青铜兵器是","o":["吴王光剑","吴王夫差矛","越王勾践剑","秦王剑"],"a":2,"w":"越王勾践剑于1965年在湖北江陵出土，现藏湖北省博物馆，锋利完好。"}],"rel":[{"t":"毛公鼎","n":"先秦青铜重器对照"},{"t":"四羊方尊","n":"先秦青铜重器对照"}],"exam":[]},{"id":"a07-025","t":"金缕玉衣","cid":"07b","p":3,"kind":"常识","alias":["玉衣","玉匣"],"one":"汉代皇帝与高级贵族的顶级殓服，以玉片与金丝缀连而成，体现死后不朽观念。","ans":"金缕玉衣是**汉代皇帝与高级贵族的顶级殓服**，由玉片穿缀金丝编织而成。最著名实物为**河北满城汉墓中山靖王刘胜玉衣**。东汉严分**金缕、银缕、铜缕等级**，至三国曹魏时期正式下令废除。玉衣反映了汉代追求尸骨不朽的生死观念。","pts":["汉代帝王高级贵族专用丧葬殓服","河北满城中山靖王刘胜墓出土最著名","按金银铜缕区分等级，曹魏时废除"],"mem":"玉衣等级分金银：皇帝诸侯王穿金缕，列侯银缕贵人铜；满城刘胜最知名。","mix":"金缕玉衣是最高规格，汉代依身份有金缕、银缕、铜缕、丝缕之分；曹魏魏文帝曹丕下诏废除玉衣。","mcq":[{"q":"汉代帝王贵族死后入葬所穿的最高等级玉衣是金缕玉衣，其最具代表性的完整实物出土于","o":["湖南长沙马王堆汉墓","广东广州南越王墓","山东巨野汉墓","河北满城中山靖王刘胜墓"],"a":3,"w":"1968年河北满城中山靖王刘胜及其妻窦绾墓出土了两套完整的金缕玉衣。"}],"rel":[{"t":"秦始皇陵及兵马俑坑","n":"汉承秦制之丧葬礼制"},{"t":"考古学文化","n":"汉代考古实物遗存"}],"exam":[]},{"id":"a07-026","t":"中华文明探源工程","cid":"07b","p":2,"kind":"事件","alias":["探源工程"],"one":"2002年启动的多学科国家工程，前接夏商周断代工程，实证五千多年文明史。","ans":"中华文明探源工程是**2002年启动的多学科综合性国家重大科研工程**，继**夏商周断代工程（1996至2000年）**之后，把研究推向文明起源与早期发展。它联合考古、历史、天文、地质、生物等学科，以**良渚、陶寺、石峁、二里头**等遗址为重点，成果提出：**距今5800年前后**出现文明起源迹象，**距今5300年以来进入文明阶段**，实证了**五千多年文明史**。","pts":["2002年启动，多学科国家工程","重点遗址：良渚、陶寺、石峁、二里头","实证五千多年文明史"],"mem":"两个工程成对记：断代工程（1996至2000）定“何时”，探源工程（2002起）究“从何来”。数字“5800前后萌芽，5300进入文明”。","mix":"夏商周断代工程着眼年代学，探源工程着眼文明起源；“考古中国”是后续的考古项目，不是同一工程。","mcq":[{"q":"为实证五千多年文明史，于2002年启动的国家工程是","o":["夏商周断代工程","中华文明探源工程","中华学术外译项目","大中华文库"],"a":1,"w":"探源工程2002年启动，夏商周断代工程为1996至2000年。"}],"rel":[{"t":"良渚古城遗址","n":"实证五千年文明的核心"},{"t":"二里头遗址","n":"重点研究遗址"},{"t":"夏文化","n":"断代工程的成果"},{"t":"“考古中国”与全国十大考古新发现","n":"后续考古项目"}],"exam":[]},{"id":"a07-027","t":"“考古中国”与全国十大考古新发现","cid":"07b","p":3,"kind":"时事","alias":["考古中国","全国十大考古新发现"],"one":"国家重大考古研究项目与由国家文物局指导评选的年度十大考古成果。","ans":"“考古中国”是**国家文物局推进的重大考古研究工程**，聚焦中华文明探源等重大课题。**全国十大考古新发现**创办于1990年，由中国文物报社与中国考古学会主办，每年评选上一年度十项重大田野成果，被誉为**“中国考古界的奥斯卡”**。","pts":["国家文物局主导的“考古中国”重大项目","创办于1990年的全国十大考古新发现评选","展现中华文明起源与发展的最新实证"],"mem":"记分工：“考古中国”是官方重大科研工程，“十大发现”是年度奥斯卡学术评奖。","mix":"“考古中国”是国家文物局推进的重大课题研究机制；“全国十大考古新发现”是由中国文物报社和中国考古学会组织的年度评奖。","mcq":[{"q":"创办于1990年、每年由中国文物报社和中国考古学会主办并被誉为“中国考古界奥斯卡”的评选是","o":["全国十大考古新发现","中国百年百大考古发现","田野考古奖评选","中国考古学会年会金奖"],"a":0,"w":"全国十大考古新发现创办于1990年，每年评选上一年度全国十项重大田野考古发现。"}],"rel":[{"t":"二里头遗址","n":"夏商周断代与早期国家考古"},{"t":"八里桥遗址","n":"“考古中国”夏文化重大发现"},{"t":"良渚古城遗址","n":"中华文明探源工程实证"}],"more":"2026年11月18日“考古中国”重大项目进展会：四川遂宁桃花河遗址（中更新世旷野营地）、杭州良渚反山遗址（良渚文化最高等级贵族墓地）、九江荞麦岭遗址群岭头上遗址、湖北云梦老虎墩墓地（出土秦简最集中的墓地）","exam":[]},{"id":"a07-028","t":"大足石刻","cid":"07b","p":3,"kind":"地理","alias":["大足石窟"],"one":"重庆大足境内的石窟造像群，晚期石窟代表，儒释道三教合一，世界文化遗产。","ans":"大足石刻位于**重庆市大足区**，始凿于初唐，盛于两宋。它是中国石窟艺术晚期的巅峰代表，以鲜明的世俗化与**儒释道“三教合一”造像**为特色。**1999年被列入《世界遗产名录》**。代表作有千手观音像与卧佛，具有极高艺术价值。","pts":["位于重庆大足，始凿于唐盛于两宋","晚期石窟代表，突出儒释道三教融合","1999年列入世界文化遗产"],"mem":"大足石刻记四点：重庆大足、宋代为主、三教合一、1999年申遗。","mix":"大足石刻位于南方重庆，开凿时间盛于两宋，晚于北方四大石窟（敦煌、云冈、龙门、麦积山），突出“三教合一”与民间世俗化。","mcq":[{"q":"1999年列入《世界遗产名录》，以世俗化和“儒释道三教合一”造像著称的中国南方晚期石窟是","o":["麦积山石窟","大足石刻","龙门石窟","云冈石窟"],"a":1,"w":"大足石刻位于重庆大足，以宋代造像为主，充分体现了儒释道三教融合的世俗化特征。"}],"rel":[{"t":"中国四大石窟","n":"石窟造像艺术对照"},{"t":"世界文化遗产","n":"1999年列入世界遗产"}],"exam":[]},{"id":"a07-029","t":"七大古都","cid":"07c","p":2,"kind":"合称","alias":["四大古都","八大古都"],"one":"西安、洛阳、南京、北京、开封、杭州、安阳；前四座常称四大古都，加郑州为八大。","ans":"七大古都指**西安、洛阳、南京、北京、开封、杭州、安阳**七座历史上长期作为王朝都城的城市。其中**西安、洛阳、南京、北京**常称**四大古都**，后来学界又加入开封、杭州、安阳，**加上郑州则称八大古都**。西安为周秦汉唐等朝都城，洛阳是东周、东汉、隋唐旧都，南京是六朝古都，北京是辽金元明清都城，安阳是商代殷墟所在。七大古都反映中国都城的历史变迁。","pts":["西安、洛阳、南京、北京为四大","加开封、杭州、安阳成七大","加郑州为八大"],"members":[["西安","周秦汉隋唐等朝，古称长安、镐京"],["洛阳","东周、东汉、魏晋、隋唐"],["南京","六朝、明初、民国"],["北京","辽金元明清"],["开封","战国魏、北宋等"],["杭州","吴越国、南宋"],["安阳","商（殷墟）、曹魏邺城"]],"mem":"先记四大“西洛南北”（西安、洛阳、南京、北京），再记“开杭安”（开封、杭州、安阳）谐音“开航安”，最后加郑州成八大。","mix":"四大古都、七大古都、八大古都是三种说法；安阳靠殷墟，杭州靠南宋和吴越，不要与“四大”混。","mcq":[{"q":"下列城市中，不属于七大古都的是","o":["开封","杭州","郑州","安阳"],"a":2,"w":"郑州是八大古都之一，七大古都为西安、洛阳、南京、北京、开封、杭州、安阳。"}],"rel":[{"t":"殷墟","n":"安阳的代表遗址"},{"t":"商朝与盘庚迁殷","n":"安阳与商都"},{"t":"北京中轴线","n":"北京的世界遗产"},{"t":"丝绸之路：长安-天山廊道路网","n":"长安、洛阳为起点"}],"exam":[]},{"id":"a07-030","t":"赵州桥","cid":"07c","p":2,"kind":"常识","alias":["安济桥"],"one":"隋代李春设计的河北赵县石拱桥，现存最早的敞肩石拱桥。","ans":"赵州桥又名安济桥，位于**河北省赵县**，由**隋代工匠李春**设计建造，约建于隋开皇十五年至大业元年（公元595至605年）。桥为**单孔敞肩石拱桥**，全长约64米，主拱跨度约37米，大拱两肩各设两个小拱，既减轻桥重，又利于泄洪，是**世界现存最早、保存最完整的敞肩石拱桥**。它历经一千四百多年仍在使用，是中国古代桥梁技术的代表。","pts":["隋代李春设计，河北赵县","单孔敞肩石拱桥，一大四小","现存最早的敞肩石拱桥"],"mem":"画面：一个大拱，两肩各开两个小眼，“一大四小”就是敞肩。年代记“隋”，设计者记“李春”（都江堰的李冰是战国）。","mix":"卢沟桥是金代石拱联拱桥，洛阳桥在福建泉州（宋），广济桥在广东潮州；李春（赵州桥）与李冰（都江堰）姓名相近易混。","mcq":[{"q":"赵州桥的设计者是","o":["李春","鲁班","宇文恺","李冰"],"a":0,"w":"赵州桥为隋代李春设计，李冰修都江堰。"}],"rel":[{"t":"中国四大古桥","n":"赵州桥属其一"},{"t":"应县木塔","n":"同属古代建筑杰作"},{"t":"隋朝","n":"所属朝代"},{"t":"隋炀帝与大运河","n":"隋代工程对照"}],"exam":[]},{"id":"a07-033","t":"中国古代三大殿","cid":"07c","p":3,"kind":"合称","alias":["三大殿","中国三大殿"],"one":"中国古代最高等级木构宫殿建筑合称，即北京太和殿、曲阜大成殿与泰安天贶殿。","ans":"中国古代三大殿是指**古代形制等级最高的三座木结构殿堂**，即**北京故宫太和殿、山东曲阜孔庙大成殿与山东泰安岱庙天贶殿**。三大殿均采用最高形制重檐庑殿顶。分别代表至高无上的封建**皇权**、儒家**文统**与祭祀泰山神的**神道礼制**。","pts":["北京故宫太和殿、曲阜孔庙大成殿、泰安岱庙天贶殿","中国古代最高规格的重檐庑殿顶建筑","分别象征皇权礼制、儒家文统与神道祭祀"],"members":[["北京故宫太和殿","紫禁城三大殿之首，俗称金銮殿，明清帝王举行登基大婚等国家大典场所"],["曲阜孔庙大成殿","曲阜孔庙正殿，祭孔场所，前檐十根高浮雕滚龙石柱闻名于世"],["泰安岱庙天贶殿","泰山岱庙主体建筑，宋真宗大中祥符年间建，供奉东岳泰山神（东岳大帝）"]],"mem":"记忆口诀：“故宫太和金銮殿，孔庙大成尊夫子，岱庙天贶敬泰山”。","mix":"天贶殿位于泰安城内的岱庙，非泰山极顶的碧霞祠；大成殿在曲阜孔庙；三大殿均享有重檐庑殿顶最高建制。","mcq":[{"q":"与北京故宫太和殿、曲阜孔庙大成殿并称为“中国古代三大殿”的是","o":["沈阳故宫大政殿","承德普陀宗乘之庙大红台","泰安岱庙天贶殿","武当山紫霄宫大殿"],"a":2,"w":"中国古代三大殿指北京故宫太和殿、曲阜孔庙大成殿与泰安岱庙天贶殿。"}],"rel":[{"t":"中国首批世界遗产（1987年6项）","n":"故宫与泰山首批列入世遗"},{"t":"五岳","n":"天贶殿坐落于东岳泰山岱庙"}],"exam":[]},{"id":"a07-034","t":"四大名亭","cid":"07c","p":3,"kind":"合称","alias":["中国四大名亭"],"one":"中国四座著名历史文化名亭合称：醉翁亭、陶然亭、爱晚亭与湖心亭。","ans":"四大名亭是指**中国古代四座著名历史文化名亭**，即**安徽滁州醉翁亭、北京陶然亭、湖南长沙爱晚亭与浙江杭州湖心亭**。四亭均因欧阳修《醉翁亭记》、杜牧诗句等**名家诗文**而饮誉天下，体现了文人意趣与自然山水的精妙融合。","pts":["醉翁亭、陶然亭、爱晚亭、湖心亭","均与欧阳修、白居易、杜牧、张岱等名家诗文相关","体现山水建筑与文人审美情趣的融合"],"members":[["醉翁亭","安徽滁州琅琊山，宋代智仙和尚建，欧阳修作《醉翁亭记》"],["陶然亭","北京宣武门外先农坛西，清代江藻建，取白居易诗“共君一醉一陶然”"],["爱晚亭","湖南长沙岳麓山清风峡，清代罗典建，取杜牧诗“停车坐爱枫林晚”"],["湖心亭","浙江杭州西湖外湖中央，明嘉靖年间建，明末张岱作名篇《湖心亭看雪》"]],"mem":"名句串记四亭：醉翁琅琊山，陶然白居易，爱晚枫林叶，湖心西湖雪。","mix":"爱晚亭原名红叶亭，取杜牧诗改名；陶然亭取白居易诗名；王羲之兰亭修禊之“兰亭”不在通行四大名亭之列。","mcq":[{"q":"坐落于湖南长沙岳麓山清风峡、名字取自杜牧“停车坐爱枫林晚”名句的中国名亭是","o":["爱晚亭","醉翁亭","陶然亭","湖心亭"],"a":0,"w":"爱晚亭位于湖南长沙岳麓山，清代罗典始建，原名红叶亭，后取杜牧诗句改名爱晚亭。"}],"rel":[{"t":"中国四大名楼","n":"传统景观名胜合称"},{"t":"中国四大名园","n":"传统园林名胜合称"}],"exam":[]},{"id":"a07-035","t":"江南三大名楼","cid":"07c","p":3,"kind":"合称","alias":["江南三大楼"],"one":"长江流域三座著名古建筑合称，即黄鹤楼、岳阳楼与滕王阁。","ans":"江南三大名楼是指**坐落于长江流域的三座历史文化名楼**，即**湖北武汉黄鹤楼、湖南岳阳岳阳楼与江西南昌滕王阁**。三楼均因崔颢《黄鹤楼》、范仲淹《岳阳楼记》与王勃《滕王阁序》等**千古传诵名作**而闻名，合称中不含北方的鹳雀楼。","pts":["黄鹤楼、岳阳楼、滕王阁","均地处长江流域，各配千古传诵名篇","四大名楼中唯独不含北方的鹳雀楼"],"members":[["黄鹤楼","湖北武汉武昌蛇山，唐代崔颢作《黄鹤楼》、李白作《黄鹤楼送孟浩然之广陵》"],["岳阳楼","湖南岳阳洞庭湖畔巴陵古城，北宋范仲淹作《岳阳楼记》“先天下之忧而忧”"],["滕王阁","江西南昌赣江之畔，唐代王勃作《滕王阁序》“落霞与孤鹜齐飞”"]],"mem":"记三楼三水：黄鹤楼临长江，岳阳楼瞰洞庭，滕王阁枕赣江；剔除黄河鹳雀楼。","mix":"“中国四大名楼”包含山西永济鹳雀楼，而“江南三大名楼”仅指江南长江流域的三座名楼，不含鹳雀楼。","mcq":[{"q":"下列名楼中，属于“中国四大名楼”但不属于“江南三大名楼”的是","o":["岳阳楼","鹳雀楼","黄鹤楼","滕王阁"],"a":1,"w":"鹳雀楼位于北方山西运城永济，属于四大名楼之一，但不属于江南三大名楼。"}],"rel":[{"t":"中国四大名楼","n":"北方鹳雀楼与江南三楼并称"},{"t":"范仲淹《岳阳楼记》与“易混作者”","n":"名楼文学作品"}],"exam":[]},{"id":"a07-036","t":"三山五岳之“三山”","cid":"07c","p":3,"kind":"合称","alias":["三山"],"one":"中国名山合称，地理上通常指黄山、庐山、雁荡山；神话中指蓬莱、方丈、瀛洲。","ans":"三山五岳之“三山”是指**中国著名风景名山的并称**。在现代地理景观上指**安徽黄山、江西庐山、浙江雁荡山**三座风景名胜，分别以奇松、飞瀑与奇峰闻名。在古代神话中，“海上三神山”则指**蓬莱、方丈、瀛洲**，相传为仙人所居之地。","pts":["现代地理名山指黄山、庐山、雁荡山","古代神话三神山指蓬莱、方丈、瀛洲","与五岳并称，构成中国名山文化象征"],"members":[["黄山","安徽黄山，以奇松、怪石、云海、温泉、冬雪“五绝”著称，徐霞客赞“归来不看岳”"],["庐山","江西九江，临长江、倚鄱阳湖，匡庐奇秀，苏轼作《题西林壁》、李白作《望庐山瀑布》"],["雁荡山","浙江温州乐清，开山凿胜始于南北朝，以奇峰、叠嶂、飞瀑闻名，誉为“寰中绝胜”"]],"mem":"景观三山记省份：安徽黄山、江西庐山、浙江雁荡；神话三仙山：蓬莱、方丈、瀛洲。","mix":"五岳（泰山、华山、衡山、恒山、嵩山）是古代官方封禅祭祀的名山；“三山”在古代多指海外仙山，现代文旅通称黄山、庐山、雁荡山。","mcq":[{"q":"现代文旅常识中，“三山五岳”里的“三山”通常指","o":["黄山、庐山、雁荡山","泰山、华山、衡山","武夷山、阿里山、雁荡山","峨眉山、青城山、九华山"],"a":0,"w":"现代常说的“三山”指安徽黄山、江西庐山、浙江雁荡山；五岳为泰山、华山、衡山、恒山、嵩山。"}],"rel":[{"t":"五岳","n":"三山五岳并称"},{"t":"世界文化遗产","n":"黄山与庐山入选世界遗产"}],"exam":[]},{"id":"a07-037","t":"五方神（四时之神）","cid":"07d","p":1,"kind":"合称","alias":["四时之神","五方之神","五帝佐神"],"one":"句芒（东春木）、祝融（南夏火）、蓐收（西秋金）、玄冥（北冬水）、后土（中土）。","ans":"五方神是古代与五行、五方、四季相配的**五位神祇**，说法见于《礼记·月令》等文献：**东方句芒主春属木，南方祝融主夏属火，西方蓐收主秋属金，北方玄冥主冬属水，中央后土属土**，前四位又称四时之神。他们是辅佐五方天帝的神，句芒掌草木萌发，祝融是火神，蓐收司秋收，玄冥司冬藏。五方神把**五行、方位、季节**编成一套对应体系，在祭祀和历法中长期沿用。","pts":["东句芒春木、南祝融夏火","西蓐收秋金、北玄冥冬水","中央后土；见《礼记·月令》"],"members":[["句芒","东方，木，春神"],["祝融","南方，火，夏神"],["蓐收","西方，金，秋神"],["玄冥","北方，水，冬神"],["后土","中央，土"]],"mem":"顺序按“东南西北中”背：句芒、祝融、蓐收、玄冥、后土，对应木、火、金、水、土。字形帮忙：句“芒”带草字头，是春草；“祝融”像火融；“蓐收”谐音“入秋收”；“玄冥”玄是黑，黑属北方冬天。","mix":"2024选择考句芒（春神）；后土有时指大地之神“后土娘娘”，在五方神里居中央；五行相生顺序是木火土金水，方位顺序是木火金水土，两个排法不同。","mcq":[{"q":"古代神话中，掌管春天的神是","o":["祝融","句芒","蓐收","玄冥"],"a":1,"w":"句芒是东方之神，主春，属木。"},{"q":"下列神祇中，对应西方、秋季的是","o":["后土","祝融","玄冥","蓐收"],"a":3,"w":"蓐收主西方、秋季、属金；祝融主南方夏季；玄冥主北方冬季。"}],"rel":[{"t":"句芒","n":"春神"},{"t":"五行","n":"配属体系"},{"t":"四象（四灵）","n":"方位对应体系"},{"t":"二十四节气","n":"季节划分"},{"t":"《山海经》","n":"句芒等神的早期记载"}],"more":"见于《礼记·月令》：春，其神句芒；夏，其神祝融；秋，其神蓐收；冬，其神玄冥；中央，其神后土。","exam":[]},{"id":"a07-038","t":"四象（四灵）","cid":"07d","p":2,"kind":"合称","alias":["四象","四灵","青龙白虎朱雀玄武"],"one":"东方青龙、西方白虎、南方朱雀、北方玄武，各辖七宿。","ans":"四象（四灵）是**中国古代天文和方位文化中的四种神兽**：**东方青龙、西方白虎、南方朱雀、北方玄武**，分别对应春、秋、夏、冬和青、白、红、黑四色。古人把黄道赤道附近的**二十八宿**分成四组，每象各辖**七宿**，如青龙辖角亢氐房心尾箕。四象与五行、四季配合，常见于墓葬壁画、瓦当和军阵，如“左青龙，右白虎，前朱雀，后玄武”。","pts":["青龙东、白虎西、朱雀南、玄武北","每象各辖七宿，共二十八宿","对应春秋夏冬，常见于壁画瓦当"],"members":[["东方青龙","春，青色，角亢氐房心尾箕"],["西方白虎","秋，白色，奎娄胃昴毕觜参"],["南方朱雀","夏，红色，井鬼柳星张翼轸"],["北方玄武","冬，黑色，斗牛女虚危室壁"]],"mem":"口诀“左青龙，右白虎，前朱雀，后玄武”。季节颜色：青春、朱夏、白秋、玄冬。","mix":"《周易》中的“四象”是太阳、少阴、少阳、太阴，是另一个概念；玄武是龟蛇合体，不是龟；四象不含黄龙。","mcq":[{"q":"与北方、冬季相配的神兽是","o":["青龙","白虎","朱雀","玄武"],"a":3,"w":"北方玄武，对应冬季和黑色。"}],"rel":[{"t":"二十八宿","n":"四象分辖"},{"t":"五方神（四时之神）","n":"四季神祇对照"},{"t":"北斗七星","n":"另一星官"},{"t":"五行","n":"方位与颜色相配"}],"exam":[]},{"id":"a07-039","t":"二十八宿","cid":"07d","p":2,"kind":"概念","alias":["廿八宿","28宿"],"one":"黄道赤道附近分成的二十八个星区，四象各辖七宿。","ans":"二十八宿是**古人把黄道、赤道附近的星空划分成的二十八个星区**，用作观测日月五星运行的坐标。它分属**四象**，每象七宿：东方青龙为角亢氐房心尾箕，北方玄武为斗牛女虚危室壁，西方白虎为奎娄胃昴毕觜参，南方朱雀为井鬼柳星张翼轸。二十八宿体系至迟战国已形成，**曾侯乙墓**漆箱盖上有现存最早的完整二十八宿名称，是古代天文历法的基础。","pts":["黄道赤道附近分二十八个星区","四象各辖七宿","曾侯乙墓漆箱盖有最早完整名称"],"mem":"四组七宿按东、北、西、南顺序背：“角亢氐房心尾箕，斗牛女虚危室壁，奎娄胃昴毕觜参，井鬼柳星张翼轸”。","mix":"杜甫“人生不相见，动如参与商”：参宿在西，商指心宿在东，此出彼没；二十八宿不是黄道十二宫，后者是西方体系。","mcq":[{"q":"下列星宿中，属于西方白虎七宿的是","o":["角宿","斗宿","参宿","井宿"],"a":2,"w":"参宿属西方白虎；角属东，斗属北，井属南。"}],"rel":[{"t":"四象（四灵）","n":"二十八宿的分组"},{"t":"北斗七星","n":"另一星官"},{"t":"文曲星","n":"星神与星官"},{"t":"哈雷彗星","n":"中国有早期记录"}],"exam":[]},{"id":"a07-040","t":"北斗七星","cid":"07d","p":3,"kind":"合称","alias":["北斗"],"one":"大熊座七颗明亮恒星，勺状排列，古代用于辨别方向与判定时令季节。","ans":"北斗七星是大熊座排列成勺状的七颗亮星，依次为**天枢、天璇、天玑、天权、玉衡、开阳、摇光**。前四星称斗魁，后三星称斗杓。天璇与天枢连线延长约五倍可定**北极星**以辨方向。古人借斗柄旋转判定季节，如**“斗柄东指，天下皆春”**。","pts":["天枢天璇天玑天权玉衡开阳摇光七星","前四星为斗魁，后三星为斗杓","延长天璇天枢找北极星；斗柄指向定四季"],"members":[["天枢","北斗第一星，魁首，与天璇相连指向北极星，道教称贪狼星"],["天璇","北斗第二星，与天枢连线延长约五倍即为北极星，道教称巨门星"],["天玑","北斗第三星，斗身第三角，道教称禄存星"],["天权","北斗第四星，斗勺与斗柄连接处，光芒最暗，道教称文曲星"],["玉衡","北斗第五星，斗柄第一星，北斗中最亮的一颗，道教称廉贞星"],["开阳","北斗第六星，斗柄第二星，旁有暗星辅星，道教称武曲星"],["摇光","北斗第七星，斗柄最末端之星，道教称破军星，斗柄所指即为此星方向"]],"mem":"七星口诀：“枢璇玑权（斗魁身），衡阳摇光（斗柄尾）”；斗柄指东天下春。","mix":"指向北极星的是天璇向天枢方向延长5倍；第四星天权星在古代传说中对应文曲星，而非文昌星。","mcq":[{"q":"中国古代根据北斗星斗柄的指向来判断季节，古语“斗柄东指”所对应的季节是","o":["夏季","秋季","春季","冬季"],"a":2,"w":"《鹖冠子》载：“斗柄东指，天下皆春；斗柄南指，天下皆夏；斗柄西指，天下皆秋；斗柄北指，天下皆冬。”"}],"rel":[{"t":"古代计时","n":"天文观测与历法计时"},{"t":"孟仲季与月份别称","n":"传统历法岁时体系"}],"exam":[]},{"id":"a07-041","t":"太初历","cid":"07d","p":2,"kind":"制度","alias":["太初历法"],"one":"西汉武帝太初元年（前104年）颁行，首次把二十四节气订入历法，以正月为岁首。","ans":"太初历是**西汉汉武帝太初元年（前104年）颁行**的历法，由**邓平、落下闳**等制定，司马迁也参与改历。它**以正月为岁首**，改变了汉初沿用的以十月为岁首的做法，**首次把二十四节气订入历法**，并规定无中气之月为闰月，使节气、季节与月份相配。太初历一年约365.2502日，推行近两百年，奠定了中国农历的基本格局。","pts":["前104年颁行，邓平、落下闳等制定","正月为岁首","首次把二十四节气订入历法"],"mem":"画面：汉武帝改年号为“太初”，同时把岁首从十月移到正月。口诀：“太初历，订节气，岁首正月”。","mix":"授时历（元）一年365.2425日，太初历约365.2502日；祖冲之的《大明历》属南朝；二十四节气的概念早于太初历，但订入历法始于太初历。","mcq":[{"q":"首次把二十四节气订入历法的是","o":["颛顼历","太初历","大明历","授时历"],"a":1,"w":"太初历首次把二十四节气订入历法。"}],"rel":[{"t":"汉武帝","n":"改历的君主"},{"t":"二十四节气","n":"订入历法"},{"t":"授时历与郭守敬","n":"历法发展对照"},{"t":"农历","n":"基本格局的奠定"},{"t":"闰月与十九年七闰","n":"闰月规则"}],"exam":[]},{"id":"a07-042","t":"授时历与郭守敬","cid":"07d","p":2,"kind":"制度","alias":["授时历","郭守敬"],"one":"元代郭守敬、王恂等制定，1281年颁行，一年365.2425日，与现行公历相同。","ans":"授时历是**元代郭守敬、王恂、许衡等人制定的历法**，**1281年（至元十八年）颁行**，是中国古代最精确的历法之一，为明代大统历所沿用。它测定一年为**365.2425日**，与今天通行的公历（格里高利历）数值相同，却**早约三百年**（格里高利历1582年颁行）。郭守敬为此发明**简仪、仰仪**等仪器，在全国设二十七处观测点进行“四海测验”，还主持修治大运河通惠河。","pts":["元代郭守敬等制定，1281年颁行","一年365.2425日，同公历","简仪、仰仪，四海测验"],"mem":"年份对比：授时历1281，格里高利历1582，相差约三百年；数值同为365.2425。","mix":"太初历一年约365.2502日，与授时历不同；格里高利历是欧洲历法，授时历先于它数百年。","mcq":[{"q":"授时历测定的一年长度为","o":["365.25日","365.2425日","365.2502日","366日"],"a":1,"w":"授时历定一年为365.2425日，与公历相同。"}],"rel":[{"t":"太初历","n":"历法发展对照"},{"t":"公历闰年","n":"与公历相同的数值"},{"t":"农历","n":"历法体系"},{"t":"张衡","n":"古代天文成就"},{"t":"哥白尼日心说","n":"中西天文对照"}],"exam":[]},{"id":"a07-043","t":"朔、望、晦、朏","cid":"07d","p":2,"kind":"合称","alias":["朔望晦朏","既望"],"one":"朔为初一，望为十五（或十六），晦为月末，朏为初三。","ans":"朔、望、晦、朏是**农历表示月相和日期的古称**：**朔**为每月初一，月球运行到日地之间，月面不可见；**望**为十五（或十六），月亮最圆；**晦**为月末最后一天，月光全无；**朏**为初三，新月初现微光。此外十六称**既望**，如苏轼《赤壁赋》“壬戌之秋，七月既望”；上弦在初七八，下弦在廿二三。这些称谓体现农历以月相定月的特点。","pts":["朔初一，望十五，晦月末","朏为初三，既望为十六","农历以月相定月"],"members":[["朔","每月初一，月不可见"],["朏","初三，新月初现"],["望","十五或十六，满月"],["晦","月末最后一天，月光全无"]],"mem":"口诀“初一朔，初三朏，十五望，月末晦”。月亮由暗到亮再到暗：朔暗，朏初光，望满，晦又暗。","mix":"朔日常发生日食，望日常发生月食；朏读fěi，不读fēi；既望指十六，不是十五。","mcq":[{"q":"农历每月十五（或十六），月亮最圆的日子称为","o":["朔","晦","望","朏"],"a":2,"w":"望指月圆之日，朔为初一，晦为月末，朏为初三。"}],"rel":[{"t":"农历","n":"月相历法"},{"t":"日食与月食","n":"朔日日食、望日月食"},{"t":"中秋节","n":"八月十五望月"},{"t":"闰月与十九年七闰","n":"朔望月与闰月"}],"exam":[]},{"id":"a07-044","t":"干支纪年与历史事件","cid":"07d","p":2,"kind":"常识","alias":["干支纪年","甲午年","戊戌年","辛亥年"],"one":"以天干地支六十年一轮纪年，近代大事常以干支命名。","ans":"干支纪年是**以十天干与十二地支依次相配、六十年一循环的纪年方法**，起于汉代并沿用至今。近代史上许多事件以干支命名：**甲午战争（1894）、戊戌变法（1898）、辛丑条约（1901）、辛亥革命（1911）**。推算时，公历年份减3后除以10的余数定天干，除以12的余数定地支。2026年为**丙午马年**，2027年为丁未羊年。掌握干支可以直接由事件名反推年份，也能判断事件先后。","pts":["天干地支相配，六十年一循环","甲午1894、戊戌1898、辛丑1901、辛亥1911","2026丙午年，2027丁未年"],"mem":"换算公式：公历年减3，除以10看余数定天干（1甲2乙3丙4丁5戊6己7庚8辛9壬0癸），除以12看余数定地支（1子2丑3寅4卯5辰6巳7午8未9申10酉11戌0亥）。例：2026减3得2023，余数3为丙，余数7为午，所以是丙午。四件大事的间隔记“4、3、10”：1894甲午，加4年1898戊戌，加3年1901辛丑，加10年1911辛亥。","mix":"1900年是庚子年（庚子事变、八国联军侵华），1840年也是庚子年（鸦片战争），两者相差60年；1898戊戌与1894甲午不要对调。","mcq":[{"q":"“辛亥革命”爆发的公历年份是","o":["1898年","1901年","1911年","1894年"],"a":2,"w":"辛亥年即1911年；1894甲午、1898戊戌、1901辛丑。"}],"rel":[{"t":"天干地支","n":"干支纪年的基础"},{"t":"十二生肖","n":"与地支相配"},{"t":"干支与近代史事件","n":"同类词条"},{"t":"甲午中日战争","n":"1894年甲午"},{"t":"辛亥革命","n":"1911年辛亥"}],"more":"1840庚子（鸦片战争）｜1894甲午｜1898戊戌｜1900庚子｜1901辛丑｜1911辛亥｜2026丙午｜2027丁未","exam":[]},{"id":"a07-045","t":"孟仲季与月份别称","cid":"07d","p":3,"kind":"常识","alias":["孟仲季","月份别称"],"one":"古代按孟仲季区分四季月份的排次法，以及端月、腊月等传统纪月别名。","ans":"孟仲季与月份别称是我国古代独特的**纪月常识体系**。古人将四季中每季的三月依次冠以**孟、仲、季**表示先后，如**孟春为正月、仲秋为八月、季冬为十二月**。各月另有雅称，如**正月称端月（避秦始皇讳）**，八月称桂月，**十二月称腊月**。","pts":["每季三月依次称孟、仲、季","正月为孟春、八月为仲秋、十二月为季冬","正月避秦讳称端月，十二月称腊月"],"mem":"排序口诀：“伯仲叔季长幼序，孟仲季春分早迟”；秦避皇讳称端月，岁末祭祀叫腊月。","mix":"伯仲叔季用于兄弟排行；孟仲季用于一季中三个月份排次；仲秋是农历八月（中秋节所在月）。","mcq":[{"q":"古代按“孟、仲、季”纪月，农历八月对应的称谓以及正月的著名避讳别称分别是","o":["仲秋、端月","孟秋、腊月","季秋、元月","仲秋、杏月"],"a":0,"w":"秋季三个月依次为孟秋、仲秋、季秋；正月因避秦始皇嬴政讳而改称“端月”。"}],"rel":[{"t":"十二时辰","n":"古代历法计时系统"},{"t":"古代计时","n":"古代时间制度"},{"t":"农历","n":"中国传统阴阳合历"}],"exam":[]},{"id":"a07-046","t":"三伏与数九","cid":"07d","p":3,"kind":"常识","alias":["三伏天与数九寒天","三伏数九"],"one":"中国民间标志一年中最热盛夏（三伏）与最冷寒冬（数九）的推算节令。","ans":"三伏与数九是中国民间推算**一年中最热与最冷时段**的传统节令。**三伏**包含初伏、中伏与末伏，自夏至后第三个庚日起算；**数九**自**冬至日起算**，每九天为一个“九”，合“九九八十一天”至春暖，民间合称**“冷在三九，热在三伏”**。","pts":["三伏为夏至后庚日推算，为一年最热时段","数九从冬至起算，每九天一单元共八十一天","合称“冷在三九，热在三伏”"],"mem":"民谚直记：“夏至三庚入头伏，冬至交九数到春；冷在三九，热在三伏”。","mix":"三伏不是从夏至当天开始，而是从“夏至后第三个庚日”入伏；数九则是从“冬至”开始起算。","mcq":[{"q":"中国民间常说“冷在三九，热在三伏”，其中“数九寒天”开始计算的节气节点是","o":["立冬","冬至","大雪","小寒"],"a":1,"w":"“数九”自冬至当天起算，每九天为一个阶段，共九九八十一天。"}],"rel":[{"t":"冬至与夏至","n":"推算起点的核心节气"},{"t":"二十四节气","n":"传统农历岁时节令"}],"exam":[]},{"id":"a07-047","t":"七十二候","cid":"07d","p":3,"kind":"概念","alias":["二十四节气七十二候"],"one":"中国古代结合天文物候对二十四节气的进一步细分，一节气分三候，全年共七十二候。","ans":"七十二候是我国古代结合**动植物物候变化**制定的时令系统。古人将**每个节气均分为三候，每候五天，全年二十四节气共合七十二候**。每候以一种典型自然物候为标志，如立春初候为“东风解冻”。七十二候细致揭示了物候节律，用以**指导精细农耕**。","pts":["每个节气分为三候，每候五日，共七十二候","以动植物生长与自然物候现象为标识","二十四节气配套知识，指导农耕物候"],"mem":"算法公式：“五日为一候，三候为一气，六气为一时，四时为一岁”（5×3×24=360日）。","mix":"“五日一候，三候一气”；一候是5天，一个节气是15天（包含初候、二候、三候）。","mcq":[{"q":"我国古代历法将一年二十四节气进一步细分，其划分标准是每个节气包含几候、每候几天","o":["分二候，每候七天","分四候，每候四天","分三候，每候五天","分五候，每候三天"],"a":2,"w":"古代历法“五日为一候，三候为一气”，每个节气包含三候，每候五天，全年共七十二候。"}],"rel":[{"t":"二十四节气","n":"七十二候母体时令体系"},{"t":"冬至与夏至","n":"节气关键节点"}],"exam":[]},{"id":"a07-048","t":"闰月与十九年七闰","cid":"07d","p":3,"kind":"常识","alias":["十九年七闰","农历置闰法"],"one":"农历协调朔望月与回归年长度的置闰法则，每十九个太阳年中插入七个闰月。","ans":"闰月与十九年七闰是中国农历**协调朔望月与回归年周期**的置闰方法。农历平年比回归年短约11天。古人发现**19个回归年与235个朔望月日数几乎相等**，故采用**“十九年七闰”**法，在19年中加入7个闰月，确保了农历节气与四季物候严格吻合。","pts":["农历协调阴历月与太阳年的置闰方法","19个回归年插入7个闰月以平衡季节岁实","现代按“无中气置闰”规则确定闰月"],"mem":"巧记数字：“十九年里加七闰，阴阳合历两头准”（19年加7个闰月）。","mix":"“十九年七闰”是古代确立的置闰周期；现代农历确定具体哪个月是闰月则依据该月“无中气”原则。","mcq":[{"q":"中国古代传统历法为协调朔望月与回归年的时间差，在春秋战国时期普遍采用的置闰周期是","o":["八年三闰","十二年五闰","三十年十闰","十九年七闰"],"a":3,"w":"古代中国发现19个回归年与235个朔望月几乎等长，因而采用“十九年七闰”的置闰方法。"}],"rel":[{"t":"农历","n":"中国传统阴阳合历"},{"t":"公历闰年","n":"中西历法闰法对照"},{"t":"二十四节气","n":"农历置闰的中气参照"}],"exam":[]},{"id":"a07-049","t":"圭表、日晷与漏刻","cid":"07d","p":3,"kind":"常识","alias":["古代三大计时仪器","圭表日晷漏刻"],"one":"中国古代测定节气与时间的三大代表性天文计时仪器。","ans":"圭表、日晷与漏刻是**中国古代三大代表性天文计时仪器**。圭表利用**表圭测正午日影长度**以定节气；日晷依据**晷针日影方向测定时辰**；漏刻通过**水流滴注与箭尺升降计量时间**，一昼夜分为**一百刻**。三者体现了古人的天文科技智慧。","pts":["圭表测正午日影长以定节气与岁长","日晷依据晷针日影方向测定时辰","漏刻以水滴计时，一昼夜分一百刻"],"mem":"功能口诀：“**圭表测影定节气，日晷观针认时辰，漏刻滴水数百刻**”。","mix":"圭表测正午影长定节气（测年），日晷测影向定时辰（测日），漏刻靠水滴全天候昼夜计时不受阴晴限制。","mcq":[{"q":"中国古代利用水流滴注与刻箭升降来计量昼夜时间的仪器是","o":["漏刻","日晷","圭表","浑天仪"],"a":0,"w":"漏刻通过流水滴漏和箭尺升降计量昼夜时间；日晷和圭表利用日影观测。"}],"rel":[{"t":"十二时辰","n":"日晷测定时间单位"},{"t":"二十四节气","n":"圭表测定节气划分"},{"t":"授时历与郭守敬","n":"郭守敬创制简仪高表"}],"exam":[]},{"id":"a07-050","t":"元宵节","cid":"07e","p":2,"kind":"常识","alias":["上元节","灯节","元夕"],"one":"正月十五，赏灯、吃元宵、猜灯谜。","ans":"元宵节是**农历正月十五的传统节日**，又称上元节、灯节，是春节庆祝活动的收尾。古人称正月为“元月”，夜为“宵”，故名元宵。节日习俗以**赏灯、吃元宵（汤圆）、猜灯谜**为主，也有舞龙舞狮等活动。相关诗词有辛弃疾《青玉案·元夕》，其中“众里寻他千百度，蓦然回首，那人却在，灯火阑珊处”写元夕灯火中的寻觅，后来常被引用。元宵节在汉代已有张灯习俗，唐宋时灯会最盛。","pts":["正月十五，又称上元节、灯节","赏灯、吃元宵、猜灯谜","辛弃疾《青玉案·元夕》"],"mem":"一个画面：正月十五夜，满城花灯，人群里有个人在找人，找了千百遍，一回头，人在灯火稀疏的角落，这就是《青玉案·元夕》。节日顺序记“初一春节，十五元宵”，春节的尾声就是元宵。","mix":"元宵既指节日也指食品，北方称“元宵”，南方多称“汤圆”；同样是灯会诗，唐代苏味道《正月十五夜》与辛弃疾此词不是同一首。","mcq":[{"q":"下列诗词中，写元宵节观灯情景的是","o":["王维《九月九日忆山东兄弟》","秦观《鹊桥仙》","杜牧《清明》","辛弃疾《青玉案·元夕》"],"a":3,"w":"《青玉案·元夕》写正月十五夜灯火；其余分别写重阳、七夕、清明。"}],"rel":[{"t":"春节列入人类非遗代表作名录","n":"元宵为春节收尾"},{"t":"辛弃疾","n":"《青玉案·元夕》作者"},{"t":"中秋节","n":"同为月圆之节"},{"t":"中国传统四大节日","n":"相邻节日群"}],"more":"名句：东风夜放花千树，更吹落，星如雨。｜辛弃疾《青玉案·元夕》\n众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。｜同上","exam":[]},{"id":"a07-051","t":"上巳节","cid":"07e","p":2,"kind":"常识","alias":["三月三","修禊","祓禊","女儿节"],"one":"三月初三，水边祓禊踏青，兰亭修禊即此日。","ans":"上巳节是**古代在三月上旬巳日（魏晋后固定为农历三月初三）举行的节日**，主要习俗是**到水边沐浴洗濯、祓除不祥，称“祓禊”**，并伴有踏青、宴饮。东晋永和九年（353年）三月三日，**王羲之等人在会稽山阴兰亭修禊**，作《兰亭集序》，使这一习俗成为文学名篇的背景。杜甫《丽人行》“三月三日天气新，长安水边多丽人”写唐代长安上巳游春。后来上巳节渐衰，部分习俗并入清明与踏青，壮族、黎族等仍有“三月三”节庆。","pts":["三月初三，水边祓禊、踏青","兰亭修禊：王羲之作《兰亭集序》","杜甫《丽人行》写长安上巳游春"],"mem":"“三月三，修禊玩水边。”把三个关键词挂在一起：三月三、兰亭、王羲之。兰亭那次是353年（永和九年），记“永和九年，岁在癸丑”，开头第一句就是年份。","mix":"上巳节与清明节日期相邻但不同，上巳在农历三月初三，清明是节气；壮族“三月三”是民族节日，来源不同，不要混为同一节。","mcq":[{"q":"王羲之等人在兰亭举行修禊活动的节日是","o":["上巳节","寒食节","重阳节","七夕节"],"a":0,"w":"永和九年三月三日上巳，修禊于兰亭。"}],"rel":[{"t":"《兰亭集序》","n":"修禊之作"},{"t":"王羲之","n":"兰亭雅集主持者"},{"t":"寒食节与清明节","n":"春季踏青相邻"},{"t":"少数民族传统节日","n":"壮族三月三"}],"more":"《兰亭集序》开篇：永和九年，岁在癸丑，暮春之初，会于会稽山阴之兰亭，修禊事也。\n杜甫《丽人行》：三月三日天气新，长安水边多丽人。","exam":[]},{"id":"a07-052","t":"寒食节与清明节","cid":"07e","p":1,"kind":"常识","alias":["寒食节","清明节","清明","寒食"],"one":"寒食禁火冷食纪念介子推；清明是节气也是节日，扫墓踏青。","ans":"寒食节在**冬至后105日**，约在清明前一两天，节日期间**禁火、只吃冷食**，相传为纪念晋国**介子推**：晋文公焚山逼他出仕，介子推抱树而死，文公遂下令禁火。清明既是**二十四节气之一**，又是传统节日，习俗为**扫墓祭祖、踏青**。唐宋以后寒食与清明逐渐合并，寒食扫墓的习俗并入清明。杜牧《清明》“清明时节雨纷纷，路上行人欲断魂”写的正是清明扫墓的情境。","pts":["寒食在冬至后105日，禁火冷食","纪念介子推；清明是节气兼节日","扫墓踏青，杜牧《清明》"],"mem":"一条时间线：冬至后105日寒食，紧接清明。因果：介子推被火逼死，所以寒食“不动火”；清明接过寒食的扫墓习俗，才有了“清明祭祖”。诗对号：杜牧《清明》雨纷纷，王维《九月九日》是重阳，别串。","mix":"寒食纪念介子推，端午纪念屈原；清明是节气，寒食不是节气；《黄州寒食诗帖》（苏轼）与寒食节相关。","mcq":[{"q":"相传寒食节是为纪念谁而设","o":["屈原","伍子胥","介子推","曹娥"],"a":2,"w":"寒食禁火冷食相传为纪念晋国介子推。"},{"q":"“清明时节雨纷纷，路上行人欲断魂”的作者是","o":["王维","杜甫","苏轼","杜牧"],"a":3,"w":"这是杜牧的《清明》。"}],"rel":[{"t":"二十四节气","n":"清明是节气"},{"t":"《黄州寒食诗帖》","n":"苏轼书写寒食"},{"t":"端午节","n":"另一纪念性节日"},{"t":"节令酒与节令食","n":"青团等节令食"},{"t":"杜牧","n":"《清明》作者"}],"more":"清明｜杜牧\n清明时节雨纷纷，路上行人欲断魂。借问酒家何处有？牧童遥指杏花村。","exam":[]},{"id":"a07-053","t":"七夕节","cid":"07e","p":2,"kind":"常识","alias":["乞巧节","七巧节","女儿节"],"one":"七月初七，牛郎织女鹊桥相会，女子乞巧。","ans":"七夕节是**农历七月初七的传统节日**，又称乞巧节，源于对星辰的崇拜和牛郎织女的民间传说。传说织女与牛郎被银河阻隔，每年七夕**喜鹊搭桥使二人相会**，牛郎织女故事列入中国四大民间传说。节日习俗以**女子乞巧**（穿针比巧、拜织女）为主。诗词方面，**秦观《鹊桥仙》**“金风玉露一相逢，便胜却人间无数”和《古诗十九首》“迢迢牵牛星”都写此事。七夕被视为中国的情人节，乞巧习俗已列入国家级非物质文化遗产。","pts":["七月初七，又称乞巧节","牛郎织女，喜鹊搭桥相会","秦观《鹊桥仙》；《迢迢牵牛星》"],"mem":"“七月七，鹊搭桥，织女穿针乞巧。”诗词挂钩：秦观《鹊桥仙》是七夕的标准答案，“两情若是久长时，又岂在朝朝暮暮”是最常考名句；七夕对应的两颗星是牵牛星与织女星。","mix":"同样写爱情的《长恨歌》与七夕无关，只是里面有“七月七日长生殿”一句；重阳（九月初九）与七夕（七月初七）都是重数日，注意区分。","mcq":[{"q":"秦观《鹊桥仙》所写的传统节日是","o":["中秋节","重阳节","元宵节","七夕节"],"a":3,"w":"《鹊桥仙》咏牛郎织女，对应七夕。"}],"rel":[{"t":"秦观","n":"《鹊桥仙》作者"},{"t":"四大民间传说","n":"牛郎织女在列"},{"t":"中秋节","n":"同为秋季节日"},{"t":"重阳节","n":"同为重数日"}],"more":"名句：纤云弄巧，飞星传恨，银汉迢迢暗度。金风玉露一相逢，便胜却人间无数。｜秦观《鹊桥仙》\n天阶夜色凉如水，卧看牵牛织女星。｜杜牧《秋夕》","exam":[]},{"id":"a07-054","t":"中秋节","cid":"07e","p":2,"kind":"常识","alias":["仲秋节","团圆节","八月十五"],"one":"八月十五，赏月吃月饼，苏轼《水调歌头》为代表之作。","ans":"中秋节是**农历八月十五的传统节日**，源于古代对月亮的祭拜，又称团圆节。节日习俗以**赏月、吃月饼、家人团聚**为主，并有嫦娥奔月、吴刚伐桂等传说。文学上最著名的是**苏轼《水调歌头·明月几时有》**，作于1076年（熙宁九年）中秋，词中“但愿人长久，千里共婵娟”表达对弟弟苏辙的思念和对人间离合的达观。中秋节与春节、清明、端午并称中国传统四大节日，2008年起成为法定节假日。","pts":["八月十五，赏月、吃月饼、团圆","苏轼《水调歌头》，怀念苏辙","与春节、清明、端午并称四大节日"],"mem":"“八月十五月儿圆”，三个动作：看月（赏月）、吃饼（月饼）、望人（团圆）。《水调歌头》记两个数字：1076年，写给弟弟苏辙（字子由）。最后一句“千里共婵娟”，婵娟指月亮。","mix":"“海上生明月，天涯共此时”是张九龄《望月怀远》，不是苏轼作；中秋词不要与秦观七夕词《鹊桥仙》混淆。","mcq":[{"q":"“但愿人长久，千里共婵娟”出自苏轼哪首词","o":["《念奴娇·赤壁怀古》","《定风波》","《江城子·密州出猎》","《水调歌头·明月几时有》"],"a":3,"w":"作于中秋，怀念苏辙。"}],"rel":[{"t":"苏轼","n":"《水调歌头》作者"},{"t":"中国传统四大节日","n":"四大节日之一"},{"t":"七夕节","n":"同为秋季节日"},{"t":"元宵节","n":"同为月圆之节"}],"more":"名句：明月几时有？把酒问青天。｜苏轼《水调歌头》\n人有悲欢离合，月有阴晴圆缺，此事古难全。但愿人长久，千里共婵娟。｜同上","exam":[]},{"id":"a07-055","t":"重阳节","cid":"07e","p":1,"kind":"常识","alias":["重九","九九节","老年节","登高节"],"one":"农历九月初九，登高、插茱萸、赏菊，法定老年节。","ans":"重阳节在**农历九月初九**，古人以**“九”为阳数**，两九相重，故称重阳，也称重九。习俗有**登高、插茱萸、赏菊、饮菊花酒**、吃重阳糕。王维《九月九日忆山东兄弟》“遥知兄弟登高处，遍插茱萸少一人”是节日名篇。“九九”谐音“久久”，含长寿之意，**2012年修订的《老年人权益保障法》定农历九月初九为老年节**，使重阳增添敬老的现代内涵。","pts":["农历九月初九，九为阳数故称重阳","登高、插茱萸、赏菊、饮菊花酒","王维名篇；2012年法定老年节"],"mem":"“九九重阳”谐音“久久”，所以祝老人长寿。习俗四字：登、插、赏、饮（登高、插茱萸、赏菊、饮菊花酒）。诗对号：“独在异乡为异客”开头，“遍插茱萸少一人”结尾，作者王维，写时才十七岁左右。","mix":"登高也出现在杜甫《登高》，但那是写秋景，与节日习俗是两回事；端午赛龙舟、中秋赏月、元宵赏灯，不要和重阳习俗混。","mcq":[{"q":"“遥知兄弟登高处，遍插茱萸少一人”的作者是","o":["李白","王维","杜甫","王安石"],"a":1,"w":"出自王维《九月九日忆山东兄弟》。"},{"q":"下列习俗中，与重阳节无关的是","o":["登高","插茱萸","赏菊","赛龙舟"],"a":3,"w":"赛龙舟属于端午节。"}],"rel":[{"t":"节令酒与节令食","n":"菊花酒、重阳糕"},{"t":"中秋节","n":"同属秋季节日"},{"t":"端午节","n":"另一重要节日"},{"t":"王维","n":"重阳名篇作者"}],"more":"九月九日忆山东兄弟｜王维\n独在异乡为异客，每逢佳节倍思亲。遥知兄弟登高处，遍插茱萸少一人。","exam":[]},{"id":"a07-056","t":"中国传统四大节日","cid":"07e","p":2,"kind":"合称","alias":["四大传统节日"],"one":"春节、清明节、端午节、中秋节。","ans":"中国传统四大节日通常指**春节、清明节、端午节、中秋节**，是民间流传最广、最受重视的四个传统节日。**春节**在正月初一，辞旧迎新；**清明**在4月上旬，祭祖扫墓与踏青；**端午**在五月初五，赛龙舟、吃粽子，纪念屈原；**中秋**在八月十五，赏月团圆。2008年起，清明、端午、中秋被列为法定节假日。**春节（2024年）与端午（2009年）已分别列入人类非物质文化遗产代表作名录**。","pts":["春节、清明、端午、中秋","各自习俗：守岁、扫墓、龙舟、赏月","端午2009年、春节2024年入选人类非遗"],"members":[["春节","正月初一；守岁、贴春联"],["清明节","节气兼节日；扫墓踏青"],["端午节","五月初五；龙舟粽子，纪念屈原"],["中秋节","八月十五；赏月团圆"]],"mem":"口诀“春清端中”：春天一头一尾（春节、清明），夏有端午，秋有中秋，正好一季一节（冬季无节）。四个节日各配一个动作：守岁、扫墓、划船、望月。","mix":"重阳、元宵、七夕在民间同样重要，但不在“四大节日”之列；也有把春节、端午、中秋并称“三大传统节日”的说法。","mcq":[{"q":"下列节日中，不属于中国传统四大节日的是","o":["春节","清明节","重阳节","中秋节"],"a":2,"w":"四大节日为春节、清明、端午、中秋。"}],"rel":[{"t":"春节列入人类非遗代表作名录","n":"2024年入选"},{"t":"端午节","n":"2009年入选非遗"},{"t":"中秋节","n":"四大节日之一"},{"t":"寒食节与清明节","n":"四大节日之一"}],"more":"2008年起清明、端午、中秋成为法定节假日；春节早已是法定假日。","exam":[]},{"id":"a07-057","t":"节令酒与节令食","cid":"07e","p":1,"kind":"常识","alias":["节令饮食","岁时饮食","节日食俗"],"one":"屠苏酒、雄黄酒、菊花酒；元宵、青团、粽子、月饼、重阳糕、腊八粥。","ans":"节令酒与节令食指**岁时节日中约定俗成的饮品与食品**。酒类有**元日饮屠苏酒、椒柏酒，端午饮菖蒲酒、雄黄酒，重阳饮菊花酒**，多取辟邪祛病、延年益寿之意。食类有**元宵节吃元宵，清明吃青团，端午吃粽子，中秋吃月饼，重阳吃重阳糕，腊八吃腊八粥**。这些饮食与时令物候和纪念传说相连，如粽子与纪念屈原有关，使节日有可感的物质载体，构成岁时民俗的重要部分。","pts":["元日屠苏、端午雄黄、重阳菊花酒","元宵、青团、粽子、月饼、重阳糕、腊八粥","取辟邪祛病之意，与时令传说相连"],"members":[["屠苏酒、椒柏酒","春节（元日）"],["菖蒲酒、雄黄酒","端午"],["菊花酒","重阳"],["元宵","元宵节"],["青团","清明（江南）"],["粽子","端午"],["月饼","中秋"],["重阳糕","重阳"],["腊八粥","腊月初八"]],"mem":"按一年顺序串：春节屠苏酒、元宵吃元宵、清明吃青团、端午粽子配雄黄酒、中秋月饼、重阳糕配菊花酒、腊八喝粥。酒的口诀“春屠苏，夏雄黄，秋菊花”，对应春节、端午、重阳。","mix":"2026选择考屠苏（酒），干扰项是食物和房屋；雄黄酒现代已不提倡饮用；中秋酒俗多为桂花酒，不属于常考重点。","mcq":[{"q":"重阳节的节令酒是","o":["屠苏酒","雄黄酒","椒柏酒","菊花酒"],"a":3,"w":"重阳登高赏菊，饮菊花酒；屠苏、椒柏是元日酒，雄黄是端午酒。"},{"q":"下列节日与节令食搭配不正确的是","o":["清明：青团","重阳：重阳糕","端午：月饼","腊八：腊八粥"],"a":2,"w":"端午吃粽子，中秋才吃月饼。"}],"rel":[{"t":"屠苏","n":"元日药酒"},{"t":"端午节","n":"粽子与雄黄酒"},{"t":"重阳节","n":"菊花酒与重阳糕"},{"t":"中秋节","n":"月饼"},{"t":"元宵节","n":"元宵"}],"more":"佛教节日腊八（腊月初八）喝腊八粥，与佛成道日相传有关。","exam":[]},{"id":"a07-058","t":"腊八节与小年","cid":"07e","p":3,"kind":"常识","alias":["腊八与小年","腊日祭灶"],"one":"农历岁末以喝腊八粥与祭灶扫尘为核心风俗的迎春序幕节俗。","ans":"腊八节与小年是**中国农历岁末迎接春节的传统节俗**。腊月初八**腊八节相传为佛祖成道日**，民间有**喝腊八粥、泡腊八蒜**习俗；腊月二十三或二十四为**小年**，民间举行**祭灶神、扫尘土、吃灶糖**等仪式，拉开了春节年庆的序幕。","pts":["腊月初八喝腊八粥，源自佛祖成道日","小年祭灶神扫尘土，北二十三南二十四","岁末迎春序幕节俗"],"mem":"口诀：“**腊八喝粥念佛祖，小年祭灶扫尘土**”，先喝热粥润肚，再送灶王上天。","mix":"小年祭灶时间南北不同（北方腊月二十三，南方腊月二十四）；吃灶糖寓意“粘住灶王嘴，上天言好事”。","mcq":[{"q":"下列传统民俗中，属于农历‘小年’核心习俗的是","o":["水边修禊","插茱萸登高","吃冷食禁火","祭灶神与扫尘"],"a":3,"w":"小年核心习俗为祭灶王、扫尘、吃灶糖；水边修禊为上巳，插茱萸为重阳，禁火为寒食。"}],"rel":[{"t":"春节列入人类非遗代表作名录","n":"岁末节俗引向春节"},{"t":"桃符与春联","n":"春节迎新民俗承接"},{"t":"寒食节与清明节","n":"传统岁时节令对照"}],"exam":[]},{"id":"a07-059","t":"中元节","cid":"07e","p":3,"kind":"常识","alias":["七月半","盂兰盆节","鬼节"],"one":"农历七月十五集道教中元、佛教盂兰盆会与民间祭祖于一体的传统节日。","ans":"中元节是**农历七月十五的传统祭祖节日**，俗称“七月半”。在道教中为**地官赦罪之日**；在佛教中源于目连救母典故，称为**盂兰盆节**。民间有**祭祖、放河灯、焚纸锭与施孤**等习俗，体现了**慎终追远、尽孝报恩**的传统伦理。","pts":["农历七月十五，道教称中元、地官赦罪","佛教称盂兰盆节，源于目连救母","习俗有祭祖、放河灯、施孤，弘扬孝道"],"mem":"联想：“**七月十五地官赦，中元放灯渡盂兰**”，道教赦罪，佛教报亲恩。","mix":"道教“三元”指上元（正月十五元宵）、中元（七月十五）、下元（十月十五）；中元节与清明节、寒衣节并称中国三大冥节。","mcq":[{"q":"道教‘三元’中的‘中元节’对应农历哪一天","o":["七月十五","正月十五","五月初五","十月十五"],"a":0,"w":"正月十五为上元节，七月十五为中元节，十月十五为下元节。"}],"rel":[{"t":"元宵节","n":"道教上元节对应"},{"t":"寒食节与清明节","n":"同属传统祭祖节令"},{"t":"七夕节","n":"同在农历七月岁时"}],"exam":[]},{"id":"a07-060","t":"社日","cid":"07e","p":3,"kind":"常识","alias":["社日节","春社","秋社"],"one":"古代立春立秋后第五个戊日祭祀土地神祈丰收报恩德的传统节日。","ans":"社日是**中国古代祭祀土地神的传统节日**，分为**春社与秋社**，通常在**立春或立秋后的第五个戊日**举行。春社祈求丰收，秋社报答神恩；民间有**饮治聋酒、演社戏与聚饮**等风俗。唐代诗人王驾作有**《社日》**名篇传诵至今。","pts":["古代祭祀土地神的节日，分春社与秋社","在立春或立秋后第五个戊日举行","春社祈丰收秋社酬神，王驾留有《社日》"],"mem":"口诀：“**春祈秋报戊日聚，社日醉归王驾诗**”，立春立秋第五戊，祈丰报德敬土地。","mix":"社日依干支戊日推算（戊在五行中属土），非固定农历初几；春社主祈谷，秋社主报赛；鲁迅《社戏》所写的社戏即源于社日酬神演戏。","mcq":[{"q":"“桑柘影斜春社散，家家扶得醉人归”描绘的是哪个传统节日的风俗景象","o":["寒食节","社日","重阳节","中秋节"],"a":1,"w":"出自唐代诗人王驾《社日》，描写春社祭祀土地神后乡民聚饮尽欢的淳朴景象。"}],"rel":[{"t":"二十四节气","n":"社日依立春立秋推算"},{"t":"重阳节","n":"同含农事祈丰酬报风俗"},{"t":"天干地支","n":"社日取干支戊日"}],"exam":[]},{"id":"a07-061","t":"桃符与春联","cid":"07e","p":3,"kind":"常识","alias":["桃符","春联","门对"],"one":"古代画神除祟的桃木板演变为红纸书写迎春吉语的年俗演进。","ans":"桃符与春联是**中国春节标志性辟邪迎祥民俗**。早期在桃木板画**神荼、郁垒二神**挂于门旁辟邪；五代后蜀主孟昶题写**“新年纳余庆，嘉节号长春”**，为我国首副春联；明代红纸春联普及。王安石名句**“总把新桃换旧符”**记录了此风俗演变。","pts":["桃符原画神荼郁垒二神以辟邪驱鬼","五代后蜀主孟昶题写我国首副春联","明代红纸春联盛行，王安石诗句传诵"],"mem":"联想：“**桃木神荼驱恶鬼，孟昶新春题首联**”，王安石《元日》新桃换旧符。","mix":"桃符是桃木板（实物辟邪），春联是纸质对联（文字吉祥）；首副春联作者是五代后蜀主孟昶，并非李白或苏轼。","mcq":[{"q":"被公认为中国历史上第一副春联的是五代后蜀主孟昶题写的哪一句","o":["爆竹声中一岁除，春风送暖入屠苏","千门万户曈曈日，总把新桃换旧符","新年纳余庆，嘉节号长春","春色满园关不住，一枝红杏出墙来"],"a":2,"w":"孟昶题写的“新年纳余庆，嘉节号长春”为我国最早见诸记载的春联。"}],"rel":[{"t":"春节列入人类非遗代表作名录","n":"春节核心文化符号"},{"t":"王安石","n":"作《元日》写新桃换旧符"},{"t":"四大年画","n":"同属新春门面民俗"}],"exam":[]},{"id":"a07-062","t":"四大民间传说","cid":"07e","p":1,"kind":"合称","alias":["四大民间爱情传说","中国四大民间传说"],"one":"牛郎织女、孟姜女哭长城、梁山伯与祝英台、白蛇传。","ans":"四大民间传说指**牛郎织女、孟姜女哭长城、梁山伯与祝英台、白蛇传**四个流传最广的民间故事，多为爱情或婚姻悲剧题材。牛郎织女的星宿故事早见于《诗经·小雅·大东》，演化为**七夕节**的由来；孟姜女哭长城源于《左传》杞梁妻的记载；梁祝发生在东晋，被誉为“中国的罗密欧与朱丽叶”；**白蛇传**讲白素贞与许仙，明代冯梦龙《警世通言》收有《白娘子永镇雷峰塔》。四个故事长期以口头、戏曲、曲艺形式传承。","pts":["牛郎织女、孟姜女、梁祝、白蛇传","多为爱情悲剧，源流各异","牛郎织女与七夕，白蛇传见《警世通言》"],"members":[["牛郎织女","七夕节由来，早见于《诗经》"],["孟姜女哭长城","源于《左传》杞梁妻"],["梁山伯与祝英台","东晋，化蝶；越剧《梁祝》"],["白蛇传","白素贞与许仙，《白娘子永镇雷峰塔》"]],"mem":"一句话串：牛郎织女隔银河，孟姜女哭倒长城，梁祝化蝶，白蛇水漫金山，各用一个画面：河、墙、蝶、水。通行顺序“牛孟梁白”，首字谐音“牛猛量白”。","mix":"花木兰、嫦娥奔月、精卫填海是神话或民间故事，但不在这四大之列；《梁祝》小提琴协奏曲是1959年何占豪、陈钢创作的音乐作品。","mcq":[{"q":"下列不属于“四大民间传说”的是","o":["牛郎织女","孟姜女哭长城","嫦娥奔月","白蛇传"],"a":2,"w":"四大民间传说是牛郎织女、孟姜女哭长城、梁祝、白蛇传。"},{"q":"《白娘子永镇雷峰塔》收录于","o":["《喻世明言》","《警世通言》","《醒世恒言》","《初刻拍案惊奇》"],"a":1,"w":"冯梦龙“三言”中的《警世通言》收有该篇。"}],"rel":[{"t":"七夕节","n":"牛郎织女的节日"},{"t":"《梁祝》","n":"梁祝故事的音乐作品"},{"t":"冯梦龙","n":"白蛇传故事成型者"},{"t":"三言二拍","n":"白蛇传文本出处"},{"t":"《牡丹亭》","n":"古典爱情故事对照"}],"more":"牛郎织女、孟姜女传说、梁祝传说、白蛇传传说先后被列入国家级非物质文化遗产名录。","exam":[]},{"id":"a07-063","t":"少数民族传统节日","cid":"07e","p":2,"kind":"合称","alias":["民族节日"],"one":"泼水节、火把节、那达慕、雪顿节、三月三、开斋节与古尔邦节。","ans":"少数民族传统节日是**各民族根据自身历史、宗教和生产生活形成的节庆**。常见的有：**傣族泼水节**（傣历新年）、**彝族火把节**（农历六月下旬）、**蒙古族那达慕**（夏秋之际，有摔跤、赛马、射箭）、**藏族雪顿节**（藏历六月底七月初，有藏戏和晒大佛）、**壮族三月三**（对歌赛歌）、**回族、维吾尔族等的开斋节与古尔邦节**。这些节日保存各民族的歌舞、饮食与信仰，是中华文化多样性的体现，其中我国蒙古族那达慕于2006年列入首批国家级非遗名录（2010年蒙古国申报的“那达慕”列入人类非遗代表作名录）。","pts":["泼水节（傣）、火把节（彝）、那达慕（蒙古）","雪顿节（藏）、三月三（壮）、开斋节古尔邦节（回等）","体现中华文化多样性；我国那达慕2006年入首批国家级非遗"],"members":[["泼水节","傣族，傣历新年，泼水祝福"],["火把节","彝族等，农历六月下旬，点火把驱邪"],["那达慕","蒙古族，摔跤、赛马、射箭"],["雪顿节","藏族，藏历六月底，酸奶宴与藏戏"],["三月三","壮族，农历三月初三，对歌"],["开斋节与古尔邦节","回族、维吾尔族等伊斯兰教信仰民族"]],"mem":"配对记忆“水傣火彝，那蒙雪藏”：泼水配傣，火把配彝，那达慕配蒙古，雪顿配藏。壮族是“三月三歌圩”，伊斯兰教节日两个都带“节”字，开斋节在斋月结束后，古尔邦节又称宰牲节。","mix":"彝族民歌、倮倮（彝族旧称）、《格萨尔王传》（藏族史诗）都在近年真题里出现，选择题常以“哪个民族”设问；火把节也有白族、纳西族等民族过，但以彝族最有代表性。","mcq":[{"q":"“那达慕大会”是下列哪个民族的传统节日","o":["傣族","彝族","蒙古族","藏族"],"a":2,"w":"那达慕是蒙古族节日，有摔跤、赛马、射箭三项。"}],"rel":[{"t":"开斋节与古尔邦节","n":"伊斯兰教节日"},{"t":"倮倮","n":"彝族旧称，真题相关"},{"t":"《格萨尔王传》","n":"藏族史诗"},{"t":"上巳节","n":"与壮族三月三易混"}],"more":"泼水节：傣历新年，一般在公历4月中旬。\n火把节：彝族最隆重节日，农历六月二十四前后。\n那达慕：2006年列入我国首批国家级非遗名录；2010年蒙古国申报的“那达慕”列入人类非遗代表作名录。","exam":[]},{"id":"a07-064","t":"《阿诗玛》","cid":"07e","p":3,"kind":"作品","alias":["阿诗玛"],"one":"云南彝族撒尼人口头流传的长篇叙事诗与民族民间文学经典。","ans":"《阿诗玛》是**云南彝族撒尼人的著名民间长篇叙事诗**。作品讲述**阿诗玛与青年阿黑**抗争恶势力逼婚、化为石林的动人故事。1964年改编为**中国首部彩色音乐舞蹈电影**。作品展现了彝族人民**反抗强暴、追求自由爱情**的高贵品格。","pts":["云南彝族撒尼人传统口传长篇叙事诗","叙述阿诗玛与阿黑抗争逼婚化为石林","1964年改编为我国首部彩色音乐舞蹈电影"],"mem":"口诀：“**撒尼诗史阿诗玛，阿黑相伴化石林**”，1964年经典彩色歌舞电影。","mix":"《阿诗玛》是彝族撒尼人民间叙事诗（流传于云南石林），不是白族或傣族传说；中国三大英雄史诗是《格萨尔》《江格尔》《玛纳斯》，《阿诗玛》属于民间叙事诗。","mcq":[{"q":"流传于云南石林、讲述阿诗玛与阿黑抗争逼婚化为石林的民间长篇叙事诗属于哪个民族","o":["白族","纳西族","傣族","彝族撒尼人"],"a":3,"w":"《阿诗玛》是云南彝族撒尼人的口头叙事诗与民族民间文学经典。"}],"rel":[{"t":"《远方的客人请你留下来》","n":"同属彝族撒尼人艺术代表"},{"t":"倮倮","n":"同属彝族历史文化"},{"t":"中国三大英雄史诗","n":"少数民族民间史诗对照"}],"exam":[]},{"id":"a07-065","t":"冠礼与笄礼","cid":"07f","p":2,"kind":"制度","alias":["冠礼","笄礼","弱冠","及笄"],"one":"男子二十行冠礼，女子十五行笄礼，是古代成年礼。","ans":"冠礼与笄礼是**中国古代的成年礼**，属周代礼制中的嘉礼。**男子二十岁行冠礼**，束发加冠，表示成年，称“弱冠”；**女子十五岁行笄礼**，以笄（发簪）束发，称“及笄”，通常于许嫁时举行，未许嫁者至二十岁亦须行笄礼。《礼记》《仪礼·士冠礼》对仪式有详细记载。行冠礼后男子要**取字**，从此以字相称。冠笄之礼标志着个人获得社会身份，要承担对家族与社会的责任，与婚礼、丧礼一同构成人生礼仪。","pts":["男子二十行冠礼，称弱冠","女子十五行笄礼，称及笄","冠后取字，标志成年"],"mem":"数字口诀“男二十女十五”：男的“二十冠”，女的“十五笄”。字形帮记：冠是帽子（冠冕），笄是竹字头的发簪。成年之后要“字”，所以《礼记》说“男子二十冠而字”。","mix":"“弱冠”指二十岁，不是年纪小；“及笄”指十五岁，与“豆蔻”（十三四岁）、“碧玉年华”（十六岁）相邻易混。","mcq":[{"q":"古代女子年满十五行成年礼，称为","o":["及笄","弱冠","束发","而立"],"a":0,"w":"女子十五岁行笄礼，称及笄；弱冠指男子二十岁。"},{"q":"关于古代冠礼，说法正确的是","o":["女子二十行冠礼","男子二十行冠礼，之后取字","男子十五行冠礼","冠礼属于凶礼"],"a":1,"w":"冠礼属嘉礼，男子二十行之，礼成后取字。"}],"rel":[{"t":"姓氏与名、字、号","n":"冠后取字"},{"t":"童年与高龄称谓","n":"年龄称谓补全"},{"t":"五礼","n":"冠礼属嘉礼"},{"t":"三书六礼","n":"同为人生礼仪"}],"more":"《礼记·曲礼上》：人生十年曰幼，学。二十曰弱，冠。三十曰壮，有室。四十曰强，而仕。五十曰艾，服官政。六十曰耆，指使。七十曰老，而传。","exam":[]},{"id":"a07-066","t":"童年与高龄称谓","cid":"07f","p":2,"kind":"合称","alias":["年龄称谓","垂髫","总角","耄耋","期颐","鲐背","黄发"],"one":"襁褓、孩提、垂髫、总角、豆蔻；耄耋、期颐、黄发、鲐背。","ans":"古代常以**借代词**称不同年龄。童年阶段：**襁褓**指未满周岁，**孩提**指两三岁，**垂髫**指幼童（头发下垂未束），**总角**指童年（把头发扎成两角），**豆蔻**指十三四岁的少女。高龄阶段：**耄耋**指八九十岁，**期颐**指百岁，**黄发、鲐背**指高寿老人。这些词与弱冠、而立、不惑、知命、耳顺、古稀共同构成完整的年龄称谓体系，常出现在古诗文中，如陶渊明《桃花源记》“黄发垂髫，并怡然自乐”。","pts":["襁褓、孩提、垂髫、总角、豆蔻","耄耋八九十岁，期颐百岁","黄发、鲐背指高寿"],"members":[["襁褓","未满周岁"],["孩提","两三岁"],["垂髫","幼童"],["总角","童年"],["豆蔻","十三四岁女子"],["耄耋","八九十岁"],["期颐","一百岁"],["黄发、鲐背","高寿老人"]],"mem":"按年龄排队：襁褓（周岁内）→孩提（两三岁）→垂髫（幼童）→总角（八九岁以上）→豆蔻（十三四）。高龄记“耄耋期颐”：八十九十是耄耋，一百岁“期颐”，期是期待，颐是颐养天年。《桃花源记》“黄发垂髫”一句就把老人和小孩放在一起。","mix":"“豆蔻”专指女子十三四岁（杜牧“豆蔻梢头二月初”），“弱冠”才是男子二十；垂髫指小孩，不是老人；“耄”与“耋”的具体岁数古书说法略有出入，通行以八九十岁概括。","mcq":[{"q":"下列年龄称谓中，指百岁的是","o":["耄耋","古稀","花甲","期颐"],"a":3,"w":"期颐指百岁；耄耋八九十，古稀七十，花甲六十。"}],"rel":[{"t":"古代称谓","n":"称谓总类"},{"t":"冠礼与笄礼","n":"弱冠、及笄"},{"t":"三姑六婆","n":"称谓体系"},{"t":"姓氏与名、字、号","n":"同属称谓"}],"more":"弱冠20｜而立30｜不惑40｜知命50｜耳顺60｜花甲60｜古稀70｜耄耋80至90｜期颐100\n陶渊明《桃花源记》：黄发垂髫，并怡然自乐。\n杜牧《赠别》：娉娉袅袅十三余，豆蔻梢头二月初。","exam":[]},{"id":"a07-067","t":"谦辞与敬辞","cid":"07f","p":1,"kind":"常识","alias":["谦敬辞","敬辞","谦辞","令尊","令堂","家父","舍弟"],"one":"称对方亲属用“令”，称自家年长亲属用“家”、年幼用“舍”。","ans":"谦辞与敬辞是**汉语中表示谦逊自称与尊敬对方的固定用语**。称对方亲属用敬辞“**令**”：令尊（父）、令堂（母）、令郎（子）、令爱（女）。称自己亲属用谦辞：对年长者称“**家**”，如家父、家母、家兄；对年幼者称“**舍**”，如舍弟、舍妹、舍侄。其他敬辞有惠存、斧正、赐教，谦辞有拙作、寒舍、鄙人。使用时要分清对象，不能用敬辞称自己一方。","pts":["称对方亲属用“令”","称自家年长用“家”，年幼用“舍”","惠存、斧正；拙作、寒舍、鄙人"],"mem":"口诀：“令是对方，家舍是自己；家对长，舍对幼。”配例子：令尊令堂（别人父母）、家父家母（我的父母）、舍弟舍妹（我的弟妹）。","mix":"“惠存”用于请对方保存赠品，“斧正”用于请对方修改文章，两者都是敬辞；“拙作”“寒舍”是谦辞，不能用于对方；“令”不可用于自己的亲属。","mcq":[{"q":"称呼对方的母亲，应用","o":["家母","令堂","舍妹","先慈"],"a":1,"w":"令堂是对对方母亲的敬称；家母是对人称自己的母亲。"},{"q":"请别人修改自己的文章时，应说","o":["惠存","笑纳","垂询","斧正"],"a":3,"w":"“斧正”是请对方修改文章的敬辞；“惠存”用于请对方收存赠物。"}],"rel":[{"t":"书信敬语","n":"同类敬辞"},{"t":"亲属雅称","n":"称谓体系"},{"t":"古代称谓","n":"称谓常识"},{"t":"礼仪","n":"上位概念"}],"more":"令：令尊、令堂、令郎、令爱。\n家：家父、家母、家兄。\n舍：舍弟、舍妹、舍侄。\n敬辞：惠存、斧正、赐教、拜读。\n谦辞：拙作、寒舍、鄙人、愚见。","exam":[]},{"id":"a07-068","t":"五服","cid":"07f","p":1,"kind":"合称","alias":["五服之内","出了五服","斩衰","齐衰","大功","小功","缌麻"],"one":"斩衰、齐衰、大功、小功、缌麻五等丧服，按亲疏定服制与丧期。","ans":"五服是**中国古代按血缘亲疏确定的五等丧服制度**，由近到远依次为**斩衰、齐衰、大功、小功、缌麻**，丧服用料由粗到细，服丧期限由长到短：斩衰三年，齐衰一年为主，大功九个月，小功五个月，缌麻三个月。制度见于《仪礼·丧服》，体现宗法制度下的亲属远近。五服之内为近亲，所以“**出了五服**”指亲属关系已远，不必再为其服丧。","pts":["斩衰、齐衰、大功、小功、缌麻","按亲疏定丧服粗细与服丧时长","“出了五服”指关系疏远；见《仪礼·丧服》"],"members":[["斩衰","最重，三年，如子为父"],["齐衰","一年为主，另有三年、五月、三月"],["大功","九个月"],["小功","五个月"],["缌麻","最轻，三个月"]],"mem":"口诀“斩齐大小缌”，越往后越轻：布料越来越细，时间越来越短。时间递减口诀“三年、一年、九月、五月、三月”，数字对应五个名称。","mix":"“五服”与“五行”“五礼”只是数字相同；“九族”是另一个亲属范围概念；五服服制中“斩衰”最重，不是“缌麻”。","mcq":[{"q":"古代五服中最重的一等是","o":["斩衰","齐衰","大功","缌麻"],"a":0,"w":"斩衰服期三年，是五服中最重的一等。"},{"q":"“出了五服”一般指","o":["离开家乡","超过法定年龄","亲属关系已经疏远","不再有户籍"],"a":2,"w":"五服之外的亲属已无需服丧，关系较远。"}],"rel":[{"t":"九族","n":"亲属范围对照"},{"t":"三书六礼","n":"同属礼制，婚丧对举"},{"t":"礼仪","n":"上位概念"},{"t":"三礼","n":"《仪礼·丧服》出处"}],"more":"《仪礼·丧服》是五服制度的经典记载。","exam":[]},{"id":"a07-069","t":"九族","cid":"07f","p":3,"kind":"合称","alias":["诛九族","宗族九代"],"one":"中国古代宗法血亲体系中九代直系亲属及封建株连刑罚的合称。","ans":"九族是**中国古代宗法血亲体系与刑罚株连范围的合称**。古文经学指**己身起上至高祖下至玄孙的直系九代亲属**；今文经学指**父族四、母族三、妻族二**。统治者常以此施株连极刑，是**宗法伦理与专制皇权**结合的体现。","pts":["通说指高祖至玄孙的直系九代亲属","异说指父族四、母族三、妻族二","古代宗法血亲核心与封建株连极刑"],"members":[["高祖","自身之曾祖父之父，纵向九代之始"],["曾祖","自身之祖父之父"],["祖父","自身之父亲之父"],["父亲","自身之生父"],["己身","自身本人，九族之居中者"],["儿子","自身之生子"],["孙子","自身之儿子之子"],["曾孙","自身之孙子之子"],["玄孙","自身之曾孙之子，纵向九代之末"]],"mem":"九代纵向口诀：“**高曾祖父己，子孙曾玄全**”，己身居中，上下各四代。","mix":"九族两说：古文经主直系九代（高祖至玄孙），今文经主三族扩大（父四母三妻二）；明代方孝孺拒草即位诏，相传被朱棣诛灭“十族”（加朋友门生）。","mcq":[{"q":"中国古代宗法血亲体系中，‘九族’通行说法所指的纵向九代范围是","o":["从高祖到玄孙","从太祖到曾孙","从鼻祖到耳孙","从祖父到重孙"],"a":0,"w":"通说九族指高祖、曾祖、祖、父、己、子、孙、曾孙、玄孙直系九代。"}],"rel":[{"t":"宗法制","n":"九族所依托的血缘礼制"},{"t":"亲属雅称","n":"同属亲属称谓与宗法范畴"},{"t":"避讳","n":"尊祖敬宗礼制规范"}],"exam":[]},{"id":"a07-070","t":"姓氏与名、字、号","cid":"07f","p":2,"kind":"常识","alias":["名字号","姓名字号","名与字"],"one":"姓氏先秦有别，名为本名，字成年后取，号为自取别称。","ans":"姓、氏、名、字、号是**中国古人的称名系统**。先秦时**姓用来区别婚姻，氏用来区别贵贱**，秦汉以后姓氏合一。**名是本名，字在成年后取，与名意义相关**，如诸葛亮字孔明；**号是自取的别称**，如李白号青莲居士、苏轼号东坡居士。称呼上，自称用名表示谦逊，称人用字表示尊敬。这套称名习惯与冠礼取字相连，反映古代重视礼貌与宗法伦理的传统。","pts":["先秦姓别婚姻、氏别贵贱，秦汉后合一","名为本名，字成年后取，与名相关","号为自取，称人以字为敬"],"mem":"“名字号”三层：名（出生取，自称）→字（成年取，别人称）→号（自己起，写在书画上）。例子一套背下来：诸葛亮，字孔明；李白，字太白，号青莲居士；苏轼，字子瞻，号东坡居士。亮与明、轼与瞻都是意义相关，这就是“名字相应”。","mix":"谥号、庙号、年号不是名字号，是帝王、官员的另一类称号；“号”与“字”要分清，如“东坡”是号，“子瞻”才是字。","mcq":[{"q":"苏轼的字和号分别是","o":["字东坡，号子瞻","字太白，号东坡","字子瞻，号东坡居士","字子由，号东坡居士"],"a":2,"w":"苏轼字子瞻，号东坡居士；子由是苏辙的字。"}],"rel":[{"t":"冠礼与笄礼","n":"冠后取字"},{"t":"谥号与庙号","n":"帝王另类称号"},{"t":"古代称谓","n":"称谓总类"},{"t":"伯仲叔季","n":"兄弟排行"}],"more":"诸葛亮，字孔明｜李白，字太白，号青莲居士｜苏轼，字子瞻，号东坡居士｜陶渊明，字元亮，号五柳先生。\n《礼记·曲礼》：男子二十冠而字。","exam":[]},{"id":"a07-071","t":"谥号与庙号","cid":"07f","p":2,"kind":"制度","alias":["谥号","庙号","谥法"],"one":"谥号评其生平，庙号立室奉祀；唐以前多称谥号，唐宋多称庙号，明清多称年号。","ans":"谥号与庙号是**古代对帝王的两类死后称号**。**谥号**依据生平功过评定，有美谥（文、武）、恶谥（厉、炀）和平谥（哀、怀）之分，如汉文帝、隋炀帝；**庙号**是在太庙立室奉祀时所定，如太祖、太宗，多按功业高低、始创与中兴给出。通行的称呼习惯是：**唐以前多称谥号，唐以后多称庙号，明清多称年号**，如唐太宗、宋太祖、康熙帝。这套称号制度体现了古代礼制对帝王的褒贬与追崇。","pts":["谥号据生平评定，有美谥恶谥","庙号为太庙立室奉祀之号","唐前称谥号，唐后称庙号，明清称年号"],"mem":"口诀“前谥号，中庙号，后年号”：汉文帝、隋炀帝用谥号；唐太宗、宋太祖用庙号；万历帝、康熙帝用年号。美谥字多正面（文武成康），恶谥字多负面（厉炀幽灵）。","mix":"年号是帝王纪年的名号（如“贞观”），不是庙号也不是谥号；汉高祖刘邦的庙号实为“太祖”、谥号为“高”（“高祖”系《史记》习称沿用），“汉武帝”的“武”是谥号，汉代庙号极严，不可一概而论。","mcq":[{"q":"“隋炀帝”中的“炀”属于","o":["庙号","年号","谥号（恶谥）","字"],"a":2,"w":"炀是恶谥，表示去礼远众、好内远礼。"},{"q":"明清两代人们称呼皇帝，多用","o":["谥号","年号","庙号","字号"],"a":1,"w":"明清一帝一年号，习惯以年号称帝，如康熙、乾隆。"}],"rel":[{"t":"谥号","n":"单项词条"},{"t":"庙号","n":"单项词条"},{"t":"年号","n":"明清称帝依据"},{"t":"姓氏与名、字、号","n":"姓名称谓体系"}],"more":"谥号：文（美）、武（美）、厉（恶）、炀（恶）、哀（平）。\n庙号：太祖（开国）、太宗、世宗、高宗等。","exam":[]},{"id":"a07-073","t":"伯仲叔季","cid":"07f","p":2,"kind":"合称","alias":["孟仲叔季","伯仲叔季"],"one":"兄弟排行：老大伯（孟），老二仲，老三叔，最小季。","ans":"伯仲叔季是**古代表示兄弟姐妹排行的字眼**，依序为**伯（或孟）、仲、叔、季**，分别指老大、老二、老三、最小的。常用于人的字中，如孔子字仲尼（排行第二），孙策字伯符，孙权字仲谋。其中“伯”与“孟”均用于长子，按《白虎通》礼制“伯”常指嫡长，“孟”常指庶长。“伯仲”连用比喻不相上下，如“伯仲之间”。这一排行用字是宗法社会长幼有序的体现，在先秦人名中十分常见。","pts":["伯（孟）、仲、叔、季依次为老大到最小","孔子字仲尼，孙策字伯符","“伯仲之间”比喻不相上下"],"members":[["伯（孟）","老大"],["仲","老二"],["叔","老三"],["季","最小的"]],"mem":"谐音记“伯仲叔季”依次是“大二三小”。例子挂钩：孔子字仲尼，所以孔子是家里老二；孙策（伯符）、孙权（仲谋）是兄弟，哥哥带“伯”，弟弟带“仲”；“季”是最小的，所以“季”也作“四季之末”。","mix":"“叔”在今天指父亲的弟弟，但排行里是老三；“伯仲叔季”不是“伯仲季叔”，“季”总是最小的；“孟”与“伯”都可指老大，三兄弟时也可用“孟仲季”。","mcq":[{"q":"“伯仲叔季”中，表示兄弟中排行最小的是","o":["伯","仲","叔","季"],"a":3,"w":"季最小。"}],"rel":[{"t":"姓氏与名、字、号","n":"排行用于字"},{"t":"古代称谓","n":"称谓总类"},{"t":"三姑六婆","n":"同属称谓体系"},{"t":"冠礼与笄礼","n":"取字相关"}],"more":"孔子字仲尼｜孙策字伯符，孙权字仲谋｜曹操字孟德。\n伯仲之间：比喻不相上下。","exam":[]},{"id":"a07-074","t":"亲属雅称","cid":"07f","p":3,"kind":"常识","alias":["亲属称谓","传统亲属敬称"],"one":"中国传统礼仪与书面交际中敬称或雅称亲属关系的专有词汇。","ans":"亲属雅称是**中国传统宗法礼俗中对亲属关系的典雅敬称**。代表词汇包括：以**“椿萱”代指父母**，以**“泰山”称岳父**；以**“连襟”指姐妹之夫**，以**“妯娌”指兄弟之妇**。体现了**尊卑有序、亲疏有别**的传统伦理。","pts":["椿萱指父母，泰山岳丈指岳父","昆仲指兄弟，伉俪指夫妻","连襟为姐妹之夫互称，妯娌为兄弟之妇互称"],"mem":"雅称口诀：“**椿萱父母泰山岳，昆仲兄弟伉俪偶；连襟姐妹婿，妯娌兄弟妇**”。","mix":"“连襟”是姐妹的丈夫之间的称谓，“妯娌”是兄弟的妻子之间的称谓，切勿颠倒；泰山代指岳父源于唐玄宗封禅泰山张说提拔女婿的典故。","mcq":[{"q":"在传统亲属雅称中，姐妹的丈夫之间互相称为","o":["昆仲","连襟","妯娌","连理"],"a":1,"w":"姐妹的丈夫之间互称连襟，兄弟的妻子之间互称妯娌。"}],"rel":[{"t":"谦辞与敬辞","n":"同属传统社交礼仪词汇"},{"t":"姓氏与名、字、号","n":"同属传统人名称谓体系"},{"t":"三书六礼","n":"婚姻结亲礼俗基础"}],"exam":[]},{"id":"a07-075","t":"五礼","cid":"07f","p":2,"kind":"合称","alias":["吉凶军宾嘉"],"one":"吉礼、凶礼、军礼、宾礼、嘉礼，《周礼》所载五类礼仪。","ans":"五礼是**《周礼》将古代礼仪分成的五大类**，即**吉礼、凶礼、军礼、宾礼、嘉礼**。吉礼指祭祀天地鬼神；凶礼指丧葬与救灾吊唁；军礼指军队征伐、田猎、阅兵；宾礼指诸侯朝觐、会盟及外交往来；嘉礼指冠礼、婚礼、飨燕等喜庆礼仪。五礼涵盖国家政治与社会生活，是“三礼”之一《周礼》的核心内容，后世历代编修礼典多以五礼为框架，如唐代《开元礼》、明代《大明集礼》。","pts":["吉、凶、军、宾、嘉五类","吉祭祀、凶丧葬、军征伐、宾朝聘、嘉冠婚","《周礼》所载，后世礼典以此为框架"],"members":[["吉礼","祭祀天地、祖先、神灵"],["凶礼","丧葬、荒灾、吊唁"],["军礼","出征、田猎、阅兵"],["宾礼","诸侯朝觐、会盟、外交"],["嘉礼","冠礼、婚礼、飨燕等喜庆"]],"mem":"口诀就是五个字“吉凶军宾嘉”。配画面：祭祀（吉）、办丧事（凶）、出兵（军）、接待客人（宾）、办喜事（嘉）。冠礼和婚礼都在“嘉”里，所以冠笄之礼属嘉礼。","mix":"“五礼”与“五服”“五经”“五伦”都带“五”：五服管丧服，五礼管礼仪分类，不要混；“三礼”是《周礼》《仪礼》《礼记》三部书，五礼是礼的分类。","mcq":[{"q":"《周礼》五礼中，包括冠礼和婚礼的是","o":["嘉礼","吉礼","宾礼","凶礼"],"a":0,"w":"冠婚飨燕属嘉礼。"},{"q":"下列不属于五礼的是","o":["吉礼","军礼","宾礼","乐礼"],"a":3,"w":"五礼为吉、凶、军、宾、嘉，没有乐礼。"}],"rel":[{"t":"三礼","n":"《周礼》为三礼之一"},{"t":"冠礼与笄礼","n":"属嘉礼"},{"t":"五服","n":"凶礼中的丧服"},{"t":"三书六礼","n":"婚礼属嘉礼"}],"more":"《周礼·春官·大宗伯》载五礼的名目与职掌。","exam":[]},{"id":"a07-076","t":"三教九流","cid":"07f","p":2,"kind":"合称","alias":["九流三教"],"one":"三教指儒释道；九流指《汉书·艺文志》诸子九家，后泛指各行各业。","ans":"三教九流**原指宗教与学术流派，后泛指社会各行各业的人**。**三教是儒教、佛教、道教**。**九流**出自《汉书·艺文志》对诸子的分类，包括**儒、道、阴阳、法、名、墨、纵横、杂、农九家**，加上小说家为“十家”，但小说家不入流。后来民间又有“上九流”“下九流”的说法，把职业分为高低等级。三教九流一词反映古人对思想与职业的分类，常带有复杂人群的含义。","pts":["三教：儒、释、道","九流：儒道阴阳法名墨纵横杂农","后泛指社会各行各业"],"members":[["儒家","孔子、孟子、荀子"],["道家","老子、庄子"],["阴阳家","邹衍"],["法家","韩非、商鞅"],["名家","惠施、公孙龙"],["墨家","墨子"],["纵横家","苏秦、张仪"],["杂家","《吕氏春秋》"],["农家","许行"]],"mem":"九流首字串联：儒道阴阳，法名墨纵，杂农。三教就记“儒释道”。《汉书·艺文志》共十家，比九流多一个“小说家”，所以口诀是“十家去小说，剩下九流”。","mix":"“九流十家”中的第十家是小说家，不在九流之内；《汉书·艺文志》分类依据的是西汉刘歆《七略》，“三教九流”与“三姑六婆”都是泛称人群，但前者重学术职业，后者指女性职业。","mcq":[{"q":"“九流”的出处是","o":["《史记·太史公自序》","《汉书·艺文志》","《论语》","《庄子·天下》"],"a":1,"w":"班固《汉书·艺文志》列诸子十家，去小说家为九流。"}],"rel":[{"t":"九流十家","n":"十家比九流多小说家"},{"t":"诸子百家","n":"九流的来源"},{"t":"三教合一","n":"儒释道关系"},{"t":"三姑六婆","n":"同类社会称谓"}],"more":"“上九流”“下九流”是民间对职业的等级划分，说法不一。","exam":[]},{"id":"a07-077","t":"七出与三不去","cid":"07f","p":3,"kind":"合称","alias":["七出三不去","七去三不去"],"one":"中国古代礼制与律法中男子休妻的七种条件及三种保护限制的合称。","ans":"七出与三不去是**中国古代封建礼法规定的休妻条件与限制准则**。“七出”为**不顺父母、无子、淫、妒、有恶疾、多言、窃盗**七项休妻理由；“三不去”为**无所归、三年丧、后富贵**三种保护情形。兼顾了**夫权统治与家庭稳定**。","pts":["古代男子休妻的法定七出理由","保护妻子的三不去限制情形","兼顾夫权至上与宗族伦理稳定"],"members":[["不顺父母","七出之一，违背孝道，不顺从公婆"],["无子","七出之一，绝后无嗣，断绝宗族香火"],["淫","七出之一，行为不贞，紊乱宗族血统"],["妒","七出之一，嫉妒妾室，扰乱家庭和睦"],["有恶疾","七出之一，患重大传染或严重残疾之疾，不可共承宗庙祭祀"],["多言","七出之一，口舌是非，离间亲族骨肉"],["窃盗","七出之一，不告而取，违背道义礼法"],["有所受而无所归不去","三不去之一，出嫁时有娘家可归，休弃时娘家已无亲人可依"],["与更三年丧不去","三不去之一，曾与丈夫一同为公婆守满三年之丧"],["前贫贱后富贵不去","三不去之一，结婚时家境贫贱，后发家致富不可弃糟糠之妻"]],"mem":"口诀：“**不顺无子淫妒疾，多言窃盗七出例；无所归、三年丧、后富贵，三不去护糟糠**”。","mix":"即使妻子符合“七出”，只要满足“三不去”之一，丈夫便不可任意休弃（但犯淫、恶疾等极特殊情形除外）；“前贫贱后富贵”体现了“糟糠之妻不下堂”。","mcq":[{"q":"下列不属于中国古代婚姻制度中丈夫不得休妻的‘三不去’情形的是","o":["有所受而无所归","与更三年丧","生有嫡长子","前贫贱后富贵"],"a":2,"w":"三不去为：有所受而无所归、与更三年丧、前贫贱后富贵；生嫡长子不属三不去法定条款。"}],"rel":[{"t":"三书六礼","n":"古代明媒正娶之礼"},{"t":"宗法制","n":"休妻制度背后的宗法原则"},{"t":"发妻","n":"正妻身份与三不去保护"}],"exam":[]},{"id":"a07-078","t":"丁忧","cid":"07f","p":3,"kind":"制度","alias":["守制","夺情","匿丧"],"one":"古代官员父母去世后须解职离任回乡守丧二十七个月的宗法丧服制度。","ans":"丁忧是**中国古代官员父母去世后解职守丧的礼制规定**，又称“守制”。**守丧期按礼制为二十七个月**。隐瞒丧讯称“匿丧”，按律治罪；若因国家军政急需由皇帝特旨留任，则称**“夺情”**。深刻体现了古代以**孝治天下**的纲常原则。","pts":["官员父母去世须解职守丧二十七个月","源于儒家孝道，匿丧不报按律治重罪","国家军政特殊需要特旨留任称夺情"],"mem":"联想：“**父母大丧解任丁忧，特旨起复名为夺情**”，丁为遭逢，忧为亲丧。","mix":"丁忧俗称“守孝三年”，礼制实际执行期为二十七个月；朝廷强令不回籍守丧称“夺情”，官员隐瞒死讯图谋留任称“匿丧”，性质截然不同。","mcq":[{"q":"中国古代官员在遭逢父母去世守丧期间，因军政急需经皇帝特旨不离职守丧的做法称为","o":["守制","辟召","匿丧","夺情"],"a":3,"w":"官员在遭逢父母丧事时被皇帝特旨挽留或提前起复任职称为夺情。"}],"rel":[{"t":"张居正改革","n":"张居正因夺情事件引发政争"},{"t":"冠礼与笄礼","n":"同属传统礼制人生节点"},{"t":"三书六礼","n":"同受孝治宗法制度约束"}],"exam":[]},{"id":"a07-079","t":"书信敬语","cid":"07f","p":3,"kind":"常识","alias":["书简敬语","尺牍敬语","提称语"],"one":"中国传统尺牍书信中依据收信人长幼尊卑所用的规范化礼貌词语。","ans":"书信敬语是**中国传统尺牍书信中表达敬意的程式化用语**。包括提称语与末尾敬语：对长辈用**“尊鉴”“钧鉴”**；对平辈用**“台鉴”“大鉴”**；对晚辈用**“青鉴”“如晤”**；文末配以**“顿首”**等。严格体现**长幼尊卑与礼貌修养**。","pts":["书信提称语因长幼尊卑而异","长辈用钧鉴尊鉴，平辈用台鉴惠鉴，晚辈用青鉴","篇末配以顿首、再拜等敬辞"],"mem":"提称口诀：“**长辈钧鉴尊鉴，平辈台鉴惠鉴，晚辈青鉴如晤**”，钧重如山敬长辈。","mix":"“钧鉴”专用于长辈或极受尊崇的长官，平辈绝不可用；晚辈用“青鉴”或“如晤”（如林觉民《与妻书》“意映卿卿如晤”）。","mcq":[{"q":"传统书信中，写给平辈朋友的信件提称语最适宜选用的是","o":["台鉴","钧鉴","尊鉴","青鉴"],"a":0,"w":"台鉴、惠鉴、大鉴用于平辈；钧鉴、尊鉴用于长辈；青鉴用于晚辈。"}],"rel":[{"t":"谦辞与敬辞","n":"同属传统交往礼貌用语规范"},{"t":"亲属雅称","n":"同属人际称谓与礼仪系统"},{"t":"姓氏与名、字、号","n":"书信署名与称呼规矩"}],"exam":[]},{"id":"a07-080","t":"造纸术","cid":"07g","p":2,"kind":"常识","alias":["蔡伦造纸","蔡侯纸","灞桥纸"],"one":"四大发明之一，西汉已有麻纸，东汉蔡伦改进。","ans":"造纸术是**中国古代四大发明之一**。**西汉已有以麻为原料的纸（如灞桥纸）**，但质地粗糙。**东汉蔡伦总结前人经验加以改进**，用树皮、麻头、破布、旧渔网等为原料造纸，元兴元年（105年）奏报朝廷，世称**“蔡侯纸”**。改进后的纸成本低、易书写，逐渐取代竹简和缣帛。造纸术在唐代传入中亚阿拉伯地区，后又传入欧洲，推动了世界文化的传播与保存。","pts":["西汉已有麻纸，如灞桥纸","东汉蔡伦改进，105年奏报，称蔡侯纸","经阿拉伯传入欧洲"],"mem":"“蔡伦造纸”不是从零发明，是“改进+推广”。记两个年份：西汉灞桥纸（1957年西安出土），东汉105年蔡伦。原料口诀“树麻布网”：树皮、麻头、破布、旧渔网。","mix":"蔡伦并非纸的最早发明者，考古发现早于东汉的西汉纸；常被混为“蔡伦发明印刷”或“毕昇造纸”。","mcq":[{"q":"关于造纸术，下列说法正确的是","o":["蔡伦改进造纸术，所造纸称“蔡侯纸”","毕昇发明造纸术","灞桥纸出土于东汉墓","蔡伦是唐代人"],"a":0,"w":"蔡伦东汉人，105年奏报改进的造纸术。"},{"q":"下列属于蔡伦造纸原料的是","o":["竹简","丝绸","树皮、麻头、破布、旧渔网","石灰"],"a":2,"w":"蔡伦用树皮、麻头、破布、旧渔网等造纸。"}],"rel":[{"t":"四大发明","n":"成员之一"},{"t":"印刷术","n":"同为四大发明"},{"t":"指南针","n":"同为四大发明"},{"t":"火药","n":"同为四大发明"}],"more":"1957年西安灞桥出土西汉麻纸，称“灞桥纸”。\n唐代天宝十年（751年）怛罗斯之战后，造纸术传入阿拉伯世界（通行说法）。","exam":[]},{"id":"a07-081","t":"印刷术","cid":"07g","p":2,"kind":"常识","alias":["雕版印刷","活字印刷","毕昇","泥活字"],"one":"唐代雕版印刷，北宋毕昇发明泥活字，元代王祯创木活字。","ans":"印刷术是**中国古代四大发明之一**，经历了雕版到活字的发展。**唐代已有雕版印刷**，咸通九年（868年）刻印的《金刚经》是现存最早有明确纪年的雕版印刷品。**北宋庆历年间毕昇发明泥活字印刷**，记载于沈括《梦溪笔谈》，使印刷可以反复拼版。**元代王祯创制木活字**并发明转轮排字架。印刷术大大降低了书籍成本，促进知识传播，后来传到朝鲜、日本、阿拉伯及欧洲，对世界文明产生了深远影响。","pts":["唐代雕版，868年《金刚经》","北宋毕昇泥活字，载《梦溪笔谈》","元代王祯木活字"],"mem":"时间线顺口溜“唐雕宋泥元木”：唐朝雕版，宋朝泥活字，元朝木活字。人物对应：毕昇—泥—梦溪笔谈；王祯—木—转轮排字架。数字：868年《金刚经》，敦煌藏经洞出土，现藏大英图书馆。","mix":"毕昇发明的是泥活字，不是木活字，王祯才创木活字；欧洲古腾堡15世纪发明的是金属活字印刷，晚于中国。","mcq":[{"q":"记载毕昇发明活字印刷的著作是","o":["《天工开物》","《梦溪笔谈》","《齐民要术》","《本草纲目》"],"a":1,"w":"沈括《梦溪笔谈》记载毕昇泥活字。"}],"rel":[{"t":"四大发明","n":"成员之一"},{"t":"《梦溪笔谈》","n":"毕昇活字记载"},{"t":"造纸术","n":"同为四大发明"},{"t":"敦煌藏经洞","n":"868年《金刚经》出土"}],"more":"868年（咸通九年）《金刚经》：现存最早有明确纪年的雕版印刷品，出自敦煌藏经洞。","exam":[]},{"id":"a07-082","t":"火药","cid":"07g","p":3,"kind":"常识","alias":["黑火药","中国四大发明之一"],"one":"中国古代炼丹家发明、宋代广泛用于军事的中国古代四大发明之一。","ans":"火药是**中国古代“四大发明”之一**，源于**唐代道家炼丹术的实践探索**。由**硝石、硫磺、木炭**按比例配制而成。北宋**《武经总要》最早记载了军用火药配方**。宋元时期火药西传，促成了**欧洲火器革命与封建城堡解体**，对世界历史产生巨大推动作用。","pts":["中国古代四大发明之一，源于唐代炼丹术","由硝石、硫磺、木炭三种成分配制","北宋《武经总要》最早记录军用火药配方"],"mem":"配方口诀：“**一硝二磺三木炭**，唐代炼丹宋用兵”，《武经总要》记配方。","mix":"火药由中国炼丹家首创，北宋《武经总要》载有最早火药配方；火药外传推动了欧洲中世纪封建骑士阶层的崩溃。","mcq":[{"q":"中国历史上最早记载军用火药配方的典籍是北宋官修的","o":["《天工开物》","《武经总要》","《梦溪笔谈》","《齐民要术》"],"a":1,"w":"北宋曾公亮等编纂的《武经总要》最早记载了火炮火药、蒺藜火球等火药配方。"}],"rel":[{"t":"四大发明","n":"四大发明核心成员"},{"t":"造纸术","n":"四大发明并列项"},{"t":"指南针","n":"四大发明并列项"},{"t":"炼丹术与火药","n":"火药发明源头"}],"exam":[]},{"id":"a07-083","t":"新四大发明","cid":"07g","p":3,"kind":"合称","alias":["中国新四大发明"],"one":"2017年“一带一路”沿线青年评选出的高铁、扫码支付、共享单车与网购。","ans":"新四大发明是**2017年“一带一路”沿线青年评选出的中国创新生活方式**，包括**高铁、扫码支付、共享单车和网购**。四项成果依托中国**完善的基础设施与数字应用生态**做到了全球领先，成为**当代中国科技创新与高品质生活方式**的亮丽国际名片。","pts":["2017年“一带一路”沿线青年评选提出","由高铁、扫码支付、共享单车、网购组成","展现当代中国数字经济与基础设施创新"],"members":[["高铁","中国高速铁路，运营里程全球第一，重塑现代交通出行时空格局"],["扫码支付","以移动互联和二维码为核心的移动支付，构建便捷高效的无现金生活模式"],["共享单车","以手机应用分时租赁为特征的共享自行车，绿色环保解决出行最后一公里"],["网购","以网络电子商务平台为基础的在线购物，重构现代消费生活与物流体系"]],"mem":"缩写口诀：“**高支共网**”（高铁、支付、共享单车、网购），现代出行与数字生活标配。","mix":"“新四大发明”并非古代科技原生发明，而是中国在基础设施、数字经济与商业应用上的集成创新；发起评选主体是2017年“一带一路”沿线国家留学生。","mcq":[{"q":"2017年‘一带一路’沿线青年评选出的中国‘新四大发明’不包括","o":["高速铁路","扫码支付","无人机配送","共享单车"],"a":2,"w":"新四大发明为：高铁、扫码支付、共享单车、网购；无人机配送不属于其中。"}],"rel":[{"t":"四大发明","n":"古今科技发明对举"},{"t":"一带一路","n":"新四大发明评选提出背景"},{"t":"“一带一路”五通","n":"基础设施互联互通"}],"exam":[]},{"id":"a07-084","t":"《九章算术》","cid":"07g","p":2,"kind":"作品","alias":["九章算术","刘徽注"],"one":"汉代数学经典，系统记载负数与方程解法，刘徽作注并提出割圆术。","ans":"《九章算术》是**中国古代的数学经典**，成书于东汉，是《算经十书》中最重要的一部。全书共九章，收录二百多个应用问题，**最早系统记载了负数和方程（线性方程组）的解法**，也包括分数运算、勾股定理等内容。**魏晋时期刘徽为其作注**，提出**“割圆术”**，用圆内接正多边形逼近圆周率，得出π约为3.1416。《九章算术》以实用算法为特点，奠定了中国古代数学的体系，对东亚数学发展影响深远。","pts":["东汉成书，中国古代数学经典","最早系统记载负数、方程解法","刘徽作注，提出割圆术"],"mem":"口诀“九章算术东汉成，负数方程它最早”。“刘徽割圆”可以想成切蛋糕：把圆切成越来越多的小三角形，边数越多越接近圆。数轴挂钩：刘徽（魏晋，割圆3.1416）→祖冲之（南朝，3.1415926）。","mix":"《九章算术》成书年代学界有西汉至东汉初说法，通行说汉代成书，常归东汉；割圆术的提出者是刘徽，不是祖冲之，祖冲之是在此基础上把圆周率推到小数点后七位。","mcq":[{"q":"提出“割圆术”并为《九章算术》作注的是","o":["祖冲之","张衡","刘徽","沈括"],"a":2,"w":"刘徽，魏晋时期数学家。"}],"rel":[{"t":"祖冲之","n":"圆周率后继者"},{"t":"《梦溪笔谈》","n":"科技典籍顺序"},{"t":"《齐民要术》","n":"科技典籍顺序"},{"t":"李约瑟与《中国科学技术史》","n":"评价中国科技"}],"more":"《九章算术》九章：方田、粟米、衰分、少广、商功、均输、盈不足、方程、勾股。","exam":[]},{"id":"a07-085","t":"祖冲之","cid":"07g","p":2,"kind":"人物","alias":["祖冲之","祖文远","密率"],"one":"南朝数学家，圆周率精确到小数点后七位，制定《大明历》。","ans":"祖冲之（429—500）是**南朝（宋、齐）时期的数学家、天文学家**，字文远，范阳遒（今河北涞水）人。他的**突出贡献是推算出圆周率在3.1415926和3.1415927之间**，精确到小数点后七位，并提出**约率22/7、密率355/113**，这一成果领先世界近千年。他还制定了**《大明历》**，首次引入岁差。著有《缀术》，已失传。月球背面的一座环形山以他命名，以纪念他的成就。","pts":["南朝数学家，字文远","圆周率在3.1415926与3.1415927之间","约率22/7，密率355/113；《大明历》"],"mem":"数字口诀：“3.1415926 与 3.1415927 夹出π”，密率355/113：把“113355”拆成两半，前半113是分母，后半355是分子。朝代线：刘徽（魏晋）割圆→祖冲之（南朝）七位。","mix":"约率22/7更粗略，是早就有的近似；密率355/113才是祖冲之的创造；割圆术属刘徽。《缀术》已失传，不是现存著作。","mcq":[{"q":"祖冲之把圆周率推算到小数点后第几位","o":["七位","五位","三位","九位"],"a":0,"w":"在3.1415926与3.1415927之间，精确到小数点后七位。"},{"q":"祖冲之提出的圆周率密率是","o":["22/7","355/113","3.14","3.1416"],"a":1,"w":"约率22/7，密率355/113。"}],"rel":[{"t":"《九章算术》","n":"刘徽注割圆术在先"},{"t":"李约瑟与《中国科学技术史》","n":"中国古代科技成就"},{"t":"四大发明","n":"古代科技并提"},{"t":"《梦溪笔谈》","n":"科技名家并提"}],"more":"《大明历》：462年制定，首次引入岁差，510年（梁天监九年）施行。\n月球环形山“祖冲之”以其命名。","exam":[]},{"id":"a07-086","t":"《周髀算经》","cid":"07g","p":3,"kind":"作品","alias":["周髀"],"one":"中国现存最早的天文算学经典，最早记载勾股定理与“盖天说”宇宙理论。","ans":"《周髀算经》是**中国现存最早的天文算学经典著作**，成书于西汉。该书系统阐发了古代天文学的**“盖天说”理论**（天圆地方）；并在数学上最早记录了商高**“勾三股四弦五”勾股定理**。位列唐代**“算经十书”之首**，奠定数理天文基石。","pts":["中国现存最早的天文数学著作，算经十书之首","阐发天圆地方的盖天说宇宙论","最早记录商高勾股定理“勾三股四弦五”"],"mem":"口诀：“**算经之首周髀记，盖天宏论勾股明**”，商高答周公勾三股四弦五。","mix":"《周髀算经》是中国现存最早的天文数学书（主盖天说与勾股定理）；而《九章算术》标志中国古代数学完整体系的建立，二者不要混淆。","mcq":[{"q":"中国现存最早记录勾股定理‘勾三股四弦五’的天文数学著作是","o":["《九章算术》","《齐民要术》","《梦溪笔谈》","《周髀算经》"],"a":3,"w":"《周髀算经》最早记载了商高提出的勾三股四弦五勾股定理特例。"}],"rel":[{"t":"《九章算术》","n":"古代数学经典双璧"},{"t":"珠算","n":"同属传统数学科技史脉络"},{"t":"张衡","n":"盖天说与浑天说对举"}],"exam":[]},{"id":"a07-087","t":"中国古代四大农书","cid":"07g","p":3,"kind":"合称","alias":["古代四大农书","四大农书"],"one":"中国历史上四部代表性农学经典巨著的合称。","ans":"中国古代四大农书指**中国古代农学成就极高的四部代表性农学巨著**。包括**西汉氾胜之《氾胜之书》**、**北魏贾思勰《齐民要术》**、**元代王祯《王祯农书》**与**明代徐光启《农政全书》**。四部著作系统总结了精耕细作经验，展现了古代**农业科技文明的高峰**。","pts":["西汉《氾胜之书》为最早农学专著","北魏贾思勰《齐民要术》为现存最早完整农书","元王祯《农书》载图谱，明徐光启《农政全书》集大成"],"members":[["《氾胜之书》","西汉氾胜之撰，中国最早农学专著，总结关中精耕细作区田法与溲种法"],["《齐民要术》","北魏贾思勰撰，中国现存最早最完整大型综合农书，总结北方农林牧副渔"],["《王祯农书》","元代王祯撰，兼论南北农业技术，附大量精美图谱《农器图谱》"],["《农政全书》","明代徐光启撰，集传统农业技术之大成，吸收西方水利科技"]],"mem":"朝代串联口诀：“**汉氾北齐元王明徐**”（氾胜之、齐民要术、王祯、徐光启），四大农书。","mix":"《氾胜之书》最早但已佚失（仅存辑本）；《齐民要术》是“现存最早完整”的农书；明代宋应星《天工开物》是手工业综合科技巨著，不属于四大农书。","mcq":[{"q":"下列农学与科技著作中，不属于‘中国古代四大农书’的是","o":["《天工开物》","《氾胜之书》","《齐民要术》","《王祯农书》"],"a":0,"w":"四大农书为《氾胜之书》《齐民要术》《王祯农书》《农政全书》；《天工开物》为手工业技术著作。"}],"rel":[{"t":"《齐民要术》","n":"四大农书核心现存最早者"},{"t":"《天工开物》","n":"古代综合科技名著对照"},{"t":"重农抑商","n":"农书编纂的社会经济思想背景"}],"exam":[]},{"id":"a07-089","t":"《徐霞客游记》","cid":"07g","p":3,"kind":"作品","alias":["徐霞客游记"],"one":"明代徐霞客所撰、系统考察喀斯特地貌的地理学与文学名著。","ans":"《徐霞客游记》是**明代地理学家徐霞客实地考察三十余年撰写的地理学巨著**。该书在世界上最早系统记录了**喀斯特地貌**发育规律，并考定金沙江为长江源。全书融**科学考察与游记文学**于一体。开篇日5月19日被定为**“中国旅游日”**。","pts":["明代徐霞客实地考察三十余年的地理名著","世界最早系统考察喀斯特地貌，考证长江源","开篇日5月19日被确立为“中国旅游日”"],"mem":"口诀：“**霞客穷行千万里，五一九开旅游日**”，喀斯特地貌考察第一人。","mix":"徐霞客考证金沙江为长江正源（纠正《尚书·禹贡》“岷山导江”之误）；开篇《游天台山日记》日期5月19日被国家定为中国旅游日。","mcq":[{"q":"我国将每年5月19日确立为‘中国旅游日’，源于哪部古代名著的开篇日期","o":["《水经注》","《徐霞客游记》","《大唐西域记》","《梦溪笔谈》"],"a":1,"w":"《徐霞客游记》开篇《游天台山日记》始于公元1613年5月19日。"}],"rel":[{"t":"《水经注》","n":"同属古代地理学名著"},{"t":"郦道元","n":"古代地理学家对举"},{"t":"《天工开物》","n":"同属明末实学科技名著"}],"exam":[]},{"id":"a07-091","t":"李约瑟与《中国科学技术史》","cid":"07g","p":2,"kind":"人物","alias":["李约瑟","李约瑟难题","Joseph Needham","李约瑟问题"],"one":"英国学者，著《中国科学技术史》，提出“李约瑟难题”。","ans":"李约瑟（Joseph Needham，1900—1995）是**英国生物化学家、科学史学家**，长期研究中国科技史。他主持编写**《中国科学技术史》**（又译《中国的科学与文明》），自1954年起陆续出版，系统论述中国古代科技成就。他提出的**“李约瑟难题”**是：**为什么近代科学没有在中国产生，尽管中国古代科技长期领先于世界**。这一问题引发中外学界长期讨论，涉及制度、文化、经济等多个层面，也推动了世界对中国科技史的重视。","pts":["英国科学史学家，1900—1995","主编《中国科学技术史》，1954年起出版","李约瑟难题：近代科学为何未在中国产生"],"mem":"“李约瑟之问”记成一个转折句：中国古代科技那么发达，为什么近代科学没在中国产生？和“钱学森之问”对比：李约瑟问的是科学，钱学森问的是教育（为什么培养不出杰出人才）。","mix":"李约瑟难题常被说成“中国为什么落后”，更准确是“近代科学为什么没在中国出现”；与“钱学森之问”不是同一问题，后者问教育。","mcq":[{"q":"提出“近代科学为什么没有在中国产生”这一问题的学者是","o":["钱学森","李约瑟","杨振宁","费正清"],"a":1,"w":"这是“李约瑟难题”，李约瑟是英国学者。"}],"rel":[{"t":"四大发明","n":"中国古代科技成就"},{"t":"祖冲之","n":"古代科技人物"},{"t":"《九章算术》","n":"古代科技典籍"},{"t":"《天工开物》","n":"古代科技典籍"}],"more":"《中国科学技术史》（Science and Civilisation in China）：1954年起出版，多卷本，后由多位学者续编。","exam":[]},{"id":"a07-092","t":"秦代三大水利工程","cid":"07g","p":2,"kind":"合称","alias":["三大水利工程"],"one":"都江堰、郑国渠、灵渠。","ans":"秦代三大水利工程是**都江堰、郑国渠、灵渠**。**都江堰**由蜀郡守李冰主持修建于岷江，使成都平原“水旱从人，不知饥馑”，2000年作为青城山—都江堰列入世界遗产。**郑国渠**由韩国水工郑国主持，引泾水入洛水，灌溉关中平原，增强了秦国国力。**灵渠**由史禄主持开凿，沟通湘江与漓江，连接长江与珠江水系，便利了秦军南下统一岭南。这三项工程体现了秦代的水利技术和对国家统一的推动作用。","pts":["都江堰（李冰，岷江）","郑国渠（关中，引泾入洛）","灵渠（沟通湘江漓江，连接长江珠江水系）"],"members":[["都江堰","李冰主持，四川岷江，成都平原"],["郑国渠","郑国主持，陕西关中，引泾水入洛水"],["灵渠","史禄主持，广西，沟通湘江与漓江"]],"mem":"“都郑灵”，按地理从西到东、南：四川（都江堰）→陕西（郑国渠）→广西（灵渠）。人物配对：李冰—都江堰，郑国—郑国渠（名字就在渠名里），灵渠是沟通两大水系的“南北桥”。","mix":"都江堰在战国末年秦昭襄王时修建，是秦国而非秦朝，常归入“秦代”；京杭大运河、坎儿井不属于秦代三大工程。","mcq":[{"q":"沟通湘江与漓江、连接长江和珠江水系的水利工程是","o":["灵渠","都江堰","郑国渠","京杭大运河"],"a":0,"w":"灵渠位于今广西兴安，秦代开凿。"},{"q":"主持修建都江堰的是","o":["郑国","李冰","史禄","大禹"],"a":1,"w":"蜀郡守李冰主持修建。"}],"rel":[{"t":"青城山—都江堰","n":"世界遗产"},{"t":"世界遗产类型","n":"遗产保护体系"},{"t":"四大发明","n":"古代科技并提"},{"t":"李约瑟与《中国科学技术史》","n":"科技史评价"}],"more":"都江堰：约前256年，战国秦昭襄王时。郑国渠：前246年。灵渠：前214年。","exam":[]},{"id":"a07-093","t":"《黄帝内经》","cid":"07g","p":1,"kind":"作品","alias":["黄帝内经","内经","《素问》","《灵枢》"],"one":"现存最早的中医理论经典，分《素问》《灵枢》，奠定阴阳五行与脏腑经络学说。","ans":"《黄帝内经》是**现存最早的中医理论经典**，托名黄帝，实为战国至秦汉间众多医家陆续编成。全书分**《素问》《灵枢》两部分**，各81篇。书中以**阴阳五行学说、脏腑经络学说**为基础，论述人体生理、病因、诊断和养生，提出“治未病”的预防思想。它**奠定了中医的理论体系**，后世医家多奉为宗，2011年与《本草纲目》一同列入**世界记忆名录**。","pts":["现存最早中医理论经典，托名黄帝","《素问》《灵枢》；阴阳五行、脏腑经络","奠定中医理论，2011年入世界记忆名录"],"mem":"“内经”像医学的“宪法”：《素问》问理论（黄帝和岐伯一问一答），《灵枢》讲针灸经络（灵枢，“灵”配针）。托名黄帝，所以叫“黄帝”内经，实际是集体之作。中医“四大经典”常把它排第一。","mix":"《神农本草经》是现存最早的药学专著，《伤寒杂病论》是张仲景的临床辨证著作，《本草纲目》是明代李时珍的药学巨著，不要把“最早的理论经典”选成这些。","mcq":[{"q":"现存最早的中医理论经典是","o":["《伤寒杂病论》","《神农本草经》","《本草纲目》","《黄帝内经》"],"a":3,"w":"《黄帝内经》奠定中医理论基础；《神农本草经》是最早的药学专著。"},{"q":"《黄帝内经》的两个组成部分是","o":["《难经》《脉经》","《素问》《灵枢》","《伤寒论》《金匮要略》","《本草》《方剂》"],"a":1,"w":"《黄帝内经》包括《素问》和《灵枢》。"}],"rel":[{"t":"中医四大经典","n":"内经居首"},{"t":"《神农本草经》","n":"最早药学专著"},{"t":"五行","n":"理论基础"},{"t":"《本草纲目》","n":"同年入选世界记忆名录"},{"t":"中医针灸","n":"《灵枢》论针灸"}],"more":"素问、灵枢各81篇。\n不治已病治未病。｜《素问·四气调神大论》","exam":[]},{"id":"a07-094","t":"中医四大经典","cid":"07g","p":3,"kind":"合称","alias":["中医学四大经典"],"one":"奠定中医药学基础理论、临床辨证与中药学体系的四部经典医籍合称。","ans":"中医四大经典指**奠定中医学理论与临床辨证体系的四部基石典籍**。通行包括**《黄帝内经》**（理论框架）、**《难经》**（脉法释疑）、**《伤寒杂病论》**（张仲景著，辨证论治）与**《神农本草经》**（药物学专著）。另一说以清代**《温病条辨》**替换《难经》。","pts":["通行四经典：内经、难经、伤寒论、本草经","分别奠定基础理论、脉学、辨证论治与药物学","另一说将《难经》替换为清代《温病条辨》"],"members":[["《黄帝内经》","战国至秦汉成书，奠定中医基础理论与藏象经络学说基石，尊为“医家之祖”"],["《难经》","相传战国扁鹊所撰，以问答释难形式阐发脉学、经络与脏腑理论"],["《伤寒杂病论》","东汉张仲景著，确立辨证论治法则与六经辨证体系，尊为“方书之祖”"],["《神农本草经》","东汉时期成书，总结药物上中下三品分类与四气五味，为现存最早中药学专著"]],"mem":"四经典口诀：“**内经难经伤寒本草**”，内生理、难释疑、伤寒临证、本草识药。","mix":"中医四大经典通行说法为《内经》《难经》《伤寒论》《本草经》；另一说为《内经》《伤寒论》《金匮要略》《温病条辨》；《本草纲目》为明代药物巨著，不属于四大经典。","mcq":[{"q":"下列著作中，不属于中医学通行‘四大经典’的是","o":["《黄帝内经》","《难经》","《本草纲目》","《神农本草经》"],"a":2,"w":"四大经典为《黄帝内经》《难经》《伤寒杂病论》《神农本草经》；《本草纲目》为明代李时珍所作。"}],"rel":[{"t":"《黄帝内经》","n":"四大经典理论基石"},{"t":"张仲景与《伤寒杂病论》","n":"四大经典临床基石"},{"t":"《神农本草经》","n":"四大经典本草基石"},{"t":"《本草纲目》","n":"明代本草集大成者"}],"exam":[]},{"id":"a07-095","t":"古代名医","cid":"07g","p":2,"kind":"合称","alias":["中医五位名医","古代五大名医"],"one":"扁鹊、华佗、张仲景、孙思邈、李时珍。","ans":"古代名医通常指**扁鹊、华佗、张仲景、孙思邈、李时珍**。**扁鹊**是春秋战国时期名医，相传创**望、闻、问、切四诊**；**华佗**是东汉末年医学家，发明麻醉剂**麻沸散**，创编**五禽戏**；**张仲景**是东汉末年医学家，被尊为**“医圣”**，著《伤寒杂病论》；**孙思邈**是唐代医学家，被称**“药王”**，著《千金要方》；**李时珍**是明代药学家，著《本草纲目》。他们分别在诊法、外科、辨证论治、方药和本草学上有突出贡献。","pts":["扁鹊四诊，华佗麻沸散与五禽戏","张仲景医圣，孙思邈药王","李时珍《本草纲目》"],"members":[["扁鹊","春秋战国；望闻问切四诊"],["华佗","东汉末；麻沸散、五禽戏"],["张仲景","东汉末；医圣，《伤寒杂病论》"],["孙思邈","唐代；药王，《千金要方》"],["李时珍","明代；《本草纲目》"]],"mem":"按时间排：扁鹊（先秦）→华佗、张仲景（东汉）→孙思邈（唐）→李时珍（明）。一句话一人：扁鹊四诊，华佗麻沸，仲景医圣，思邈药王，时珍本草。称号配对只需记两个：张仲景“圣”，孙思邈“王”。","mix":"“医圣”是张仲景，不是华佗；“药王”是孙思邈，不是李时珍；华佗以外科和麻醉见长；《黄帝内经》不是某位名医所写，是托名黄帝的医学总集。","mcq":[{"q":"被尊为“药王”的古代医学家是","o":["李时珍","张仲景","扁鹊","孙思邈"],"a":3,"w":"孙思邈，唐代，著《千金要方》。"},{"q":"下列医学家中，发明“麻沸散”的是","o":["华佗","扁鹊","孙思邈","张仲景"],"a":0,"w":"东汉末华佗，也编创五禽戏。"}],"rel":[{"t":"张仲景与《伤寒杂病论》","n":"医圣"},{"t":"《本草纲目》","n":"李时珍之作"},{"t":"《黄帝内经》","n":"中医理论奠基"},{"t":"屠呦呦与青蒿素","n":"现代中医药成就"}],"more":"扁鹊：姓秦名越人；华佗：东汉末沛国谯县人；孙思邈：著《千金要方》《千金翼方》。","exam":[]},{"id":"a07-096","t":"张仲景与《伤寒杂病论》","cid":"07g","p":2,"kind":"人物","alias":["张仲景","医圣","伤寒杂病论","张机"],"one":"东汉医学家，确立辨证论治原则，被尊为医圣。","ans":"张仲景（名机）是**东汉末年医学家**，南阳人，被后世尊为**“医圣”**。他在汉末疫病流行中总结临床经验，写成**《伤寒杂病论》**。该书**确立了“辨证论治”的原则**，把外感病分为太阳、阳明、少阳、太阴、少阴、厥阴六经辨证，并记载大量方剂，被誉为“方书之祖”。后来此书经西晋王叔和整理伤寒部分，再经北宋林亿等人校订杂病部分，分为《伤寒论》和《金匮要略》两部。《伤寒杂病论》是中医临床的奠基之作，也被列入中医四大经典。","pts":["东汉张仲景，医圣","《伤寒杂病论》确立辨证论治","后分《伤寒论》《金匮要略》"],"mem":"“仲景医圣，辨证论治”八个字就是核心。书名拆成两半：“伤寒”是外感热病，“杂病”是内科杂病，所以后来也被拆成两本。中医四大经典记法：内、难、伤寒、神农（《黄帝内经》《难经》《伤寒杂病论》《神农本草经》）。","mix":"医圣是张仲景，药王是孙思邈；《伤寒杂病论》不是《黄帝内经》，后者是理论总集，前者是临床辨证方书；四大经典的具体篇目不同版本略有出入，通行以上述四部为准。","mcq":[{"q":"确立“辨证论治”原则的医学著作是","o":["《黄帝内经》","《本草纲目》","《千金要方》","《伤寒杂病论》"],"a":3,"w":"东汉张仲景《伤寒杂病论》。"}],"rel":[{"t":"古代名医","n":"并列名医"},{"t":"中医四大经典","n":"属其中之一"},{"t":"《黄帝内经》","n":"中医理论奠基"},{"t":"屠呦呦与青蒿素","n":"中医药成就"}],"more":"六经辨证：太阳、阳明、少阳、太阴、少阴、厥阴。\n《伤寒论》与《金匮要略》由《伤寒杂病论》分出。","exam":[]},{"id":"a07-097","t":"《神农本草经》","cid":"07g","p":3,"kind":"作品","alias":["本草经","本经"],"one":"东汉成书、中国现存最早的系统性中药学专著，载药365种。","ans":"《神农本草经》简称《本草经》，是**中国现存最早的中药学专著**，成书于**东汉时期**。全书系统载药**365种**，首创**“上药、中药、下药”的三品分类法**，并阐发了君臣佐使配伍理论。它奠定了中药学理论基石，位列**中医四大经典之一**。","pts":["中国现存最早的中药学专著，东汉成书","收载药物365种，首创上中下三品分类法","确立四气五味、君臣佐使等中药理论基石"],"mem":"联想：“**神农本草汉代成，三百六十五药三品分**”，上药养生，下药治病。","mix":"《神农本草经》是“现存最早”中药专著（载药365种，东汉）；《本草纲目》是明代集大成巨著（载药1892种，李时珍）；切勿混淆时代与药种数。","mcq":[{"q":"中国现存最早的中药学专著《神农本草经》成书于哪个朝代，共载药多少种","o":["西周，108种","秦代，256种","唐代，844种","东汉，365种"],"a":3,"w":"《神农本草经》成书于东汉，载药365种，合周天三百六十五度。"}],"rel":[{"t":"中医四大经典","n":"位列四大经典之中"},{"t":"《本草纲目》","n":"明代本草学发展顶峰"},{"t":"屠呦呦与青蒿素","n":"现代从本草中提取抗疟药"}],"exam":[]},{"id":"a07-098","t":"中医针灸","cid":"07g","p":3,"kind":"常识","alias":["针灸","中国针灸"],"one":"以经络腧穴理论为核心、2010年列入人类非遗的中国传统医学治疗技法。","ans":"中医针灸是**以经络腧穴理论为基础的传统物理疗法**，含针刺与艾灸。晋代皇甫谧撰成《针灸甲乙经》；**北宋王惟一铸造针灸铜人**统一规范了腧穴标准。**2010年中医针灸列入人类非物质文化遗产代表作名录**，成为中医药走向世界的标志。","pts":["以经络腧穴为基础，含针法与灸法","北宋王惟一铸针灸铜人规范全国腧穴","2010年列入联合国人类非物质文化遗产名录"],"mem":"口诀：“**甲乙经奠基，宋铜人定经穴，一零非遗扬天下**”，王惟一铸铜人。","mix":"“针”是毫针刺入穴位，“灸”是以艾绒熏灼；晋代皇甫谧著《针灸甲乙经》，北宋王惟一设计铸造针灸铜人；2010年入选人类非遗。","mcq":[{"q":"北宋时期设计并主持铸造‘针灸铜人’以统一规范全国穴位标准的医家是","o":["王惟一","皇甫谧","孙思邈","钱乙"],"a":0,"w":"北宋医官王惟一于公元1027年主持铸造两具针灸铜人，并撰《铜人腧穴针灸图经》。"}],"rel":[{"t":"《黄帝内经》","n":"针灸经络理论的源头"},{"t":"张仲景与《伤寒杂病论》","n":"同属中医药宝库杰作"},{"t":"屠呦呦与青蒿素","n":"传统中医药现代非遗传承"}],"exam":[]},{"id":"a07-099","t":"屠呦呦与青蒿素","cid":"07g","p":1,"kind":"人物","alias":["屠呦呦","青蒿素","青蒿素与疟疾"],"one":"2015年诺贝尔生理学或医学奖得主，受葛洪《肘后备急方》启发发现青蒿素。","ans":"屠呦呦（1930年生），**浙江宁波人，中国中医科学院研究员**。20世纪60至70年代，她参与国家“523”抗疟项目，受**东晋葛洪《肘后备急方》**“青蒿一握，以水二升渍，绞取汁”的启发，改用乙醚低温提取，得到抗疟有效成分**青蒿素**。2015年她与另外两位科学家分享**诺贝尔生理学或医学奖**，是**首位获诺贝尔科学类奖项的中国本土科学家**。青蒿素类药物成为治疗疟疾的首选，挽救了全球数百万人的生命，也展示了中医药古籍与现代科学结合的价值。","pts":["中医科学院研究员，参与“523”抗疟项目","受《肘后备急方》启发，提取青蒿素","2015年诺贝尔生理学或医学奖"],"mem":"一条线：古书（葛洪《肘后备急方》）→改用乙醚低温提取→青蒿素→2015年诺奖。古方写“绞取汁”，即不煎煮，这一提示促使她避开高温，是关键一步。数字：1930年生，2015年获奖。","mix":"2012年莫言获诺贝尔文学奖，2015年屠呦呦获诺贝尔科学类奖；杨振宁、李政道等获奖时不是中国国籍，所以屠呦呦是“中国本土科学家”首位。","mcq":[{"q":"屠呦呦从哪部古籍中获得青蒿提取灵感","o":["《肘后备急方》","《伤寒杂病论》","《千金方》","《本草纲目》"],"a":0,"w":"东晋葛洪《肘后备急方》载“青蒿一握，以水二升渍，绞取汁”。"},{"q":"屠呦呦获诺贝尔生理学或医学奖的年份是","o":["2010年","2012年","2015年","2018年"],"a":2,"w":"2015年，因青蒿素的发现获奖。"}],"rel":[{"t":"《黄帝内经》","n":"中医经典"},{"t":"中医四大经典","n":"传统医学对照"},{"t":"《本草纲目》","n":"药学典籍"},{"t":"国家最高科学技术奖","n":"国内科技最高奖"},{"t":"《神农本草经》","n":"药学传统"}],"more":"2015年诺贝尔生理学或医学奖由屠呦呦、威廉·坎贝尔、大村智共享，屠呦呦获奖份额为一半。\n2019年获“共和国勋章”。","exam":[]},{"id":"a07-100","t":"南青北白","cid":"07h","p":2,"kind":"概念","alias":["越窑青瓷","邢窑白瓷","秘色瓷"],"one":"唐代瓷业格局：南方越窑青瓷，北方邢窑白瓷。","ans":"“南青北白”是**对唐代瓷业格局的概括**：**南方以越窑青瓷为代表，北方以邢窑白瓷为代表**。越窑在浙江，主要产区在上虞、慈溪上林湖一带，所产青瓷精品称**“秘色瓷”**；邢窑在河北邢台一带，白瓷洁白细润。陆羽《茶经》评价“邢瓷类银，越瓷类玉”，并对二者作了比较。唐代的青瓷与白瓷相对，后来发展为宋代五大名窑的格局，景德镇则在宋代之后逐渐兴起。","pts":["唐代瓷业格局","南方越窑青瓷，北方邢窑白瓷","越窑精品称秘色瓷"],"mem":"方位口诀：南＝青（越窑），北＝白（邢窑）。画面：江南碧水配青瓷，北方雪色配白瓷。《茶经》“邢瓷类银，越瓷类玉”：白像银，青像玉。","mix":"“南青北白”是唐代，宋代才是汝官哥钧定五大名窑；唐三彩是低温釉陶，不属于青瓷或白瓷；“秘色瓷”是越窑青瓷的精品。","mcq":[{"q":"“南青北白”中的“北白”指的是","o":["定窑白瓷","德化白瓷","邢窑白瓷","景德镇白瓷"],"a":2,"w":"唐代北方以邢窑白瓷为代表。"}],"rel":[{"t":"宋代五大名窑","n":"宋代名窑格局"},{"t":"陆羽《茶经》","n":"评邢瓷越瓷"},{"t":"青花瓷","n":"元代景德镇成熟"},{"t":"景德镇手工瓷业遗存","n":"瓷都申遗"}],"more":"1987年陕西扶风法门寺地宫出土唐代秘色瓷。","exam":[]},{"id":"a07-101","t":"青花瓷","cid":"07h","p":2,"kind":"常识","alias":["元青花","青花","白地蓝花"],"one":"以钴料绘画后罩透明釉烧成，成熟于元代景德镇。","ans":"青花瓷是**以钴料在白色瓷胎上绘画，再罩透明釉经高温一次烧成的釉下彩瓷**，呈蓝色花纹。青花瓷**成熟于元代的景德镇**，称“元青花”，以绘画精细、纹饰繁密、器型硕大著称。明代永乐宣德年间使用进口钴料“苏麻离青”，青花瓷品质最高；清代康熙青花也很出名。青花瓷是景德镇的代表产品，**景德镇手工瓷业遗存于2026年列入世界遗产**，青花瓷由此成为中国瓷业走向世界的代表符号。","pts":["钴料绘画，罩透明釉高温烧成","成熟于元代景德镇","景德镇2026年入遗"],"mem":"一句话流程：钴料画花，透明釉罩，一次烧成，蓝色花纹出现在釉下。年代线：唐有青花雏形，元代成熟，明代永乐宣德最精，清代康熙最盛。名称里“青”指蓝，“花”指花纹。","mix":"青花是釉下彩，粉彩、斗彩等是釉上彩或釉上釉下结合；“青花”与越窑“青瓷”不同，青瓷是青色釉，青花是白瓷上蓝色花纹。","mcq":[{"q":"青花瓷的主要着色原料是","o":["铜","钴","铁","金"],"a":1,"w":"青花用钴料绘画，高温烧成呈蓝色。"}],"rel":[{"t":"景德镇手工瓷业遗存","n":"2026年入遗"},{"t":"宋代五大名窑","n":"此前窑系"},{"t":"南青北白","n":"唐代格局"},{"t":"中国近年新增世界遗产","n":"遗产保护体系"}],"more":"元青花：至正十一年（1351年）款青花云龙象耳瓶，是有明确纪年的元青花标准器。","exam":[]},{"id":"a07-102","t":"紫砂壶","cid":"07h","p":3,"kind":"常识","alias":["宜兴紫砂壶","宜兴紫砂"],"one":"江苏宜兴特产、以双气孔透气不透水结构著称的中国传统手工泥陶茶具。","ans":"紫砂壶是**中国江苏宜兴特产的传统泥陶工艺茶具**。采用独特的**紫砂泥料手工拍打镶接成型**经高温烧制。具**双重气孔透气结构**，泡茶色香味俱佳。始于宋代，**明代供春与时大彬奠定其艺术高峰**。紫砂壶融汇诗书画印于一体，具有高雅的文人意趣。","pts":["江苏宜兴特产，以天然紫砂泥料手工制作","具双重气孔结构，透气不透水，极宜泡茶","明代供春、时大彬成集大成者，具文人雅趣"],"mem":"联想：“**宜兴紫砂供春壶，双重气孔聚茶香**”，明代时大彬集其大成。","mix":"紫砂壶属于炻器（介于陶与瓷之间的多孔性无釉陶器），不属于瓷器；明代供春为紫砂壶名家之祖，时大彬集大成。","mcq":[{"q":"被誉为中国‘陶都’、以出产传统紫砂壶闻名海内外的地方是","o":["江西景德镇","浙江龙泉","江苏宜兴","河南禹州"],"a":2,"w":"江苏宜兴被称为陶都，其紫砂泥质优良，所产紫砂壶闻名天下。"}],"rel":[{"t":"中国十大名茶","n":"名茶与名壶相配"},{"t":"景德镇手工瓷业遗存","n":"陶都宜兴与瓷都景德镇对举"},{"t":"文房四宝","n":"同具文人书斋审美意趣"}],"exam":[]},{"id":"a07-103","t":"中国十大名茶","cid":"07h","p":3,"kind":"合称","alias":["十大名茶"],"one":"中国传统茶文化中十种享誉海内外的代表性名茶的并称。","ans":"中国十大名茶是**中国传统茶文化中声誉最高的十类代表名茶**。通行版本包括绿茶类的**西湖龙井、碧螺春、黄山毛峰等**；黄茶类的**君山银针**；半发酵乌龙茶类的**武夷岩茶、安溪铁观音**；以及全发酵红茶**祁门红茶**。涵盖了中国六大茶类精华。","pts":["涵盖绿、黄、青、红等主要发酵茶类","绿茶占六席（龙井、碧螺春、毛峰等）","乌龙茶有铁观音、岩茶，红茶有祁门红茶"],"members":[["西湖龙井","产于浙江杭州西湖，不发酵绿茶，扁平光滑，色翠香郁，为中国名茶之冠"],["洞庭碧螺春","产于江苏苏州太湖洞庭山，不发酵绿茶，条索纤细，卷曲成螺，清香持久"],["黄山毛峰","产于安徽黄山，不发酵绿茶，芽尖微卷，状如雀舌，色如象牙，回味甘醇"],["庐山云雾","产于江西九江庐山，不发酵绿茶，条索粗壮，香如幽兰，滋味醇厚"],["六安瓜片","产于安徽六安大别山区，不发酵绿茶，唯一由单片嫩叶制成、无芽无梗的名茶"],["君山银针","产于湖南岳阳洞庭湖君山岛，轻发酵黄茶，芽头茁壮挺直，满披白毫，金镶白玉"],["信阳毛尖","产于河南信阳大别山，不发酵绿茶，条索细圆紧直，白毫明显，香高味浓"],["武夷岩茶","产于福建武夷山，半发酵乌龙茶，代表为大红袍，兼具绿茶清香与红茶醇厚，具岩韵"],["安溪铁观音","产于福建泉州安溪，半发酵乌龙茶，叶重如铁，具天然馥郁兰花香与独特“音韵”"],["祁门红茶","产于安徽黄山祁门，全发酵红茶，条索紧细，带蜜糖果香，并称世界三大高香红茶"]],"mem":"缩写口诀：“**龙碧毛云瓜信针，岩茶观音祁门红**”，六绿一黄二青一红。","mix":"乌龙茶（青茶）是半发酵茶（武夷岩茶、安溪铁观音）；君山银针是黄茶（轻发酵/闷黄），不是绿茶；祁门红茶是全发酵红茶。","mcq":[{"q":"在‘中国十大名茶’中，属于半发酵乌龙茶（青茶）的是","o":["西湖龙井","君山银针","祁门红茶","安溪铁观音"],"a":3,"w":"安溪铁观音与武夷岩茶属于半发酵乌龙茶（青茶）；龙井为绿茶，银针为黄茶，祁门为红茶。"}],"rel":[{"t":"六大茶类","n":"十大名茶的发酵分类基础"},{"t":"陆羽《茶经》","n":"茶文化奠基经典"},{"t":"茶马古道","n":"名茶经贸传播古道"}],"exam":[]},{"id":"a07-104","t":"中国传统制茶技艺及其相关习俗","cid":"07h","p":2,"kind":"常识","alias":["中国茶申遗","制茶技艺非遗","茶非遗"],"one":"2022年11月列入人类非遗代表作名录的茶类遗产项目。","ans":"“中国传统制茶技艺及其相关习俗”是**中国的茶类非物质文化遗产项目**，于**2022年11月列入联合国教科文组织人类非物质文化遗产代表作名录**。项目涵盖绿茶、黄茶、黑茶、白茶、乌龙茶、红茶、再加工茶等**六大基本茶类及再加工茶**的制作技艺，以及相关的饮茶、祭祀、茶俗等习俗。它属于《保护非物质文化遗产公约》（2003年）框架，与此前入选的端午节、二十四节气等共同构成中国的人类非遗项目。入选体现了茶在中国人生活中的深厚地位。","pts":["2022年11月入选人类非遗代表作名录","涵盖六大茶类及再加工茶的制作技艺与习俗","属于《保护非物质文化遗产公约》体系"],"mem":"“2022年11月，中国茶，入人类非遗”。年份挂钩：2009端午、2016二十四节气、2022制茶、2024春节，按顺序首字串联就是“端节制春”（端午、节气、制茶、春节）。","mix":"“中国传统制茶技艺及其相关习俗”是非遗（活态技艺和习俗），属2003年《公约》；普洱景迈山古茶林是世界文化遗产（2023年），属1972年《公约》，两者不要混。","mcq":[{"q":"“中国传统制茶技艺及其相关习俗”列入人类非遗代表作名录的年份是","o":["2009年","2016年","2022年","2024年"],"a":2,"w":"2022年11月入选；2009端午，2016二十四节气，2024春节。"}],"rel":[{"t":"六大茶类","n":"项目涉及茶类"},{"t":"人类非遗代表作中国项目","n":"中国非遗总表"},{"t":"春节列入人类非遗代表作名录","n":"2024年入选"},{"t":"陆羽《茶经》","n":"茶学专著"}],"more":"2023年：普洱景迈山古茶林文化景观列入世界遗产（文化遗产）。","exam":[]},{"id":"a07-105","t":"茶马古道","cid":"07h","p":3,"kind":"地理","alias":["茶马互市之道"],"one":"西南地区以马帮运茶为主、促进多民族交融与边疆商贸的古代贸易通道。","ans":"茶马古道是**中国西南地区以马帮为主要运力的古代民间商道**，兴于唐宋盛于明清。包括**陕甘、川藏与滇藏干线**，源于中原与边疆少数民族的**“茶马互市”**（茶叶换取藏区战马）。穿越横断山脉，是促进**汉藏多民族文化交融互补**的“南方丝绸之路”。","pts":["西南地区以马帮贩运茶马为主的古代商道","分为陕甘、川藏、滇藏干线，源于茶马互市","促进汉藏民族交流融合，被称为南方丝路"],"mem":"联想：“**横断山中马帮行，引茶换马固边防**”，唐宋茶马互市，滇川通雪域。","mix":"茶马古道以茶叶与战马互换为核心（中原茶叶解藏区糌粑油腻，藏区良马增强国防），不同于以丝绸瓷器为主的西北丝绸之路。","mcq":[{"q":"古代‘茶马互市’兴起的主要经济与国防动因是","o":["中原输出茶叶以换取边疆优质战马","藏区输出茶叶以换取中原丝绸","西域输出茶叶以换取中原铁器","江南输出良马以换取西南茶叶"],"a":0,"w":"朝廷以茶叶交换藏区和西北战马，既满足边民饮茶解腻需求，又充实国防战马储备。"}],"rel":[{"t":"中国十大名茶","n":"茶马古道贩运核心商品"},{"t":"丝绸之路","n":"古代著名商道对比"},{"t":"陆羽《茶经》","n":"茶文化普及推动边销茶贸易"}],"exam":[]},{"id":"a07-106","t":"酒的起源与名酒","cid":"07h","p":3,"kind":"常识","alias":["杜康造酒","中国酒文化"],"one":"中国古代酿酒始祖传说、酒文化发展及黄酒、白酒等传统名酒的概称。","ans":"酒的起源与名酒概括了**中国悠久的酿酒历史与名酒谱系**。古代传说**夏代仪狄作酒醪、杜康造秫酒**，杜康被尊为**“酒祖”**。传统名酒分两类：以**绍兴黄酒为代表的压榨发酵酒**，以及元代普及的**固态蒸馏白酒**。酒礼深深融入文教节令。","pts":["传说仪狄造酒醪、杜康造秫酒（酒祖）","绍兴黄酒为代表的传统古法发酵酒","元代普及固态蒸馏白酒，融汇祭祀文学"],"mem":"联想：“**仪狄酿醪杜康曲，绍兴黄酒茅台香**”，曹操名句“唯有杜康”。","mix":"仪狄造醪（浊酒/甜酒），杜康造秫酒（高粱酒），杜康被奉为酒祖；中国古代本土古酒是黄酒（发酵酒），蒸馏白酒（烧酒）元代才广泛成熟。","mcq":[{"q":"曹操《短歌行》‘何以解忧？唯有杜康’中，‘杜康’代指酒，在古代传说中杜康被尊为","o":["茶圣","酒祖","草圣","药王"],"a":1,"w":"杜康相传善酿秫酒，被后世尊为酿酒始祖，诗文中常以‘杜康’代称美酒。"}],"rel":[{"t":"节令酒与节令食","n":"传统节令饮食文化"},{"t":"曹操","n":"作《短歌行》以杜康代酒"},{"t":"腊八节与小年","n":"岁末年节饮宴习俗"}],"exam":[]},{"id":"a07-107","t":"四大菜系","cid":"07h","p":2,"kind":"合称","alias":["鲁川粤淮扬"],"one":"鲁菜、川菜、粤菜、淮扬菜（苏菜）。","ans":"四大菜系指**鲁菜、川菜、粤菜、淮扬菜（苏菜）**，是中国地方菜中影响最大的四个。**鲁菜**为山东菜，是北方菜的代表，讲究鲜咸、爆炒；**川菜**为四川菜，以麻辣著称，有“一菜一格，百菜百味”之说；**粤菜**为广东菜，讲究清淡鲜美，用料广泛；**淮扬菜**以扬州、淮安为代表，重刀工，口味清鲜。四大菜系再加上浙菜、闽菜、湘菜、徽菜，即为**八大菜系**。","pts":["鲁、川、粤、淮扬","鲁菜北方，川菜麻辣，粤菜清淡，淮扬重刀工","加浙闽湘徽成八大菜系"],"members":[["鲁菜","山东，北方菜代表"],["川菜","四川，麻辣，一菜一格"],["粤菜","广东，清淡鲜美"],["淮扬菜","扬州淮安，重刀工，口味清鲜"]],"mem":"口诀“鲁川粤淮扬”，对应“北、西、南、东”：鲁（北）、川（西）、粤（南）、淮扬（东）。八大菜系在此基础上加“浙闽湘徽”，口诀“鲁川粤苏，浙闽湘徽”。","mix":"四大菜系与八大菜系的差别：前者是鲁川粤淮扬，后者加浙闽湘徽；有的说法用“苏菜”代替“淮扬菜”，也有“鲁川粤苏”的版本，两者指同一系统。","mcq":[{"q":"下列属于四大菜系的是","o":["湘菜","徽菜","浙菜","鲁菜"],"a":3,"w":"四大菜系为鲁川粤淮扬；湘徽浙属八大菜系的后四位。"}],"rel":[{"t":"八大菜系","n":"在四大基础上扩展"},{"t":"六大茶类","n":"同属饮食文化"},{"t":"中国十大名茶","n":"同属饮食文化"},{"t":"四大名绣","n":"同样以地域分"}],"more":"八大菜系：鲁、川、粤、苏、浙、闽、湘、徽。","exam":[]},{"id":"a07-108","t":"三大名锦（四大名锦）","cid":"07h","p":3,"kind":"合称","alias":["中国三大名锦","中国四大名锦","名锦"],"one":"中国传统提花丝织工艺中南京云锦、蜀锦、宋锦及壮锦的合称。","ans":"三大名锦（四大名锦）是**中国传统提花丝织工艺的杰出代表**。三大名锦指**南京云锦**（皇家御用）、**成都蜀锦**（历史最悠久）与**苏州宋锦**（书画装裱）；加上少数民族织锦**壮锦**合称四大名锦。代表了古代蚕桑提花织造技艺的巅峰。","pts":["三大名锦为南京云锦、四川蜀锦、苏州宋锦","加广西壮锦合称为四大名锦","代表古代蚕桑提花丝织工艺的巅峰水准"],"members":[["南京云锦","产于江苏南京，织造华美如云霞，大量采用真金捻线与孔雀羽，元明清皇家御用织锦"],["四川蜀锦","产于四川成都，起源于先秦汉代，历史最悠久，纹样绚丽严谨，成都因之称“锦官城”"],["苏州宋锦","产于江苏苏州，始于宋代，色泽典雅柔和，质地平整挺括，多用于高档书画装裱与宫廷服饰"],["广西壮锦","产于广西壮族地区（靖西、宾阳），以棉线为经、彩丝为纬织成，图案粗犷繁复，民族特色浓郁（四大名锦所增）"]],"mem":"地名口诀：“**苏有宋锦金陵云，蜀锦锦官壮锦斑**”，前三为三大，添壮成四大。","mix":"“三大名锦”是南京云锦、成都蜀锦、苏州宋锦；“四大名锦”增加了少数民族织锦“广西壮锦”；注意与“四大名绣”（苏绣、湘绣、粤绣、蜀绣）区分。","mcq":[{"q":"在‘中国三大名锦’的基础上，增加哪一种少数民族传统织锦合称为‘中国四大名锦’","o":["土家织锦","傣锦","广西壮锦","黎锦"],"a":2,"w":"四大名锦为南京云锦、四川蜀锦、苏州宋锦和广西壮锦。"}],"rel":[{"t":"四大名绣","n":"中国传统织绣艺术双璧"},{"t":"中国蚕桑丝织技艺","n":"织锦依托的非遗技艺体系"},{"t":"景泰蓝","n":"同属传统皇家宫廷精绝工艺"}],"exam":[]},{"id":"a07-109","t":"中国蚕桑丝织技艺","cid":"07h","p":3,"kind":"常识","alias":["蚕桑丝织技艺","中国蚕桑丝织"],"one":"涵盖栽桑养蚕缫丝织绸、2009年列入人类非遗的传统手工技艺体系。","ans":"中国蚕桑丝织技艺是**中国五千年农耕手工业文明传承的代表性技艺**。涵盖**栽桑、养蚕、缫丝、染色与丝织**全流程及传统工具（如缂丝、杭罗）。中国是丝绸发源地。**2009年该技艺被列入联合国人类非物质文化遗产代表作名录**。","pts":["涵盖栽桑、养蚕、缫丝、织造等完整工序","中国是丝绸发源地，丝路文脉核心承载","2009年列入人类非物质文化遗产代表作名录"],"mem":"联想：“**栽桑养蚕缫丝织，二零零九入非遗**”，五千年丝绸文明源头。","mix":"中国蚕桑丝织技艺包含完整的农业养蚕与手工织造全链条（如杭罗、缂丝等）；2009年入选联合国人类非物质文化遗产名录。","mcq":[{"q":"‘中国蚕桑丝织技艺’被联合国教科文组织正式列入人类非物质文化遗产代表作名录的年份是","o":["2006年","2013年","2020年","2009年"],"a":3,"w":"2009年，中国蚕桑丝织技艺与南京云锦、端午节等一同列入人类非遗名录。"}],"rel":[{"t":"三大名锦（四大名锦）","n":"蚕桑丝织技艺结晶"},{"t":"四大名绣","n":"丝织刺绣工艺相承"},{"t":"丝绸之路","n":"丝绸商品走向世界的通道"}],"exam":[]},{"id":"a07-111","t":"四大年画","cid":"07h","p":3,"kind":"合称","alias":["中国四大木版年画","四大木版年画"],"one":"中国传统木版年画中杨柳青、桃花坞、杨家埠与绵竹四大流派的合称。","ans":"四大年画指**中国传统民间木版年画中成就最高、流传最广的四大流派**。分别为**天津杨柳青**（半印半画）、**苏州桃花坞**（刻工清雅）、**潍坊杨家埠**（木版套印）与**四川绵竹**（彩绘浓艳）。各派多以神祇吉祥戏曲为题材，寄托岁时纳祥祈福心愿。","pts":["四大流派：杨柳青、桃花坞、杨家埠、绵竹","工艺特色迥异，有半印半画与木版套印之分","以吉祥辟邪、戏曲故事为题材，列入国家级非遗"],"members":[["天津杨柳青","产于天津杨柳青镇，特色为“半印半画”，刻工细腻，设色典雅，人物生动，娃娃题材尤负盛名"],["苏州桃花坞","产于江苏苏州桃花坞，受明清文人画与水乡风情熏陶，刻工清秀细致，色彩清雅淡丽，富江南雅韵"],["山东潍坊杨家埠","产于山东潍坊杨家埠村，全版套色木刻，线条粗犷简练，色彩鲜艳纯烈，乡土气息极其浓厚"],["四川绵竹","产于四川绵竹，以手工彩绘见长（一印八刻，手绘为主），设色浓艳，造型夸张威武，门神题材著名"]],"mem":"南北四派口诀：“**南桃北柳杨家埠，西南绵竹绘新图**”，桃桃花坞、柳杨柳青。","mix":"天津杨柳青特点是“半印半画”（木版印线，手工彩绘敷色）；苏州桃花坞为纯版刻套印，并称“南桃北柳”；杨家埠全版套印，绵竹重彩绘。","mcq":[{"q":"在传统民间木版年画中，以‘半印半画’为鲜明工艺特色的著名流派是","o":["天津杨柳青","苏州桃花坞","山东潍坊杨家埠","四川绵竹"],"a":0,"w":"天津杨柳青年画采用‘半印半画’工艺，先木版印出线稿，再以人工敷彩勾勒面部。"}],"rel":[{"t":"桃符与春联","n":"同属新春岁时吉祥民俗"},{"t":"风筝之都等","n":"潍坊杨家埠与潍坊风筝同地"},{"t":"中国剪纸","n":"同属民间传统造型艺术"}],"exam":[]},{"id":"a07-112","t":"中国剪纸","cid":"07h","p":3,"kind":"常识","alias":["剪纸","刻纸","窗花"],"one":"以剪刀或刻刀在纸上剪刻镂空图案装点生活的传统民间造型艺术。","ans":"中国剪纸是**在纸上剪刻镂空图案的代表性民间造型艺术**。汉唐发端宋明普及，地域上呈现**北方剪纸的粗犷**与**南方剪纸的细腻**。广泛用于春节贴窗花与婚嫁节庆装饰。**2009年中国剪纸被列入联合国人类非物质文化遗产代表作名录**。","pts":["以剪刀或刻刀镂空纸张的传统民间美术","北方粗犷浑厚，南方纤巧清秀","用于窗花喜庆装饰，2009年列入人类非遗"],"mem":"联想：“**一把剪刀裁千巧，南秀北拙入非遗**”，贴窗花缀年俗，2009年申遗成功。","mix":"剪纸技法分为“剪”与“刻”；北方以陕北窗花为代表（粗犷朴茂），南方以扬州、浙江剪纸为代表（精细纤巧）；2009年列入人类非遗。","mcq":[{"q":"中国剪纸风格南北各异，下列哪项属于南方剪纸流派的代表性艺术特征","o":["粗犷质朴、天真浑厚","精细纤巧、清秀流利","构图简练、稚拙豪放","大幅通景、雄浑沉着"],"a":1,"w":"南方剪纸（如江苏扬州、浙江乐清）以精巧细腻、线条秀丽流利见长。"}],"rel":[{"t":"四大年画","n":"同属民间传统造型美术"},{"t":"桃符与春联","n":"同属新春岁时装饰民俗"},{"t":"腊八节与小年","n":"岁末扫尘贴窗花习俗"}],"exam":[]},{"id":"a07-113","t":"古代四大名镇","cid":"07h","p":3,"kind":"合称","alias":["中国古代四大名镇","明清四大名镇","四大名镇"],"one":"明清时期以商品经济崛起、非行政州县首府的四大著名工商业市镇。","ans":"古代四大名镇指**明清时期工商业高度繁荣的四大著名市镇**。包括**江西景德镇**（瓷都）、**广东佛山镇**（冶铁商贸）、**湖北汉口镇**（九省水运）与**河南朱仙镇**（商运年画）。它们**突破传统行政州县模式**，以纯粹的商品经济闻名天下。","pts":["明清四大名镇：景德镇、佛山镇、汉口镇、朱仙镇","分别以制瓷、冶铁、商业枢纽、中原转运见长","突破传统州县行政中心模式，代表商品经济高峰"],"members":[["江西景德镇","以瓷器制造业闻名天下，官窑民窑汇聚，产瓷誉满全球，有“瓷都”之称"],["广东佛山镇","岭南商贸与手工业重镇，以冶铁、铸造、陶瓷、纺织见长，南派武术与龙狮文化发源地"],["湖北汉口镇","地处长江与汉江交汇处，九省通衢，水陆交通发达，明清长江流域最大商业枢纽重镇"],["河南朱仙镇","中原水陆交通要冲，贾鲁河商业运输枢纽，以岳飞抗金大捷与木版年画闻名于世"]],"mem":"四名镇口诀：“**江西景德瓷，广东佛山铁，湖北汉口水，河南朱仙结**”，瓷铁水运中原聚。","mix":"四大名镇均非传统省城或府州首府，而是依托产业与交通自发崛起的商业市镇；景德镇以瓷名，佛山以冶铁铸造名，汉口以水运码头名，朱仙镇以商运与年画名。","mcq":[{"q":"明清‘古代四大名镇’中，以陶瓷制造闻名于世、享有‘瓷都’美誉的是","o":["河南朱仙镇","广东佛山镇","江西景德镇","湖北汉口镇"],"a":2,"w":"江西景德镇为千年瓷都；广东佛山以冶铁著称；湖北汉口以商业水运著称；河南朱仙镇以水运年画著称。"}],"rel":[{"t":"景德镇手工瓷业遗存","n":"四大名镇之首文化遗产"},{"t":"四大年画","n":"河南朱仙镇亦为著名年画产地"},{"t":"重农抑商","n":"明清商品经济突破传统抑商束缚"}],"exam":[]},{"id":"a07-114","t":"文人四艺（琴棋书画）","cid":"07h","p":2,"kind":"合称","alias":["琴棋书画","四艺"],"one":"琴、棋、书、画，古代文人的四种修养技艺。","ans":"文人四艺指**琴、棋、书、画**，是古代文人修身养性的四种技艺，也是衡量文人素养的标准。**琴**指古琴，如伯牙子期“高山流水”；**棋**主要指围棋，古称“弈”，起源于中国；**书**指书法，如王羲之被称“书圣”；**画**指绘画，包括山水、花鸟、人物。琴棋书画在古代常被作为才女才子的标配，也出现在《红楼梦》等小说里。其中古琴艺术于2003年列入联合国教科文组织人类口头和非物质遗产代表作，围棋也是中国最具代表性的传统棋类。","pts":["琴、棋、书、画","琴为古琴，棋为围棋，书为书法，画为绘画","古琴艺术2003年入选人类口头和非物质遗产代表作"],"members":[["琴","古琴，伯牙子期“高山流水”"],["棋","围棋，古称“弈”"],["书","书法，王羲之被称书圣"],["画","绘画，山水花鸟人物"]],"mem":"口诀就是四个字“琴棋书画”，顺序固定，不可调。一个字配一个人：琴—伯牙，棋—围棋，书—王羲之，画—顾恺之（或其他画家），记一人一艺。围棋考过两次，所以“棋”是重点。","mix":"“琴棋书画”的“棋”指围棋，不是象棋或国际象棋；“琴”指古琴，不是古筝或钢琴；古琴艺术2003年入选，早于2009年的端午节，年份不要相混。","mcq":[{"q":"“琴棋书画”中的“棋”指的是","o":["围棋","国际象棋","中国象棋","跳棋"],"a":0,"w":"文人四艺之棋指围棋，古称弈。"}],"rel":[{"t":"围棋与国际象棋","n":"“棋”的内容"},{"t":"围棋“收官”","n":"围棋术语"},{"t":"王羲之","n":"书圣，“书”的代表"},{"t":"人类非遗代表作中国项目","n":"古琴入选非遗"}],"more":"古琴艺术：2003年列入“人类口头和非物质遗产代表作”（后并入人类非遗代表作名录）。","exam":[]},{"id":"a07-115","t":"珠算","cid":"07h","p":3,"kind":"常识","alias":["中国珠算","算盘"],"one":"以算盘为工具、口诀进行四则运算的中国传统计算系统，2013年入非遗。","ans":"珠算是**以算盘为工具、口诀进行四则运算的传统数学技艺**。由古代筹算演变而来，明代程大位撰**《算法统宗》**使其成熟普及并取代筹算。被誉为**“最早的便携式计算机”**。**2013年“中国珠算”列入人类非物质文化遗产代表作名录**。","pts":["以算盘为工具、口诀运算的传统数学技艺","明代程大位《算法统宗》集其大成并普及","2013年列入联合国人类非物质文化遗产名录"],"mem":"联想：“**古筹演变算盘珠，程氏统宗定口诀，一三非遗誉全球**”。","mix":"珠算由古代筹算演化而来；明代程大位《算法统宗》集珠算大成；2013年列入联合国教科文组织人类非遗名录（是非物质文化遗产，而非物质载体本身）。","mcq":[{"q":"明代系统总结珠算理论与实用口诀、使珠算完全取代筹算并广泛普及的数学名著是程大位所撰","o":["《九章算术》","《数书九章》","《周髀算经》","《算法统宗》"],"a":3,"w":"明代程大位所撰《算法统宗》集珠算之大成，使珠算走向成熟与全面普及。"}],"rel":[{"t":"《周髀算经》","n":"同属传统数学科技经典"},{"t":"《九章算术》","n":"古代筹算数学体系源头"},{"t":"四大发明","n":"同属中国古代重大科技发明"}],"exam":[]},{"id":"a07-116","t":"太极拳","cid":"07h","p":3,"kind":"常识","alias":["太极"],"one":"融合阴阳哲理、经络导引与技击于一体的传统武术，2020年列入人类非遗。","ans":"太极拳是**融合阴阳哲理与经络技击的中国传统拳术**。明末清初发源于**河南温县陈家沟**（陈王廷创立），后衍生杨、武、吴、孙等派。动作**圆活连贯、以柔克刚**，内外兼修。**2020年太极拳被列入联合国人类非物质文化遗产代表作名录**。","pts":["融阴阳哲理、经络与技击于一体的传统拳术","明末清初发源于河南温县陈家沟陈王廷","2020年列入联合国人类非物质文化遗产名录"],"mem":"联想：“**陈家沟里生太极，以柔克刚阴阳调，二零二零入非遗**”。","mix":"太极拳发源于河南温县陈家沟（陈王廷），并非武侠小说中张三丰所创；2020年列入人类非物质文化遗产代表作名录。","mcq":[{"q":"被公认为中国传统太极拳发源地的是","o":["湖北武当山","河北沧州","河南温县陈家沟","广东佛山"],"a":2,"w":"太极拳发源于河南省焦作市温县陈家沟，明末清初由陈王廷创编陈氏太极拳。"}],"rel":[{"t":"中医针灸","n":"同具阴阳经络传统哲学基础"},{"t":"《黄帝内经》","n":"养生经络理论思想源泉"},{"t":"古代四大名镇","n":"佛山镇亦为传统武术之乡"}],"exam":[]},{"id":"d07-001","t":"泰山","cid":"07c","p":2,"kind":"地理","alias":["岱宗","东岳","东岳泰山"],"one":"五岳之首，古称岱宗，历代帝王封禅圣山，1987年列为中国首个世界双遗产。","ans":"泰山古称**岱宗**、**东岳**，位于**山东泰安**，主峰**玉皇顶**（官方测定海拔1532.7米，习称1545米），居**五岳之首**，有“五岳独尊”之誉。自秦皇汉武起，泰山为历代帝王**封禅**祭天圣山，留存岱庙、摩崖石刻与杜甫《望岳》等名篇。**1987年**泰山列入《世界遗产名录》，是中国首个**世界文化与自然双重遗产**。","pts":["古称岱宗、东岳，山东泰安，五岳之首","历代帝王封禅圣山，主峰玉皇顶","1987年入选，中国首个世界文化与自然双重遗产"],"mem":"三“最/首”记泰山：**五岳之首**（东岳岱宗）+帝王**封禅**首选+1987年**中国首个**世界双遗产（同批6项中唯一双遗产）。","mix":"玉皇顶海拔有国家测绘局实测1532.7米与传统石碑标注1545米两说；中国四处世界文化与自然双遗产为泰山（1987）、黄山（1990）、峨眉山与乐山大佛（1996）、武夷山（1999），泰山为中国最早（国际上1979年危地马拉蒂卡尔国家公园等已先入选双遗产，勿误记为世界首个）。","mcq":[{"q":"1987年中国首批入选《世界遗产名录》的六处遗产中，唯一一项“世界文化与自然双重遗产”是","o":["长城","泰山","明清皇宫（故宫）","敦煌莫高窟"],"a":1,"w":"1987年首批6项中，泰山是唯一的文化与自然双重遗产，其余5项均为文化遗产。"}],"rel":[{"t":"五岳","n":"东岳泰山居五岳之首"},{"t":"中国首批世界遗产（1987年6项）","n":"1987年首批入选且唯一双遗产"},{"t":"世界遗产类型","n":"世界首个双遗产实例"},{"t":"《保护世界文化和自然遗产公约》","n":"依据该公约列入名录"}],"more":"名句：会当凌绝顶，一览众山小。｜杜甫《望岳》","exam":[]},{"id":"d07-002","t":"毕昇与活字印刷","cid":"07g","p":1,"kind":"人物","alias":["毕昇","活字印刷术","泥活字"],"one":"北宋庆历年间毕昇发明胶泥活字印刷术，载于沈括《梦溪笔谈》，早于古登堡约四百年。","ans":"毕昇是**北宋**布衣工匠，于宋仁宗**庆历年间（1041–1048）**首创**胶泥活字印刷术**，列中国古代**四大发明**之一，完整记载于北宋**沈括《梦溪笔谈·技艺》**篇。其法以胶泥刻单字烧硬，铁板敷松脂、蜡与纸灰，置铁范排字、加热压平施印，印毕可拆版复用，革新雕版印刷一书一版之弊。元代**王祯**续创木活字与转轮排字盘。毕昇活字比德国**古登堡**15世纪中期铅活字早约**四百年**，推动人类知识大规模传播。","pts":["北宋庆历年间（1041–1048）毕昇发明胶泥活字","载于沈括《梦溪笔谈》，可拆版复用革雕版之弊","早于德国古登堡约400年，元代王祯续创木活字"],"mem":"工序四步口诀：**泥刻→火烧→蜡粘铁板→拆版复用**；人物串连：**北宋毕昇（泥）→北宋沈括（记）→元代王祯（木）→15世纪古登堡（铅，晚400年）**。","mix":"毕昇发明的是“胶泥活字”，非木活字或金属活字（木活字成熟与转轮排字盘归元代王祯《农书》）；雕版印刷始于唐代（现存最早标年雕版为868年唐咸通九年《金刚经》），勿与宋代活字混淆。","mcq":[{"q":"详细记载北宋庆历年间毕昇发明胶泥活字印刷术全过程的典籍是","o":["宋应星《天工开物》","贾思勰《齐民要术》","沈括《梦溪笔谈》","王祯《农书》"],"a":2,"w":"北宋沈括在《梦溪笔谈》卷十八《技艺》中完整记述了毕昇泥活字的制作与排版流程。"},{"q":"关于中国古代印刷术的演进，下列说法正确的是","o":["毕昇发明的是铜活字印刷术","唐代已出现成熟的泥活字印刷","毕昇活字印刷晚于德国古登堡铅活字","毕昇于北宋庆历年间发明胶泥活字，比古登堡早约四百年"],"a":3,"w":"毕昇于北宋庆历年间（1041–1048）发明胶泥活字，比15世纪中期古登堡铅活字早约400年。"}],"rel":[{"t":"印刷术","n":"活字印刷为印刷术核心飞跃"},{"t":"四大发明","n":"中国古代四大发明之一"},{"t":"《梦溪笔谈》","n":"毕昇发明的唯一原始文献记载"},{"t":"古登堡印刷术","n":"中西活字印刷对照，早约400年"},{"t":"造纸术","n":"与造纸术共同推动书籍传播"}],"exam":[]},{"id":"d07-003","t":"介子推与寒食节","cid":"07e","p":2,"kind":"人物","alias":["介之推","介子推","寒食节由来"],"one":"春秋晋国介子推随重耳流亡、隐居绵山焚死，晋文公设寒食禁火悼念。","ans":"介子推又称**介之推**，是**春秋晋国**贤臣，随流亡公子重耳（**晋文公**）在外十九年，传说曾**“割股奉君”**。重耳即位封赏时，他不言禄、携母隐居**绵山**（今**山西介休**），晋文公烧山逼仕致其抱柳焚死。晋文公悔痛，令每年此日**禁火冷食**悼念，成为**寒食节**（清明前一日或二日）的传统由来，唐宋后与清明节逐渐合流。","pts":["春秋晋国介子推随重耳流亡，传说“割股奉君”","不言禄隐居绵山（山西介休）抱树焚死","晋文公设禁火寒食悼念，后与清明节合流"],"mem":"地名人物一起记：介子推隐居归休之地叫**山西介休（绵山）**；故事四格漫画：**割股救主→不争封赏→烧山抱柳→禁火寒食**。","mix":"《左传·僖公二十四年》只载介之推“不言禄”隐居，无割股与焚死情节；“割股奉君”“抱木燔死”最早见于《庄子·盗跖》等战国诸子及汉代文献；学者也指出寒食习俗本身源起于古代仲春改火礼制。","mcq":[{"q":"传统民俗中，为悼念春秋晋国大臣介子推而设禁火冷食的节日是","o":["寒食节","上巳节","中元节","重阳节"],"a":0,"w":"晋文公为悼念焚死绵山的介子推，下令禁火寒食，成为寒食节由来。"}],"rel":[{"t":"寒食节与清明节","n":"寒食节人物传说与清明合流"},{"t":"春秋五霸","n":"晋文公重耳为春秋五霸之一"},{"t":"《左传》","n":"最早记载介之推不言禄隐居"},{"t":"《庄子》","n":"《盗跖》首见割股抱木焚死传说"},{"t":"端午节","n":"同为与历史人物关联的传统节日"}],"exam":[]},{"id":"d07-004","t":"夏商周断代工程","cid":"07b","p":3,"kind":"事件","alias":["夏商周年表"],"one":"1996年启动的攻关项目，2000年发布《夏商周年表》，定夏始约前2070年。","ans":"夏商周断代工程是**1996年**启动的“九五”国家科技攻关项目，融文献、考古、天文与**碳十四测年**攻关。**2000年**公布**《夏商周年表》**，定**夏始约前2070年**、商约前1600年、**武王克商前1046年**，前推中国信史纪年。","pts":["1996年启动、2000年公布《夏商周年表》","定夏始前2070、商前1600、克商前1046"],"mem":"四个核心年份顺口溜：**2070夏开端，1600商接班，1300盘庚迁，1046武王克商年**（全为公元前，衔接前841共和元年）。","mix":"莫与后续启动的“中华文明探源工程”（2001/2002年预研究，探寻五千多年文明起源）混淆；《夏商周年表》中部分上古年代在国际与国内学界仍存讨论。","mcq":[{"q":"2000年公布的《夏商周年表》将夏代始年与武王克商之年分别推定为","o":["约前2500年、前1122年","约前2070年、前1046年","约前1600年、前841年","约前2070年、前1300年"],"a":1,"w":"《夏商周年表》定夏始约前2070年、商始约前1600年、盘庚迁殷约前1300年、武王克商前1046年。"}],"rel":[{"t":"国人暴动与共和元年","n":"将前841年确切纪年大幅前推"},{"t":"夏朝","n":"推定夏代始年约前2070年"},{"t":"二里头遗址","n":"夏文化考古测年关键遗址"},{"t":"商朝与盘庚迁殷","n":"商始前1600、迁殷前1300"},{"t":"殷墟","n":"商代晚期甲骨与考古年代依据"}],"exam":[]},{"id":"d07-005","t":"侨批档案","cid":"07a","p":2,"kind":"常识","alias":["侨批","银信"],"one":"海外华侨寄回家乡的书信与汇款合一的凭证，2013年入选《世界记忆名录》。","ans":"侨批是**海外华侨通过民间渠道寄回国内、书信和汇款合在一起的凭证**，又称“银信”，主要来自**广东潮汕、福建闽南**等侨乡，记录了华侨在海外谋生和与家乡联系的历史。**2013年6月，广东、福建两省联合申报的“侨批档案”入选联合国教科文组织《世界记忆名录》**。侨批兼有家书和金融凭证两重价值，是研究华侨史、侨乡社会和近代金融的一手文献。2026年电影《给阿嬷的情书》以侨乡家书为题材，获第39届金鸡奖评委会特别奖。","pts":["华侨寄回国内的信款合一凭证，又称银信","广东潮汕、福建闽南侨乡","2013年广东、福建联合申报入选《世界记忆名录》"],"mem":"“**一封批，一份钱，一份情**”：信和钱装在一起寄回家。入选年份记“**13 年，粤闽联手**”。","mix":"侨批入选的是《世界记忆名录》（文献遗产），不是《世界遗产名录》或人类非遗代表作名录；我国入选《世界记忆名录》的还有《黄帝内经》《本草纲目》、南京大屠杀档案等。","mcq":[{"q":"2013年“侨批档案”入选的是联合国教科文组织的","o":["《世界遗产名录》","《世界记忆名录》","人类非物质文化遗产代表作名录","世界地质公园名录"],"a":1,"w":"侨批档案是文献遗产，2013年6月入选《世界记忆名录》。"}],"rel":[{"t":"世界记忆名录","n":"所入名录"},{"t":"第39届中国电影金鸡奖","n":"《给阿嬷的情书》获奖"},{"t":"人类非遗代表作中国项目","n":"另一名录体系"}],"more":"2013年6月：广东、福建联合申报的“侨批档案”入选《世界记忆名录》","exam":[]},{"id":"d07-201","t":"天一阁","cid":"07a","p":2,"kind":"地理","alias":["宁波天一阁"],"one":"明代兵部右侍郎范钦于1561年在浙江宁波建造，中国现存最古老私家藏书楼。","ans":"天一阁坐落于**浙江宁波**，由明代嘉靖年间兵部右侍郎**范钦**于**1561年（明嘉靖四十年）**始建，取《易经》“天一生水，地六成之”以水克火之意命名，是**中国现存最古老的私家藏书楼**。藏书以明代地方志和登科录见长，乾隆修《四库全书》亦多所进呈，并由余秋雨散文《风雨天一阁》传名。","pts":["浙江宁波，明代范钦1561年创筑","取意“天一生水”，寓意以水制火保护典籍","中国现存最古老的私家藏书楼（亚洲亦属最早梯队）"],"mem":"关键词：**宁波 + 明范钦 + 1561 + 天一生水（防火）+ 最古老私家藏书楼**。","mix":"注意定语限定：**“中国现存最古老的私家藏书楼”**，不可误作官府图书馆或国家书库；清代江南三阁（文澜、文宗、文汇）系皇家四库全书分阁，晚于天一阁两百多年。","mcq":[{"q":"宁波天一阁建于明代何人之手？楼名“天一”蕴含怎样的建筑防范功能寓意？","o":["范钦，以水克火","毛晋，防虫蛀","纪晓岚，防潮防霉","黄宗羲，防战火掠夺"],"a":0,"w":"天一阁由明代范钦于1561年建，取《易》“天一生水，地六成之”典故，寓意以水防火护书。"}],"rel":[{"t":"余秋雨《文化苦旅》","n":"代表篇目《风雨天一阁》专写天一阁护书史"},{"t":"黄宗羲","n":"清初第一位被允许登阁阅书的外姓学者"}],"exam":[]},{"id":"d07-202","t":"近代四大文献发现","cid":"07b","p":2,"kind":"合称","alias":["四大文献发现","近代四大文化发现"],"one":"清末民初四大史料重见天日：殷墟甲骨、居延汉简、敦煌遗书与明清内阁大库档案。","ans":"近代四大文献发现指19世纪末至20世纪初惊动学界的四批大型实物文字资料：**河南安阳殷墟甲骨（将信史推前至商代）、内蒙古甘肃居延汉简（西北屯戍边塞文书）、甘肃敦煌莫高窟藏经洞遗书（4至11世纪多语种写本）与明清内阁大库档案（清末险些销毁的“八千麻袋”大内旧档）**。**王国维、陈寅恪**等借此以“二重证据法”推动近代史学革新。","pts":["四大发现：殷墟甲骨、居延汉简、敦煌遗书、明清大库档案","推动清末民初“二重证据法”与现代史学转型","直接催生甲骨学、敦煌学、简牍学等新兴显学"],"mem":"口诀：**一甲二简三卷四档**（商代甲骨、汉代居延简、唐宋敦煌卷、明清大库档）。","mix":"务必区分“近代四大文献发现”（4项，含居延汉简、明清档案）与“近代三大显学”（3项：甲骨学、敦煌学、红学），后者含文学考证领域的《红楼梦》研究。","mcq":[{"q":"下列哪项不属于“近代中国四大文化（文献）发现”？","o":["安阳殷墟甲骨","湖北云梦秦简","居延汉简","明清大库档案"],"a":1,"w":"清末民初的四大发现习惯指殷墟甲骨、居延汉简、敦煌遗书、明清大库档案；睡虎地等秦汉简系1970年代后新出土，不在此清末民初四项内。"}],"rel":[{"t":"近代三大显学","n":"甲骨、敦煌由四大发现衍生，加上红学"},{"t":"甲骨文","n":"四大发现中年代最早的商代文字材料"},{"t":"敦煌藏经洞","n":"1900年王圆箓道士发现的佛教与多语种文献宝库"}],"members":[["殷墟甲骨","河南安阳商代甲骨刻辞"],["居延汉简","西北居延地区汉代屯戍档案简牍"],["敦煌遗书","莫高窟藏经洞千年宗教世俗写卷"],["明清档案","内阁大库“八千麻袋”皇家旧档"]],"exam":[]},{"id":"d07-203","t":"近代三大显学","cid":"07b","p":2,"kind":"合称","alias":["三大显学"],"one":"20世纪中国最受中外学界瞩目的三门人文专学：甲骨学、敦煌学与红学。","ans":"**近代三大显学**指近百年来在海内外学术界资料最富、学者最众、影响最广的三门专项人文学科：**以殷墟甲骨卜辞为核心的甲骨学、以莫高窟藏经洞写卷及壁画为核心的敦煌学，以及围绕古典小说《红楼梦》展开的红学**。前二者依托地下考古出土新史料，红学则立足传世小说与版本家世考证。","pts":["三门专学：甲骨学、敦煌学、红学","甲骨与敦煌属文献新发现驱动，红学立足小说与考证","甲骨学有“甲骨四堂”，新红学由胡适、俞平伯开创"],"mem":"记住极简口诀：**甲（骨）、敦（煌）、红（楼梦）**，“一商一唐一清”。","mix":"区分“先秦显学”（《韩非子》“世之显学，儒、墨也”）与“近代三大显学”（甲骨学、敦煌学、红学）；“四大文献发现”中有简牍与明清档案，“三大显学”却无档案而含红学。","mcq":[{"q":"通常并称的“近代三大显学”包括甲骨学、敦煌学以及哪一门专学？","o":["简牍学","明清档案学","红学","金石学"],"a":2,"w":"近代三大显学即甲骨学、敦煌学、红学，涵盖考古文字、丝路写本与古典名著三大支柱领域。"}],"rel":[{"t":"近代四大文献发现","n":"甲骨、敦煌学赖以勃兴的文献源头"},{"t":"红学","n":"专门研究《红楼梦》的显学"},{"t":"甲骨四堂","n":"王国维、罗振玉、郭沫若、董作宾四位甲骨学宗师"}],"members":[["甲骨学","研究商代殷墟甲骨刻辞"],["敦煌学","研究敦煌写本、石窟艺术与丝路史"],["红学","专门研究《红楼梦》文本与版本考证"]],"exam":[]},{"id":"d07-204","t":"《夏小正》","cid":"07d","p":2,"kind":"作品","alias":["夏小正"],"one":"收于《大戴礼记》第47篇，按十二月分记星象、物候与农事，中国现存最早历书。","ans":"《夏小正》原是相传记录夏代岁时的古老月令文献，后被西汉戴德编入**《大戴礼记》第47篇**得以保存。全篇不过四百余字，按**农历一月至十二月逐月记述天文星象、气候物候、动植物变化与农耕政事**，是**中国现存最早的一部完整月令体农事历书**，为后世《礼记·月令》之祖。","pts":["现存于汉代《大戴礼记》（区别于五经之一的《小戴礼记》）","逐月记录星象、物候、草木鸟兽与农事活动","中国现存最早的农事历谱与物候文献"],"mem":"重点配对：**《夏小正》藏身《大戴礼记》**，对比五经中的《礼记》（戴圣所编《小戴礼记》）。","mix":"常考《大戴礼记》与《小戴礼记》区分：通行五经《礼记》是戴圣编《小戴礼记》（内含《大学》《中庸》《学记》《月令》）；戴德所编《大戴礼记》虽未入五经，却保存了最古历书《夏小正》。","mcq":[{"q":"我国现存最早的农事历书《夏小正》如今保存于哪一部先秦汉儒礼书汇编？","o":["《仪礼》","《周礼》","《小戴礼记》（《礼记》）","《大戴礼记》"],"a":3,"w":"《夏小正》作为第47篇保存于汉代戴德所编《大戴礼记》中，而非戴圣所编的《小戴礼记》。"}],"rel":[{"t":"《礼记》","n":"戴圣所编《小戴礼记》，与戴德《大戴礼记》并称大小戴"},{"t":"二十四节气","n":"同属中国古代观象授时农事历法系统"}],"exam":[]},{"id":"d07-205","t":"立春习俗","cid":"07d","p":2,"kind":"常识","alias":["立春","咬春","鞭春牛"],"one":"二十四节气之首，太阳到达黄经315°（公历2月3至5日），有迎春、打春、咬春等俗。","ans":"立春位列**二十四节气之首**，标志太阳到达**黄经315°**（每年公历2月3至5日之间），象征天文春季开端与阳气回升。民间与古代官府历来重视立春仪礼，习俗包括**官方“迎春”祭句芒、象征劝农的“鞭春牛（打春）”、民间啃萝卜与吃春饼的“咬春”**，体现重农迎新传统。","pts":["二十四节气第一气，太阳到达黄经315°","主要民俗：迎春、鞭春牛（打春劝农）、咬春（春饼萝卜）","节气按阳历定，故与农历正月初一春节日期不同步"],"mem":"数字+三动作：**黄经315°（立春）+ 迎春、打春（鞭春牛）、咬春**。","mix":"小寒大寒黄经分别为**285°与300°**（外部资料有295°/310°之误），而立春恰好为**315°**（此后雨水330°、惊蛰345°、春分0°）；春节是农历，立春是阳历节气，有些年份会出现“无春年”或“两头春”。","mcq":[{"q":"二十四节气之首“立春”时，太阳位于黄经多少度？传统吃萝卜春卷称为何种民俗？","o":["黄经315°，咬春","黄经300°，尝新","黄经330°，祭芒","黄经0°，踏青"],"a":0,"w":"大寒为黄经300°，立春在黄经315°（每15度一气），民间吃萝卜、春饼的习俗称为“咬春”。"}],"rel":[{"t":"二十四节气","n":"二十四节气总体体系与《淮南子》记载"},{"t":"二十四节气中的“四立二分二至”","n":"立春为四立之首"}],"exam":[]},{"id":"d07-206","t":"除夕与传统四大祭祖节","cid":"07e","p":2,"kind":"常识","alias":["除夕","四大祭祖节"],"one":"农历腊月最后一日夜晚，除旧布新守岁吃年夜饭；并与清明、中元、重阳并称四大祭祖节。","ans":"除夕指农历年终岁末的最后一天夜晚（腊月三十或二十九），又称大年夜、年除夜，核心年俗涵盖**贴春联挂桃符、阖家吃团圆饭（年夜饭）、给压岁钱、通宵守岁与饮屠苏酒**。民俗学中，除夕与**清明节（三月初）、中元节（七月半）、重阳节（九月初九）**并称为中国传统**四大祭祖节日**。","pts":["农历腊月最后一夜，2025年起已正式列入法定节假日（春节休假首日）","核心习俗：团圆饭、守岁、贴春联、压岁钱、辞旧迎新","四大祭祖节合称：除夕、清明、中元、重阳"],"mem":"四大祭祖节口诀：“**年（除夕）清（明）中（元）重（阳）**”，皆有祭拜先祖习俗。","mix":"自2025年1月1日起施行的《全国年节及纪念日放假办法》修正案，正式把**农历除夕与5月2日**纳入全体公民法定节假日，春节放假增至4天，与此前除夕不单列放假有别。","mcq":[{"q":"在传统民俗分类中，除下列哪一项外，其余三节与除夕并称为中国传统“四大祭祖节”？","o":["清明节","中秋节","中元节","重阳节"],"a":1,"w":"中国传统四大祭祖大节指除夕、清明、中元、重阳；中秋节主题在于赏月与家人团圆。"}],"rel":[{"t":"法定节假日","n":"2025年起除夕正式列入法定假日"},{"t":"春节列入人类非遗代表作名录","n":"2024年以整体社会实践名义申遗"}],"exam":[]},{"id":"d07-207","t":"龙抬头（二月二）","cid":"07e","p":2,"kind":"常识","alias":["二月二龙抬头","春耕节"],"one":"农历二月初二传统民俗节日，又称春耕节、农事节，对应惊蛰前后苍龙星象东升。","ans":"龙抬头又称**“二月二”、春耕节、农事节或青龙节**，日期固定在**农历二月初二**。此时约值公历惊蛰前后，**东方苍龙七宿（角宿，象征龙头）于黄昏从东方地平线缓缓升起**，气温转暖、雨水增多，农耕随之全面开启。民俗传统有**剃龙头、吃龙须面/水饺（“龙耳”）、撒灰引龙**等。","pts":["农历二月初二，又称春耕节、农事节","天文依据：春夜东方苍龙七宿首星（角宿）东升","民间俗称剃龙头，祈愿一年风调雨顺、开运顺遂"],"mem":"口诀“二月二龙抬头：青龙角宿上天东，民间剃头忙春耕”。","mix":"注意“龙抬头”的天文源流指中国古代二十八宿中东方苍龙第一宿角宿在黄昏露出地平线；农历二月初二还被唐宋部分时期设为中和节或挑菜节。","mcq":[{"q":"农历二月初二“龙抬头”除寓意春耕开始外，其“龙头”在古天文观象中对应哪组星象的升起？","o":["北斗七星斗柄","西方白虎七宿","东方苍龙七宿的角宿","太阳进入春分点"],"a":2,"w":"每年仲春二月初二前后黄昏，东方苍龙七宿第一宿“角宿”（象征龙角与龙头）从东方地平线升起，故名“龙抬头”。"}],"rel":[{"t":"二十四节气","n":"二月二常临近惊蛰、春分农事节点"},{"t":"中国农民丰收节","n":"二月二祈求春耕起步，丰收节礼赞秋分获收"}],"exam":[]},{"id":"d07-208","t":"中国农民丰收节","cid":"07e","p":2,"kind":"常识","alias":["农民丰收节"],"one":"2018年经国务院批复设立，定在每年农历秋分，我国首个专门为农民设立的节日。","ans":"中国农民丰收节经党中央批准、国务院批复，于**2018年**正式设立，并将日期固定在**每年农历秋分日**（阳历9月22至24日前后）。这是**我国历史上第一个在国家层面专门为亿万农民设立的法定节日**，契合春华秋实、五谷丰登时令，旨在提升农民获得感并展示农业农村现代化成果。","pts":["2018年设立，每年秋分举办","首个国家层面专门为农民设立的节日","农时对应秋收与“二分”之秋分"],"mem":"口诀：“**18年设立，秋分农民过丰收**”（恰呼应秋分昼夜平分、五谷收获）。","mix":"日期按**二十四节气中的秋分**（并非固定农历八月十五中秋，也不是夏至）决定，所以阳历日期通常在9月22日至24日微动。","mcq":[{"q":"2018年设立的我国首个专门为农民设立的节日“中国农民丰收节”，固定在哪个节气？","o":["处暑","白露","霜降","秋分"],"a":3,"w":"经国务院批复同意，自2018年起将每年农历（即二十四节气）秋分设立为中国农民丰收节。"}],"rel":[{"t":"二十四节气中的“四立二分二至”","n":"秋分兼具天文学昼夜等分与丰收节意义"},{"t":"全国生态日","n":"同为新时代新设国家主题日（8月15日）"}],"exam":[]},{"id":"d07-209","t":"中国古代四大美女","cid":"07f","p":2,"kind":"合称","alias":["四大美女"],"one":"春秋西施、西汉王昭君、东汉末貂蝉、唐代杨玉环，对应沉鱼、落雁、闭月、羞花。","ans":"中国古代四大美女指**西施（春秋越国）、王昭君（西汉和亲）、貂蝉（东汉末《三国演义》人物）与杨玉环（唐代杨贵妃）**，民间以**“沉鱼、落雁、闭月、羞花”**四组典故相称：西施浣纱沉鱼，昭君出塞落雁，貂蝉拜月闭月，杨贵妃赏花羞花。除貂蝉属文学塑造外，其余三人皆见史载。","pts":["西施（沉鱼）、王昭君（落雁）、貂蝉（闭月）、杨玉环（羞花）","历史顺序跨越春秋、西汉、东汉末（文学虚构）、盛唐","沉鱼落雁源于《庄子》，后附会给西施与昭君"],"mem":"字头+时代序：“**西施（春秋鱼）、昭君（汉雁）、貂蝉（汉末月）、杨贵妃（唐花）**”。","mix":"“沉鱼落雁”原词出自《庄子·齐物论》“毛嫱丽姬，人之所美也，鱼见之深入，鸟见之高飞”，后世民间演义将其分贴给西施与王昭君；四大美女中**唯貂蝉非正史真实人物**。","mcq":[{"q":"四大美女中，传说典故与“落雁”及“闭月”分别对应哪两位？","o":["王昭君与貂蝉","西施与貂蝉","王昭君与杨玉环","西施与杨玉环"],"a":0,"w":"通常顺次对应为：西施沉鱼、王昭君落雁、貂蝉闭月、杨玉环羞花。"}],"rel":[{"t":"《长生殿》","n":"写杨玉环与唐玄宗故事"},{"t":"《汉宫秋》与《梧桐雨》","n":"《汉宫秋》写汉元帝与王昭君出塞，《梧桐雨》写杨玉环故事"}],"members":[["西施","春秋，浣纱沉鱼"],["王昭君","西汉，出塞落雁"],["貂蝉","东汉末演义人物，拜月闭月"],["杨玉环","唐代，赏花羞花"]],"exam":[]},{"id":"d07-210","t":"中国古代四大才女","cid":"07f","p":2,"kind":"合称","alias":["四大才女"],"one":"主流指蔡文姬、李清照、卓文君、上官婉儿（一说以东汉史家班昭代卓或上官）。","ans":"中国古代四大才女通行指通晓文史音律的四位女性人物：**东汉蔡文姬（精通音律，作《悲愤诗》及传作《胡笳十八拍》）、南宋李清照（婉约词宗“千古第一才女”）、西汉卓文君（善鼓琴，传《白头吟》）与唐代上官婉儿（掌诏命品评诗文，称“巾帼宰相”）**。另有一说把修《汉书》的**东汉班昭**列为四大才女之一。","pts":["主流四位：卓文君、蔡文姬、上官婉儿、李清照","另一通行口径含补修《汉书》与著《女诫》的东汉班昭","代表人物作品：《悲愤诗》《漱玉词》等"],"mem":"按朝代记：**西汉（卓文君）、东汉（蔡文姬/班昭）、唐（上官婉儿）、宋（李清照）**。","mix":"注意区分“四大才女”（多考李清照、蔡文姬、卓文君、上官婉儿/班昭）与“四大美女”（西施等）；如选项中出现班昭，通常属于合理变体口径，而林徽因、张爱玲属现代才女。","mcq":[{"q":"下列哪部作品是东汉才女蔡文姬流传下来的代表诗作（不含后世争议托名乐府）？","o":["《声声慢》","《悲愤诗》","《女诫》","《白头吟》"],"a":1,"w":"蔡文姬代表作为五言/骚体《悲愤诗》（传另有《胡笳十八拍》）；《女诫》为班昭所著，《白头吟》传为卓文君所作。"}],"rel":[{"t":"李清照","n":"宋代“千古第一才女”，婉约词大家"},{"t":"《汉书》","n":"东汉班昭曾续补其兄班固未竟之《汉书》八表及天文志"},{"t":"班固","n":"《汉书》主纂者，才女班昭（曹大家）之兄"}],"members":[["卓文君","西汉，善琴能诗"],["蔡文姬","东汉末，《悲愤诗》《胡笳十八拍》"],["上官婉儿","唐代，内舍人品评诗文"],["李清照","宋代，“千古第一才女”"]],"exam":[]}],"tables":[{"name":"中国首批世界遗产（1987年）","note":"中国1985年加入《保护世界文化和自然遗产公约》。2024选择的回忆措辞存疑，按“首批六项”整体掌握。","rows":[["项目","类型","所在地"],["长城","文化遗产","北方多省"],["明清皇宫（北京故宫，2004年增沈阳故宫）","文化遗产","北京"],["莫高窟","文化遗产","甘肃敦煌"],["秦始皇陵及兵马俑坑","文化遗产","陕西西安"],["周口店北京人遗址","文化遗产","北京"],["泰山","文化与自然双遗产（中国第一个双遗产）","山东泰安"]]},{"name":"中国四大石窟","note":"","rows":[["石窟","所在地","开凿时代","特点"],["莫高窟","甘肃敦煌","前秦（366年）始凿","壁画与彩塑，飞天；藏经洞文书；1987年列入世界遗产"],["云冈石窟","山西大同","北魏","早期大像，“昙曜五窟”，带犍陀罗风格；2001年列入世界遗产"],["龙门石窟","河南洛阳","北魏孝文帝迁都洛阳后开凿，盛于唐","卢舍那大佛（武则天时期）；2000年列入世界遗产"],["麦积山石窟","甘肃天水","后秦开凿","泥塑闻名，“东方雕塑陈列馆”；作为丝绸之路组成部分列入世界遗产"]]},{"name":"六大茶类","note":"","rows":[["茶类","发酵程度","代表茶"],["绿茶","不发酵","西湖龙井、碧螺春、黄山毛峰"],["白茶","微发酵","白毫银针、白牡丹"],["黄茶","轻发酵（闷黄）","君山银针"],["青茶（乌龙茶）","半发酵","安溪铁观音、武夷大红袍、冻顶乌龙"],["红茶","全发酵","祁门红茶、正山小种"],["黑茶","后发酵","安化黑茶、普洱熟茶"]]},{"name":"天干地支与二十四节气","note":"","rows":[["项目","内容"],["十天干","甲、乙、丙、丁、戊、己、庚、辛、壬、癸"],["十二地支","子、丑、寅、卯、辰、巳、午、未、申、酉、戌、亥（对应鼠牛虎兔龙蛇马羊猴鸡狗猪）"],["二十四节气（春夏）","立春、雨水、惊蛰、春分、清明、谷雨；立夏、小满、芒种、夏至、小暑、大暑"],["二十四节气（秋冬）","立秋、处暑、白露、秋分、寒露、霜降；立冬、小雪、大雪、冬至、小寒、大寒"]]},{"name":"中国传统节日","note":"","rows":[["节日","时间","主要习俗与相关诗文"],["春节","正月初一","守岁、贴春联、饮屠苏；王安石《元日》"],["元宵节","正月十五","赏灯、吃元宵、猜灯谜；辛弃疾《青玉案·元夕》"],["上巳节","三月初三","水边祓禊、踏青；王羲之等兰亭修禊作《兰亭集序》，杜甫《丽人行》“三月三日天气新”"],["寒食节、清明节","冬至后105日；清明为节气","禁火冷食（纪念介子推）；扫墓踏青；杜牧《清明》"],["端午节","五月初五","赛龙舟、吃粽子、挂艾草，纪念屈原"],["七夕节","七月初七","牛郎织女，乞巧；秦观《鹊桥仙》"],["中秋节","八月十五","赏月、吃月饼；苏轼《水调歌头》"],["重阳节","九月初九","登高、插茱萸、赏菊；王维《九月九日忆山东兄弟》"]]}]});